# ── 17 Murmuration ───────────────────────────────────────────────────────
#
# Thousands of starlings over winter fields at sunset. What to look at:
#   - one flock of 4,500 birds (Up / Down change it, to 12,000), flocking off
#     a spatial grid in the `jengine-swarm` package - each bird steers by its
#     two dozen nearest neighbours and nothing crosses the script bridge per
#     bird;
#   - the flock wheels after a point the script moves (the package's
#     `target_x` / `target_y`), folding and stretching as it turns;
#   - every bird flaps on its own phase - a height swing, no animation;
#   - the falcon follows the mouse (or hunts by itself when the mouse is
#     still), and every bird near it flees - a hole tears through the flock
#     and closes behind it.

MURM_COUNT = 4500
MURM_BIRD = lin(0.07, 0.05, 0.08)


def murmuration():
    ents = [camera()]
    ents.append(ent("Sky", transform=tr(0, 0),
                    sprite=sprite("sprites/env/murm_sky.png", (W + 200, H + 100), (1.0, 1.0, 1.0, 1.0), z=-100)))
    ents.append(ent("SunGlow", transform=tr(-260, -170),
                    sprite=sprite("sprites/fx/glow.png", (900, 520), emissive(lin(1.0, 0.72, 0.4, 0.55), 1.3), z=-98),
                    material=additive()))
    ents.append(ent("Sun", transform=tr(-260, -170),
                    sprite=sprite("sprites/fx/soft_dot.png", (120, 120), emissive(lin(1.0, 0.86, 0.6), 2.2), z=-97)))
    for i, (y, sy, alpha, speed) in enumerate(((210, 170, 0.55, 6.0), (120, 120, 0.35, 11.0))):
        ents.append(ent(f"Clouds{i + 1}", transform=tr(0, y),
                        sprite=sprite("sprites/env/murm_clouds.png", (W + 1200, sy), lin(1.0, 0.8, 0.75, alpha), z=-96 + i,
                                      fill={"mode": "tile", "tile_size": [1024.0, sy]}),
                        velocity={"x": speed, "y": 0.0}))
    far = ent("FieldsFar", transform=tr(120, -390),
              sprite=sprite("sprites/env/murm_fields.png", (W + 300, 330), lin(0.45, 0.32, 0.40), z=-60,
                            anchor=(0.5, 0.0), fill={"mode": "tile", "tile_size": [1100.0, 330.0]}))
    ents.append(far)
    ents.append(ent("Fields", transform=tr(0, -370),
                    sprite=sprite("sprites/env/murm_fields.png", (W + 300, 200), (1.0, 1.0, 1.0, 1.0), z=-40,
                                  anchor=(0.5, 0.0), fill={"mode": "tile", "tile_size": [1024.0, 200.0]})))
    for i, (x, size) in enumerate(((330, 330), (470, 250), (-520, 280))):
        ents.append(ent(f"Tree{i + 1}", transform=tr(x, -300),
                        sprite=sprite("sprites/env/murm_tree.png", (size, size), (1.0, 1.0, 1.0, 1.0), z=-35, anchor=(0.5, 0.0))))
    ents.append(ent("Flock", transform=tr(),
                    swarm_spawner={
                        "count": MURM_COUNT, "half_width": 900.0, "half_height": 330.0, "max_speed": 210.0,
                        "neighbor_radius": 36.0, "separation_radius": 9.0, "separation": 1.1,
                        "alignment": 1.1, "cohesion": 0.8, "max_neighbors": 20,
                        "size": 11.0, "color": MURM_BIRD, "texture_id": "sprites/fx/starling.png",
                        "z_order": -20, "flap": 7.0, "target_pull": 170.0, "threat_strength": 1600.0},
                    Swarm={"count": MURM_COUNT, "target_x": 0.0, "target_y": 80.0, "target_pull": 170.0,
                           "threat_x": 0.0, "threat_y": 0.0, "threat_radius": 0.0}))
    ents.append(ent("Falcon", transform=tr(500, 250),
                    sprite=sprite("sprites/fx/falcon.png", (42, 42), lin(0.05, 0.035, 0.05), z=-10)))
    ents += caption_entities(
        "17   Murmuration",
        "Mouse  the falcon   Up / Down  more or fewer birds   Space  falcon on / off   1-4 post   Tab captions")
    ents.append(ent("Driver", transform=tr(), script=script("scripts/s17_murmuration.lua")))
    # Version 2: the flock is a package component, and a v1 scene loads
    # into a core-only bundle that drops it without a word.
    return {
        "version": 2,
        "name": "17 - Murmuration",
        "post_process": post(
            bloom={"threshold": 0.9, "intensity": 0.35, "blur_size": 0.0},
            vignette={"intensity": 0.35, "smoothness": 0.6, "color": [0.08, 0.02, 0.06, 1.0]},
            grade={"brightness": 1.0, "contrast": 1.05, "saturation": 1.1, "tint": [1.0, 0.9, 0.85, 0.05]},
            chromatic={"strength": 0.0015, "on": False}),
        "entities": ents,
    }



# ── 19 God Rays ──────────────────────────────────────────────────────────
#
# A forest at morning, the sun low behind the canopy. What to look at:
#   - the shafts: `light_shafts` marches every pixel toward the sun and
#     gathers the bright sky it crosses, so each gap in the leaves throws a
#     beam across the air, and every trunk and hanging clump cuts one;
#   - move the mouse and the sun moves - the beams swing to follow it,
#     fanning out when it is high and raking low through the trunks;
#   - dust motes hang in the air and leaves drift down on a turbulent
#     breeze, dark against the light;
#   - three rows of trunks fade into the haze, lit from behind.
# G turns the shafts off to see what they add; Space sends a gust.

GR_SUN = (380.0, 250.0)
GR_SKY = 1.15                 # a little past white; the sun is what casts


def gr_row(prefix, xs, scale, colour, z):
    out = []
    # Trunks of a few girths, so a row reads as a wood and not a fence.
    girth = (1.0, 0.8, 1.2, 0.9, 1.1, 0.75)
    for i, x in enumerate(xs):
        out.append(ent(f"{prefix}{i + 1}", transform=tr(x, -H / 2 - 20),
                       sprite=sprite("sprites/env/gr_trunk.png", (96 * scale * girth[i % 6], H + 80), colour, z=z,
                                     anchor=(0.5, 0.0))))
    return out


def god_rays():
    ents = [camera()]
    ents.append(ent("Sky", transform=tr(0, 20),
                    sprite=sprite("sprites/env/gr_sky.png", (W + 300, H + 200), emissive([1.0, 1.0, 1.0, 1.0], GR_SKY),
                                  z=-100)))
    sx, sy = GR_SUN
    ents.append(ent("Haze", transform=tr(0, 20),
                    sprite=sprite("sprites/env/gr_haze.png", (W + 300, H + 200), lin(0.88, 0.80, 0.64), z=-90)))
    ents.append(ent("SunGlow", transform=tr(sx, sy),
                    sprite=sprite("sprites/fx/glow.png", (760, 760), emissive(lin(1.0, 0.85, 0.55, 0.8), 1.6), z=-86),
                    material=additive()))
    ents.append(ent("Sun", transform=tr(sx, sy),
                    sprite=sprite("sprites/fx/soft_dot.png", (170, 170), emissive(lin(1.0, 0.95, 0.8), 7.0), z=-85)))
    # Three rows of trunks, the far ones pale in the haze.
    ents += gr_row("TrunkFar", (-610, -410, -170, 40, 250, 520), 0.55, lin(0.80, 0.72, 0.58), -80)
    ents.append(ent("CanopyBack", transform=tr(-200, H / 2 + 30),
                    sprite=sprite("sprites/env/gr_canopy.png", (W + 600, 380), lin(0.55, 0.52, 0.40), z=-75,
                                  anchor=(0.5, 1.0), fill={"mode": "tile", "tile_size": [900.0, 380.0]})))
    ents += gr_row("TrunkMid", (-500, -300, 130, 610), 0.8, lin(0.30, 0.27, 0.22), -60)
    ents += gr_row("TrunkNear", (-130, 440), 1.0, lin(0.05, 0.045, 0.04), -40)
    ents.append(ent("Canopy", transform=tr(80, H / 2 + 20),
                    sprite=sprite("sprites/env/gr_canopy.png", (W + 600, 420), lin(0.06, 0.08, 0.05), z=-30,
                                  anchor=(0.5, 1.0), fill={"mode": "tile", "tile_size": [1024.0, 420.0]}),
                    oscillator={"amplitude": [8.0, 3.0], "frequency": [0.13, 0.21], "phase": [0.0, 0.0]}))
    ents.append(ent("Floor", transform=tr(0, -H / 2 - 20),
                    sprite=sprite("sprites/env/gr_floor.png", (W + 400, 250), lin(0.05, 0.06, 0.04), z=-20,
                                  anchor=(0.5, 0.0), fill={"mode": "tile", "tile_size": [1024.0, 250.0]})))
    ents.append(ent("Dust", transform=tr(0, 0), particle_emitter=emitter(
        emit_shape={"kind": "rect", "size": [W + 100.0, H + 100.0]},
        emission_rate=30.0, max_particles=400, lifetime=[8.0, 14.0], speed=[2.0, 10.0],
        size_start=[2.0, 4.0], size_end=[2.0, 4.0],
        color_curve=[[0.0] + lin(1.0, 0.92, 0.75, 0.0), [0.2] + lin(1.0, 0.92, 0.75, 0.5),
                     [0.8] + lin(1.0, 0.92, 0.75, 0.5), [1.0] + lin(1.0, 0.92, 0.75, 0.0)],
        turbulence={"strength": 14.0, "scale": 160.0, "speed": 0.1}, z_order=-35)))
    ents.append(ent("Leaves", transform=tr(0, H / 2 - 40), particle_emitter=emitter(
        texture_id="sprites/fx/gr_leaf.png", emit_shape={"kind": "line", "length": W + 200.0},
        emission_rate=4.0, max_particles=120, lifetime=[9.0, 14.0], speed=[10.0, 30.0], angle=[4.2, 5.2],
        size_start=[12.0, 18.0], size_end=[12.0, 18.0], angular_velocity=[-2.5, 2.5],
        color_curve=[[0.0] + lin(0.12, 0.14, 0.06, 0.0), [0.1] + lin(0.12, 0.14, 0.06, 1.0),
                     [0.9] + lin(0.16, 0.14, 0.06, 1.0), [1.0] + lin(0.16, 0.14, 0.06, 0.0)],
        gravity_modifier=0.08, drag=0.6,
        turbulence={"strength": 45.0, "scale": 180.0, "speed": 0.2}, z_order=-25)))
    ents += caption_entities(
        "19   God Rays",
        "Mouse  the sun   G  light shafts   Space  a gust   1-4 post   Tab captions")
    ents.append(ent("Driver", transform=tr(), script=script("scripts/s19_god_rays.lua")))
    pp = post(
        hdr={"tonemap": "aces", "exposure": 0.95},
        bloom={"threshold": 1.2, "intensity": 0.6, "blur_size": 0.0},
        vignette={"intensity": 0.4, "smoothness": 0.6, "color": [0.05, 0.03, 0.0, 1.0]},
        grade={"brightness": 1.0, "contrast": 1.06, "saturation": 1.1, "tint": [1.0, 0.92, 0.8, 0.08]},
        chromatic={"strength": 0.0015, "on": False})
    # The shafts go first: they read the frame's own light, before bloom.
    pp["effects"].insert(0, {"name": "light_shafts", "enabled": True, "params": {
        "source_x": {"Float": sx}, "source_y": {"Float": sy}, "length": {"Float": 1.6},
        "intensity": {"Float": 2.6}, "decay": {"Float": 0.99}, "threshold": {"Float": 1.4},
        "color": {"Vec4": [1.0, 0.9, 0.7, 1.0]}}})
    return {"name": "19 - God Rays", "post_process": pp, "entities": ents}



# ── 20 Storm ─────────────────────────────────────────────────────────────
#
# A village street at night in a storm. What to look at:
#   - the rain lands: every drop hits the roofs, the walls and the street -
#     real colliders, the same shapes physics uses - and dies there, and a
#     sub-emitter bursts a splash where it landed. Nothing in the script
#     knows where a roof is;
#   - the lightning: the whole street lights for a flicker - ambient light,
#     sky and puddles together - and the bolt forks down behind the cloud;
#   - the gusts: the rain swings to a new slant (`Particles.set` on its
#     angle) and the grass along the verge - a mesh reshaped every frame -
#     bends flat and springs back;
#   - the lamp and the windows light the wet street and the rain that
#     passes them.
# L calls lightning, G a gust, R stops and starts the rain.

ST_GROUND = -200.0            # the street's top edge: where the houses stand
ST_RAIN_ANGLE = -1.40         # radians: down, leaning with the wind
# name, texture, x, (w, h), roof height (px), windows as (x0, y0, x1, y1) px
ST_HOUSES = [
    ("HouseA", "st_house_a", -440.0, (300, 440), 150, [(60, 210, 110, 280), (190, 210, 240, 280), (60, 320, 110, 390)]),
    ("HouseB", "st_house_b", -70.0, (400, 320), 130, [(70, 180, 140, 240), (260, 180, 330, 240)]),
    ("HouseC", "st_house_c", 300.0, (240, 380), 120, [(90, 170, 150, 240), (90, 280, 150, 340)]),
]
ST_LAMP = (540.0, ST_GROUND)


def st_house(name, tex, x, size, roof, windows, lit, door=None):
    w, h = size
    wall_h = h - roof
    # Its colliders, in the entity's frame (origin at its foot): the walls a
    # box, the gable a triangle from eave to eave - the eaves overhang.
    walls = {"shape": {"Box": {"width": float(w - 16), "height": float(wall_h)}},
             "offset": [0.0, wall_h / 2.0]}
    out = [ent(name, transform=tr(x, ST_GROUND),
               sprite=sprite(f"sprites/env/{tex}.png", (w, h), lin(0.42, 0.42, 0.48), z=-40, anchor=(0.5, 0.0)),
               collider=walls)]
    out.append(ent(f"{name}Roof", transform=tr(x, ST_GROUND), collider={
        "shape": {"ConvexPolygon": {"vertices": [[-w / 2.0, wall_h - 4.0], [w / 2.0, wall_h - 4.0], [0.0, float(h)]]}}}))
    if door:
        x0, y0, x1, y1 = door
        out.append(ent(f"{name}Door", transform=tr(x - w / 2 + (x0 + x1) / 2, ST_GROUND + h - (y0 + y1) / 2),
                       sprite=sprite("sprites/env/st_window.png", (x1 - x0 + 4, y1 - y0 + 2), lin(0.10, 0.07, 0.05),
                                     z=-41)))
    for i, (x0, y0, x1, y1) in enumerate(windows):
        cx = x - w / 2 + (x0 + x1) / 2
        cy = ST_GROUND + h - (y0 + y1) / 2
        on = lit[i] if i < len(lit) else True
        # A lit window glows (unlit); a dark one is glass the lightning shows.
        window = dict(transform=tr(cx, cy),
                      sprite=sprite("sprites/env/st_window.png", (x1 - x0 + 6, y1 - y0 + 6),
                                    emissive(lin(1.0, 0.85, 0.6), 1.8) if on else lin(0.10, 0.12, 0.18), z=-41))
        if on:
            window["unlit"] = {}
        out.append(ent(f"{name}Window{i + 1}", **window))
        if on:
            out.append(ent(f"{name}Glow{i + 1}", transform=tr(cx, cy - 30),
                           point_light=point_light(lin(1.0, 0.7, 0.4), 1.6, 320, 1.4, shadows=False)))
    return out


def storm():
    ents = [camera()]
    ents.append(ent("Ambient", transform=tr(),
                    ambient_light={"color": lin(0.45, 0.52, 0.75)[:3], "intensity": 0.42}))
    ents.append(ent("Sky", transform=tr(0, 60),
                    sprite=sprite("sprites/env/st_sky.png", (W + 300, H + 200), lin(0.9, 0.9, 1.0), z=-100),
                    unlit={}))
    # Two banks of cloud rolling by, the far one slower and paler; each is
    # tiled 1024 wide and wraps by exactly that, so the jump is invisible.
    for name, y, tint, speed, z in (("CloudsFar", 250.0, lin(0.42, 0.45, 0.55), 9.0, -95),
                                    ("CloudsNear", 300.0, lin(0.26, 0.28, 0.35), 22.0, -70)):
        ents.append(ent(name, transform=tr(0, y),
                        sprite=sprite("sprites/env/st_clouds.png", (W + 2048, 360), tint, z=z,
                                      fill={"mode": "tile", "tile_size": [1024.0, 360.0]}),
                        unlit={},
                        velocity={"x": speed, "y": 0.0, "gravity": 0.0},
                        wrap_bounds={"min": [-512.0, -H], "max": [512.0, H]}))
    ents.append(ent("Bolt", transform=tr(-200, 400),
                    sprite=sprite("sprites/fx/st_bolt.png", (320, 720), [0.8, 0.85, 1.0, 0.0], z=-80, anchor=(0.5, 1.0)),
                    material=additive(), unlit={}))
    # Rain far off, behind the houses: fine, dim, hitting nothing.
    ents.append(ent("RainFar", transform=tr(-160, H / 2 + 40), particle_emitter=emitter(
        texture_id="sprites/fx/st_drop.png", emit_shape={"kind": "line", "length": W + 700.0},
        emission_rate=500.0, max_particles=1200, lifetime=[1.1, 1.3], speed=[700.0, 800.0],
        angle=[ST_RAIN_ANGLE - 0.02, ST_RAIN_ANGLE + 0.02], size_start=[1.5, 2.0], size_end=[1.5, 2.0],
        color_start=lin(0.45, 0.5, 0.6, 0.35), color_end=lin(0.45, 0.5, 0.6, 0.35),
        stretch=0.03, z_order=-60), unlit={}))
    lit = {"HouseA": [True, False, True], "HouseB": [True, True], "HouseC": [False, True]}
    for name, tex, x, size, roof, windows in ST_HOUSES:
        ents += st_house(name, tex, x, size, roof, windows, lit[name],
                         door=(170, 200, 230, 320) if name == "HouseB" else None)
    lx, ly = ST_LAMP
    ents.append(ent("Lamp", transform=tr(lx, ly),
                    sprite=sprite("sprites/env/st_lamp.png", (90, 360), lin(0.30, 0.30, 0.34), z=-35, anchor=(0.2, 0.0))))
    ents.append(ent("LampGlass", transform=tr(lx + 38, ly + 286),
                    sprite=sprite("sprites/fx/soft_dot.png", (34, 40), emissive(lin(1.0, 0.8, 0.5), 5.0), z=-34),
                    unlit={}))
    ents.append(ent("LampLight", transform=tr(lx + 38, ly + 280),
                    point_light=point_light(lin(1.0, 0.72, 0.42), 2.6, 520, 1.3, shadows=False)))
    # The street, and a ground for the rain to land on under it.
    ents.append(ent("Street", transform=tr(0, ST_GROUND),
                    sprite=sprite("sprites/env/st_street.png", (W + 200, 170), lin(0.55, 0.57, 0.62), z=-30,
                                  anchor=(0.5, 1.0), fill={"mode": "tile", "tile_size": [512.0, 160.0]}),
                    collider={"shape": {"Box": {"width": W + 400.0, "height": 200.0}}, "offset": [0.0, -100.0]}))
    for i, (px, py, pw) in enumerate(((-300.0, -250.0, 260.0), (140.0, -290.0, 340.0), (470.0, -235.0, 180.0))):
        ents.append(ent(f"Puddle{i + 1}", transform=tr(px, py),
                        sprite=sprite("sprites/env/st_puddle.png", (pw, pw * 0.16), lin(0.30, 0.34, 0.46), z=-29),
                        unlit={}))
    # The rain that lands: dies on any collider, and bursts a splash there.
    ents.append(ent("Rain", transform=tr(-160, H / 2 + 40), particle_emitter=emitter(
        texture_id="sprites/fx/st_drop.png", emit_shape={"kind": "line", "length": W + 700.0},
        emission_rate=700.0, max_particles=2000, lifetime=[1.6, 1.8], speed=[950.0, 1100.0],
        angle=[ST_RAIN_ANGLE - 0.02, ST_RAIN_ANGLE + 0.02], size_start=[2.5, 3.2], size_end=[2.5, 3.2],
        color_start=lin(0.62, 0.68, 0.8, 0.45), color_end=lin(0.62, 0.68, 0.8, 0.45),
        stretch=0.035, z_order=-20,
        collision={"response": "kill"},
        sub_emitters=[{"on": "collision", "emitter": "Splash", "count": 4, "chance": 0.6}]), unlit={}))
    ents.append(ent("Splash", transform=tr(0, 0), particle_emitter=emitter(
        texture_id="sprites/fx/soft_dot.png", emission_rate=0.0, max_particles=4000,
        lifetime=[0.22, 0.4], speed=[70.0, 190.0], angle=[0.5, 2.64],
        size_start=[5.0, 7.0], size_end=[1.5, 2.0], stretch=0.02,
        color_start=lin(0.8, 0.86, 1.0, 0.8), color_end=lin(0.8, 0.86, 1.0, 0.0),
        gravity_modifier=2.0, z_order=-19), unlit={}))
    # The verge: grass the script lays out once and bends on the GPU
    # (`materials/storm_grass`, tools/gen_shaders.py), steering it by one
    # `wind` parameter a frame. It used to rebuild all 850 vertices in Lua
    # every frame and send them across the bridge - most of the frame in a
    # web build.
    ents.append(ent("Grass", transform=tr(0, -H / 2),
                    mesh={"texture_id": "", "color": lin(0.30, 0.40, 0.24), "z_order": -10,
                          "vertices": [], "indices": []},
                    material={"material_id": "materials/storm_grass", "blend_mode": "Alpha",
                              "uniforms": {"wind": {"Vec4": [0.15 * 1.1, 0.12 + 0.15 * 0.25, 0.0, -H / 2]}}}))
    ents += caption_entities(
        "20   Storm",
        "L  lightning   G  a gust   R  rain   1-4 post   Tab captions")
    ents.append(ent("Driver", transform=tr(), script=script("scripts/s20_storm.lua")))
    pp = post(
        hdr={"tonemap": "aces", "exposure": 1.0},
        bloom={"threshold": 1.0, "intensity": 0.7, "blur_size": 0.0},
        vignette={"intensity": 0.45, "smoothness": 0.55, "color": [0.0, 0.01, 0.03, 1.0]},
        grade={"brightness": 1.0, "contrast": 1.05, "saturation": 0.85, "tint": [0.8, 0.88, 1.0, 0.08]},
        chromatic={"strength": 0.0015, "on": False})
    return {"name": "20 - Storm", "post_process": pp, "entities": ents}



# ── 21 The Creature ──────────────────────────────────────────────────────
#
# A big cat crossing rolling ground in the afternoon. What to look at:
#   - it walks into a run and back: one skeletal player, its `blend_clip`
#     weighted by pace (`Animation.set_blend`), the two clips sampled at one
#     phase so the legs never lose step, and the cycle's pace between theirs;
#   - it stops and starts with a crossfade (`Animation.crossfade`) to and
#     from an idle - no snap;
#   - its feet stand on the ground: each paw's `ik_two_bone.ground` takes the
#     foot where the clip put it and plants it on the terrain's collider, so
#     a walk authored on a flat floor climbs hills and steps over rocks;
#   - one skinned mesh - far legs, body, near legs - bends at every joint.
# Up / Down set the pace, Space stops and starts, I turns foot IK off (the
# feet then walk on the clip's flat floor, into and above the ground).

import creature as cr

CR_Z = 10


def cr_ground_mesh(points, top, soil, deep):
    """The ground: a strip of quads under the terrain line, grass at the
    top shading to soil and dark below."""
    verts, idx = [], []
    for x, y in points:
        for dy, col in ((0.0, top), (-10.0, top), (-50.0, soil), (-700.0, deep)):
            verts.append({"position": [round(x, 2), round(y + dy, 2)], "uv": [0.0, 0.0], "color": col})
    for i in range(len(points) - 1):
        for r in range(3):
            a = 4 * i + r
            b, c, d = a + 1, a + 4, a + 5
            idx += [a, b, d, a, d, c]
    return verts, idx


def creature():
    ents = [camera()]
    # Sky and sun ride the camera.
    for e in (ent("Sky", transform=tr(0, 0),
                  sprite=sprite("sprites/env/cr_sky.png", (W + 400, H + 300), lin(1.0, 1.0, 1.0), z=-100)),
              ent("Sun", transform=tr(360, 170),
                  sprite=sprite("sprites/fx/glow.png", (520, 520), emissive(lin(1.0, 0.85, 0.55, 0.7), 1.4), z=-99),
                  material=additive())):
        e["parent"] = "Camera"
        ents.append(e)
    ents.append(ent("HillsFar", transform=tr(0, -60),
                    sprite=sprite("sprites/env/cr_hills_far.png", (W + 2048, 600), lin(1.0, 1.0, 1.0), z=-90,
                                  fill={"mode": "tile", "tile_size": [1024.0, 600.0]})))
    ents.append(ent("HillsMid", transform=tr(0, -120),
                    sprite=sprite("sprites/env/cr_hills_mid.png", (W + 2048, 600), lin(1.0, 1.0, 1.0), z=-80,
                                  fill={"mode": "tile", "tile_size": [1024.0, 600.0]})))
    # The terrain: two periods and a margin, so the wrap back by one period
    # is invisible. Drawn as a mesh, and solid as a polyline the paws find.
    pts = cr.ground_points(-1200.0, 2 * cr.PERIOD + 1600.0)
    verts, idx = cr_ground_mesh(pts, lin(0.46, 0.60, 0.22), lin(0.36, 0.30, 0.18), lin(0.16, 0.12, 0.08))
    ents.append(ent("Ground", transform=tr(0, 0),
                    mesh={"texture_id": "", "color": [1.0, 1.0, 1.0, 1.0], "z_order": 0,
                          "vertices": verts, "indices": idx},
                    collider={"shape": {"Polyline": {"vertices": [[round(x, 2), round(y, 2)] for x, y in pts]}}}))
    x0 = 200.0
    body = cr.ground_height(x0) - cr.FLOOR
    for e in cr.rig_entities("Cat", x0, body, CR_Z, "cr_idle"):
        ents.append(e)
    ents += cr.ear_and_eye("Cat", CR_Z)
    # The captions ride the camera, which follows the cat.
    for e in caption_entities(
            "21   The Creature",
            "Up / Down  pace   Space  stop / go   I  foot IK   1-4 post   Tab captions"):
        e["parent"] = "Camera"
        ents.append(e)
    ents.append(ent("Driver", transform=tr(), script=script("scripts/s21_creature.lua")))
    pp = post(
        bloom={"threshold": 1.1, "intensity": 0.35, "blur_size": 0.0},
        vignette={"intensity": 0.3, "smoothness": 0.6, "color": [0.1, 0.05, 0.0, 1.0]},
        grade={"brightness": 1.0, "contrast": 1.04, "saturation": 1.05, "tint": [1.0, 0.95, 0.85, 0.05]},
        chromatic={"strength": 0.0015, "on": False})
    return {"name": "21 - The Creature", "post_process": pp, "entities": ents}


def write_creature_clips():
    import json as _json
    for path, doc in cr.clips().items():
        out = ASSETS / path
        out.parent.mkdir(parents=True, exist_ok=True)
        out.write_text(_json.dumps(doc, indent=1) + "\n", encoding="utf-8", newline="\n")
    # The terrain, for the script to follow with the body.
    lua = ["-- Generated by tools/gen_scenes.py from tools/creature.py: the terrain",
           "-- under The Creature, one period of it, sampled every STEP units.",
           "local T = {}",
           f"T.PERIOD = {cr.PERIOD}",
           f"T.STEP = {cr.STEP}",
           f"T.FLOOR = {cr.FLOOR}",
           f"T.WALK_SPEED = {cr.ground_speed('walk'):.3f}",
           f"T.RUN_SPEED = {cr.ground_speed('run'):.3f}",
           "T.H = {"]
    n = int(cr.PERIOD / cr.STEP)
    row = []
    for i in range(n):
        row.append(f"{cr.ground_height(i * cr.STEP):.2f}")
        if len(row) == 12:
            lua.append("    " + ", ".join(row) + ",")
            row = []
    if row:
        lua.append("    " + ", ".join(row) + ",")
    lua += ["}", "return T", ""]
    (ASSETS / "scripts" / "cr_terrain.lua").write_text("\n".join(lua), encoding="utf-8", newline="\n")



# ── 22 Menus & HUD ───────────────────────────────────────────────────────
#
# A game's front end over the God Rays forest: a title menu, an inventory
# and an in-game HUD, each a `.gui` document (tools/menus.py). What to look at:
#   - rounded cards, pill buttons and slots with soft drop shadows;
#   - buttons that ease into their hover colour and grow as the pointer
#     comes onto them, with centred labels;
#   - a change of screen: the old card fades and shrinks away, the new one
#     fades in from a little larger - `opacity` and `scale`, set on one card
#     and inherited by everything on it;
#   - the HUD: health and mana easing to new values, an ability bar whose
#     cooldowns drain, a gold counter that pops on a pickup, a toast that
#     slides in and away.
# Click the buttons, or wait: the demo walks the screens itself.

import menus as mh


def menus_hud():
    ents = [camera()]
    # The forest from 19, dimmer - it is behind a menu.
    ents.append(ent("Sky", transform=tr(0, 20),
                    sprite=sprite("sprites/env/gr_sky.png", (W + 300, H + 200), lin(0.75, 0.75, 0.8), z=-100)))
    ents.append(ent("Haze", transform=tr(0, 0),
                    sprite=sprite("sprites/env/gr_haze.png", (W + 300, H + 200), lin(0.62, 0.55, 0.42), z=-90)))
    ents += gr_row("TrunkFar", (-610, -410, -170, 40, 250, 520), 0.55, lin(0.55, 0.50, 0.42), -80)
    ents += gr_row("TrunkMid", (-500, -300, 130, 610), 0.8, lin(0.22, 0.20, 0.17), -60)
    ents.append(ent("Canopy", transform=tr(80, H / 2 + 20),
                    sprite=sprite("sprites/env/gr_canopy.png", (W + 600, 420), lin(0.05, 0.06, 0.04), z=-30,
                                  anchor=(0.5, 1.0), fill={"mode": "tile", "tile_size": [1024.0, 420.0]}),
                    oscillator={"amplitude": [8.0, 3.0], "frequency": [0.13, 0.21], "phase": [0.0, 0.0]}))
    ents.append(ent("Floor", transform=tr(0, -H / 2 - 20),
                    sprite=sprite("sprites/env/gr_floor.png", (W + 400, 250), lin(0.04, 0.05, 0.03), z=-20,
                                  anchor=(0.5, 0.0), fill={"mode": "tile", "tile_size": [1024.0, 250.0]})))
    ents.append(ent("Dust", transform=tr(0, 0), particle_emitter=emitter(
        emit_shape={"kind": "rect", "size": [W + 100.0, H + 100.0]},
        emission_rate=20.0, max_particles=300, lifetime=[8.0, 14.0], speed=[2.0, 10.0],
        size_start=[2.0, 4.0], size_end=[2.0, 4.0],
        color_curve=[[0.0] + lin(1.0, 0.92, 0.75, 0.0), [0.2] + lin(1.0, 0.92, 0.75, 0.45),
                     [0.8] + lin(1.0, 0.92, 0.75, 0.45), [1.0] + lin(1.0, 0.92, 0.75, 0.0)],
        turbulence={"strength": 14.0, "scale": 160.0, "speed": 0.1}, z_order=-35)))
    # One entity per document: a `.gui` is loaded only when something names it.
    for name, gid, shown in (("MenuUI", "ui/mh_menu.gui", True), ("InventoryUI", "ui/mh_inventory.gui", False),
                             ("HudUI", "ui/mh_hud.gui", False)):
        ents.append(ent(name, transform=tr(), gui={"gui_id": gid, "visible": shown}))
    ents.append(ent("Driver", transform=tr(), script=script("scripts/s22_menus.lua")))
    pp = post(
        bloom={"threshold": 1.2, "intensity": 0.3, "blur_size": 0.0},
        vignette={"intensity": 0.5, "smoothness": 0.55, "color": [0.02, 0.01, 0.0, 1.0]},
        grade={"brightness": 0.9, "contrast": 1.05, "saturation": 1.0, "tint": [1.0, 0.92, 0.8, 0.06]},
        chromatic={"strength": 0.0015, "on": False})
    return {"name": "22 - Menus & HUD", "post_process": pp, "entities": ents}


def write_menus():
    import json as _json
    for path, doc in mh.docs().items():
        out = ASSETS / path
        out.parent.mkdir(parents=True, exist_ok=True)
        out.write_text(_json.dumps(doc, indent=1) + "\n", encoding="utf-8", newline="\n")
    (ASSETS / "scripts" / "mh_items.lua").write_text(mh.items_lua(), encoding="utf-8", newline="\n")
    # The 64 px tabletop face, for titles that stay crisp. It is the
    # showcase's own (`assets/fonts/tabletop.font` and its `.png`), kept in
    # the repository rather than generated here.
    fonts = ASSETS / "fonts"
    for f in ("tabletop.font", "tabletop.png"):
        if not (fonts / f).exists():
            raise SystemExit(f"missing {fonts / f}: the Menus & HUD scene's title face")



# ── 23 Tilt-Shift Diorama ─────────────────────────────────────────────────
#
# A small town from above that reads as a model of one. What to look at:
#   - the tilt-shift: sharp along one street, blurring away above and below
#     it - `tilt_shift`, a post effect whose band is a world height, so it
#     stays on the street as the camera drifts; the mouse moves it;
#   - the traffic: cars round the blocks and through the town on patrol
#     loops, turning into each corner (`face_velocity` with a `turn_rate`,
#     which a patroller honours now); boats up and down the river;
#   - chimney smoke, and the shadows of clouds sliding over the roofs.
# Mouse: the focus band.  T: tilt-shift on / off.  Up / Down: how much blur.

import diorama as td


def td_car(i, route, points, k, speed):
    x, y = points[k]
    return ent(f"Car{i + 1}", transform=tr(x, y),
               sprite=sprite(f"sprites/env/td_car_{i % 5}.png", (26, 13), (1.0, 1.0, 1.0, 1.0), z=-55),
               patrol_path={"path_id": route, "speed": speed, "index": (k + 1) % len(points), "mode": "Loop",
                            "forward": True},
               face_velocity={"offset_radians": 0.0, "min_speed": 0.001, "turn_rate": 7.0})


def tilt_shift():
    ents = [camera()]
    ents.append(ent("Ground", transform=tr(0, 0),
                    sprite=sprite("sprites/env/td_ground.png", (td.GROUND_W, td.GROUND_H), (1.0, 1.0, 1.0, 1.0),
                                  z=-100)))
    ents[0]["components"]["camera"]["zoom"] = 0.8      # a wider look: more town, smaller town
    for i, (x, y, w, h, style, face, rot) in enumerate(td.houses()):
        ents.append(ent(f"HouseShadow{i + 1}", transform=tr(x + 7, y - 7, rot=rot),
                        sprite=sprite("sprites/env/td_block.png", (w + 8, h + 8), (0.0, 0.0, 0.0, 0.38), z=-60)))
        ents.append(ent(f"House{i + 1}", transform=tr(x, y, rot=rot),
                        sprite=sprite(f"sprites/env/td_roof_{style}.png", (w, h), (1.0, 1.0, 1.0, 1.0), z=-50)))
        if style % 2 == 0 and i % 3 == 0:
            ents.append(ent(f"Smoke{i + 1}", transform=tr(x + w * 0.2, y + h * 0.28), particle_emitter=emitter(
                emission_rate=4.0, max_particles=40, lifetime=[2.5, 4.0], speed=[6.0, 14.0], angle=[0.2, 0.9],
                size_start=[5.0, 7.0], size_end=[14.0, 20.0],
                color_curve=[[0.0, 0.8, 0.8, 0.8, 0.0], [0.15, 0.8, 0.8, 0.8, 0.5], [1.0, 0.85, 0.85, 0.85, 0.0]],
                turbulence={"strength": 6.0, "scale": 60.0, "speed": 0.2}, z_order=-30)))
    for i, (x, y, r, kind) in enumerate(td.trees()):
        ents.append(ent(f"TreeShadow{i + 1}", transform=tr(x + 6, y - 6),
                        sprite=sprite("sprites/fx/soft_dot.png", (r * 2.2, r * 2.2), (0.0, 0.0, 0.0, 0.42), z=-45)))
        ents.append(ent(f"Tree{i + 1}", transform=tr(x, y, rot=(i * 1.7) % 6.28),
                        sprite=sprite(f"sprites/env/td_tree_{kind}.png", (r * 2, r * 2), (1.0, 1.0, 1.0, 1.0), z=-40)))
    loops = td.car_loops()
    cars = [("td_loop_a", 0, 62.0), ("td_loop_a", 2, 62.0), ("td_loop_b", 1, 70.0), ("td_loop_b", 3, 70.0),
            ("td_loop_c", 0, 80.0), ("td_loop_c", 2, 80.0), ("td_thru_ew", 0, 95.0), ("td_thru_ew", 1, 95.0),
            ("td_thru_ew", 2, 90.0), ("td_thru_ns", 0, 85.0), ("td_thru_ns", 1, 85.0), ("td_thru_ns", 2, 90.0)]
    for i, (route, k, speed) in enumerate(cars):
        ents.append(td_car(i, route, loops[route]["points"], k, speed))
    for i, (route, k) in enumerate((("td_river", 3), ("td_river_back", 9), ("td_river", 12))):
        pts = loops[route]["points"]
        x, y = pts[k]
        ents.append(ent(f"Boat{i + 1}", transform=tr(x, y),
                        sprite=sprite("sprites/env/td_boat.png", (34, 15), (1.0, 1.0, 1.0, 1.0), z=-58),
                        patrol_path={"path_id": route, "speed": 18.0, "index": k + 1, "mode": "PingPong",
                                     "forward": True},
                        face_velocity={"offset_radians": 0.0, "min_speed": 0.001, "turn_rate": 2.0}))
    # Cloud shadows drifting over the town.
    for i, (x, y, size, speed) in enumerate(((-600, 150, 520, 14.0), (200, -250, 640, 11.0), (700, 300, 460, 16.0))):
        ents.append(ent(f"CloudShadow{i + 1}", transform=tr(x, y),
                        sprite=sprite("sprites/fx/soft_dot.png", (size, size * 0.6), (0.0, 0.02, 0.05, 0.16), z=-35),
                        velocity={"x": speed, "y": -speed * 0.3, "gravity": 0.0},
                        wrap_bounds={"min": [-1300.0, -800.0], "max": [1300.0, 800.0]}))
    ents += ui_captions(
        "23   Tilt-Shift Diorama",
        "Mouse  focus band   T  tilt-shift   Up / Down  blur   1-4 post   Tab captions")
    ents.append(ent("Driver", transform=tr(), script=script("scripts/s23_tilt_shift.lua")))
    pp = post(
        bloom={"threshold": 1.2, "intensity": 0.2, "blur_size": 0.0},
        vignette={"intensity": 0.35, "smoothness": 0.6, "color": [0.0, 0.0, 0.0, 1.0]},
        grade={"brightness": 1.02, "contrast": 1.12, "saturation": 1.15, "tint": [1.0, 0.97, 0.9, 0.04]},
        chromatic={"strength": 0.0015, "on": False})
    # The blur goes first: it softens the scene, not the grade's vignette.
    pp["effects"].insert(0, {"name": "tilt_shift", "enabled": True, "params": {
        "focus_y": {"Float": 0.0}, "band": {"Float": 50.0}, "falloff": {"Float": 200.0},
        "max_blur": {"Float": 9.0}, "min_blur": {"Float": 0.0}}})
    return {"name": "23 - Tilt-Shift Diorama", "post_process": pp, "paths": loops, "entities": ents}



# ── 27 Two Views ──────────────────────────────────────────────────────────
#
# Scene 23's town, seen by four cameras at once. What to look at:
#   - split screen: the left half is the main camera following one car, the
#     right half a second camera (a *view*: a camera with a `target`) that
#     follows another - each drawn by the whole world pass, post chain and
#     all, the right one into a texture a UI image shows;
#   - the minimap at the top is a third view, far above the town;
#   - the billboard by the road shows a fourth, watching the river bridge -
#     a world sprite whose texture is a camera, so the split views show a
#     picture of a picture.
# M hides the minimap; Space swaps which car each half follows.

TV_ZOOM = 2.0
TV_STREET = 0b101    # render layers 1 and 3: the ground and what stands on it
TV_MAP = 0b011       # render layers 1 and 2: the ground and the markers


def two_views():
    town = tilt_shift()
    ents = [e for e in town["entities"]
            if e["name"] not in ("Title", "Hint", "Status", "Driver")]
    # Render layers: 1 the ground, roads and cars (no component), 2 the
    # players' markers, 3 what stands above the ground - roofs, trees, their
    # shadows, smoke and cloud shadows. The street cameras draw 1 and 3; the
    # minimap draws 1 and 2, so it is a road map with the two cars marked.
    above = ("House", "HouseShadow", "Tree", "TreeShadow", "Smoke", "CloudShadow", "Billboard")
    for e in ents:
        if e["name"] == "Camera":
            e["components"]["camera"]["zoom"] = TV_ZOOM
            e["components"]["camera"]["cull_mask"] = TV_STREET
        elif e["name"].rstrip("0123456789").startswith(above):
            e["components"]["render_layers"] = {"layers": 0b100}
    def view(name, x, y, zoom, target, size, authored):
        return ent(name, transform=tr(x, y),
                   camera={"zoom": zoom, "is_active": True, "viewport_width": float(authored[0]),
                           "viewport_height": float(authored[1]), "target": target,
                           "target_size": [size[0], size[1]],
                           "cull_mask": TV_MAP if target == "views/map" else TV_STREET})
    # The right half: half the screen's width, all its height.
    ents.append(view("ViewP2", 0, 0, TV_ZOOM, "views/p2", (960, 1080), (W / 2, H)))
    ents.append(view("ViewMap", 0, 0, 0.72, "views/map", (480, 280), (W, H)))
    loops = town["paths"]
    ents.append(view("ViewBridge", -640, 189, 2.6, "views/bridge", (320, 180), (W, H)))

    # The players' markers: on the map's layer only.
    for car, colour in (("Car5", lin(1.0, 0.65, 0.25)), ("Car3", lin(0.35, 0.7, 1.0))):
        for k, (size, c) in enumerate(((150, emissive(colour, 1.6)), (150, (1.0, 1.0, 1.0, 1.0)))):
            m = ent(f"{car}Marker{k}", transform=tr(0, 0), render_layers={"layers": 0b10}, unlit={},
                    sprite=sprite("sprites/fx/soft_dot.png" if k == 0 else "", (size, size), c, z=-20 + k))
            if k == 1:
                m["components"]["sprite"]["texture_id"] = "sprites/fx/ring.png"
            m["parent"] = car
            ents.append(m)

    # The billboard, beside the road the first car drives.
    on_top = {"layers": 0b100}
    ents.append(ent("BillboardFrame", transform=tr(110, 262), render_layers=on_top,
                    sprite=sprite("sprites/fx/soft_dot.png", (0.1, 0.1), (0, 0, 0, 0), z=-30)))
    ents[-1]["components"]["sprite"] = {**sprite("", (118, 72), lin(0.12, 0.12, 0.14), z=-31)}
    ents.append(ent("BillboardPost", transform=tr(110, 214), render_layers=on_top,
                    sprite=sprite("", (6, 30), lin(0.2, 0.2, 0.22), z=-32)))
    ents.append(ent("Billboard", transform=tr(110, 262), unlit={}, render_layers=on_top,
                    sprite=sprite("views/bridge", (108, 62), (1.0, 1.0, 1.0, 1.0), z=-30)))

    def ui(name, anchor, ox, oy, w, h, z, **components):
        return ent(name, ui_element={"anchor": anchor, "offset": [float(ox), float(oy)],
                                     "size": [float(w), float(h)], "z_order": z}, **components)
    ents += [
        ui("P2Half", "TopRight", 0, 0, W / 2, H, 10, ui_image={"texture_id": "views/p2", "color": [1, 1, 1, 1]}),
        ui("Divider", "TopCenter", 0, 0, 4, H, 11, ui_panel={"bg_color": lin(0.08, 0.08, 0.1, 1.0)}),
        ui("MapFrame", "TopCenter", 0, -14, 300, 178, 12, ui_panel={"bg_color": lin(0.08, 0.08, 0.1, 0.92)}),
        ui("Map", "TopCenter", 0, -18, 292, 170, 13, ui_image={"texture_id": "views/map", "color": [1, 1, 1, 1]}),
        ui("LabelP1", "BottomLeft", 24, 64, 300, 22, 14,
           ui_text={"text": "P1", "font_size": 20.0, "color": lin(1.0, 0.75, 0.4), "alignment": "Left"}),
        ui("LabelP2", "BottomRight", -24, 64, 300, 22, 14,
           ui_text={"text": "P2", "font_size": 20.0, "color": lin(0.5, 0.8, 1.0), "alignment": "Right"}),
    ]
    ents += ui_captions(
        "27   Two Views",
        "M  minimap   Space  swap cars   1-4 post   Tab captions")
    ents.append(ent("Driver", transform=tr(), script=script("scripts/s27_two_views.lua")))
    pp = post(
        bloom={"threshold": 1.2, "intensity": 0.2, "blur_size": 0.0},
        vignette={"intensity": 0.25, "smoothness": 0.6, "color": [0.0, 0.0, 0.0, 1.0]},
        grade={"brightness": 1.02, "contrast": 1.1, "saturation": 1.12, "tint": [1.0, 0.97, 0.9, 0.04]},
        chromatic={"strength": 0.0015, "on": False})
    return {"name": "27 - Two Views", "post_process": pp, "paths": loops, "entities": ents}



# ── 28 Through the Window ─────────────────────────────────────────────────
#
# A ruined wall at night with an arched window in it, and a portal you carry
# with the mouse. What to look at:
#   - one arch-shaped `sprite_mask`, used both ways: the wall is `masked`
#     *outside* it, so the arch is a hole, and a golden afternoon is masked
#     *inside* it, so the hole shows another day - not a picture of one, a
#     layer of the world that is only drawn there;
#   - the portal: a tear in the world - a `sprite_mask` read from a painted
#     texture's alpha (`fx/rift_mask.png`), ragged and cracked, which no
#     shape could be - with a nebula masked inside it, fixed in the world, so
#     moving the portal looks into different parts of it, as through a real
#     opening; its rim is drawn from the same silhouette;
#   - the rim and the sparks ride the portal as its children.
# Mouse moves the portal (it drifts when left alone); Up / Down sizes it.


def tw_arch_points():
    """An arched window: a rectangle with a round top, 14 points."""
    pts = [[-150.0, -200.0], [150.0, -200.0], [150.0, 40.0]]
    for k in range(1, 11):
        a = math.pi * k / 11
        pts.append([round(150.0 * math.cos(a), 2), round(40.0 + 150.0 * math.sin(a), 2)])
    pts.append([-150.0, 40.0])
    return pts


def through_the_window():
    ents = [camera()]
    # The night: sky, stars, moon, hills.
    ents.append(ent("NightSky", transform=tr(0, 0),
                    sprite=sprite("sprites/env/night_sky.png", (W + 200, H + 200), lin(0.8, 0.85, 1.0), z=-100)))
    ents.append(ent("Stars", transform=tr(0, 60), material=additive(),
                    sprite=sprite("sprites/fx/stars_far.png", (W + 200, H), lin(0.8, 0.85, 1.0, 0.8), z=-99)))
    ents.append(ent("Moon", transform=tr(430, 275),
                    sprite=sprite("sprites/env/moon.png", (86, 86), lin(1.0, 0.97, 0.9), z=-98)))
    ents.append(ent("MoonGlow", transform=tr(430, 275), material=additive(),
                    sprite=sprite("sprites/fx/glow.png", (360, 360), lin(0.6, 0.7, 1.0, 0.35), z=-97)))
    ents.append(ent("Hills", transform=tr(0, -170),
                    sprite=sprite("sprites/env/hills.png", (W + 400, 300), lin(0.1, 0.12, 0.22), z=-90,
                                  fill={"mode": "tile", "tile_size": [700.0, 300.0]})))

    # The afternoon behind the window: drawn only inside the arch.
    def day(name, tex, x, y, size, colour, z, **extra):
        return ent(name, transform=tr(x, y), masked={"by": "Arch", "outside": False},
                   sprite=sprite(tex, size, colour, z=z, **extra))
    ents += [
        day("DaySky", "sprites/env/cr_sky.png", 0, 0, (W, H + 100), (1.0, 1.0, 1.0, 1.0), -70),
        day("DayHillsFar", "sprites/env/cr_hills_far.png", 0, -130, (W + 400, 600), (1.0, 1.0, 1.0, 1.0), -68,
            fill={"mode": "tile", "tile_size": [1024.0, 600.0]}),
        day("DayHillsMid", "sprites/env/cr_hills_mid.png", 0, -250, (W + 400, 600), (1.0, 1.0, 1.0, 1.0), -66,
            fill={"mode": "tile", "tile_size": [1024.0, 600.0]}),
    ]
    sun = day("DaySun", "sprites/fx/glow.png", 60, 90, (420, 420), emissive(lin(1.0, 0.85, 0.55, 0.8), 1.4), -69)
    sun["components"]["material"] = additive()
    ents.append(sun)
    ents.append(ent("Pollen", transform=tr(0, -60), masked={"by": "Arch", "outside": False},
                    particle_emitter=emitter(
                        emission_rate=10.0, max_particles=80, lifetime=[4.0, 7.0], speed=[6.0, 18.0],
                        angle=[0.0, 6.28318], size_start=[3.0, 5.0], size_end=[3.0, 5.0],
                        color_curve=[[0.0, 1.0, 0.95, 0.7, 0.0], [0.2, 1.0, 0.95, 0.7, 0.9], [1.0, 1.0, 0.95, 0.7, 0.0]],
                        emit_shape={"kind": "rect", "size": [320.0, 380.0]},
                        turbulence={"strength": 14.0, "scale": 80.0, "speed": 0.3}, z_order=-64)))

    # The wall, with the arch cut out of it by the same mask.
    ents.append(ent("Arch", transform=tr(0, -60),
                    sprite_mask={"shape": {"Polygon": {"points": tw_arch_points()}}, "feather": 1.5}))
    ents.append(ent("Wall", transform=tr(0, -80), masked={"by": "Arch", "outside": True},
                    sprite=sprite("sprites/env/bricks.png", (W + 200, 560), lin(0.7, 0.62, 0.58), z=-20,
                                  fill={"mode": "tile", "tile_size": [256.0, 256.0]})))
    for side in (-1, 1):
        ents.append(ent(f"Column{'L' if side < 0 else 'R'}", transform=tr(side * 182, -95),
                        sprite=sprite("sprites/env/column.png", (52, 330), lin(0.85, 0.8, 0.76), z=-15)))
        ents.append(ent(f"ColumnCap{'L' if side < 0 else 'R'}", transform=tr(side * 182, 76),
                        sprite=sprite("sprites/env/pillar_top.png", (70, 26), lin(0.85, 0.8, 0.76), z=-14)))
    ents.append(ent("Sill", transform=tr(0, -268),
                    sprite=sprite("sprites/env/bricks.png", (350, 22), lin(0.55, 0.5, 0.48), z=-14,
                                  fill={"mode": "tile", "tile_size": [128.0, 64.0]})))

    # The portal, and the nebula drawn only inside it.
    ents.append(ent("Portal", transform=tr(-330, 40),
                    sprite_mask={"shape": {"Texture": {"texture_id": "sprites/fx/rift_mask.png",
                                                       "size": [240.0, 336.0]}}, "feather": 0.0}))
    rim = ent("PortalRim", transform=tr(0, 0), material=additive(),
              sprite=sprite("sprites/fx/rift_rim.png", (240, 336), emissive(lin(0.75, 0.45, 1.0, 0.95), 2.2), z=33))
    rim["parent"] = "Portal"
    ents.append(rim)
    sparks = ent("PortalSparks", transform=tr(0, 0), particle_emitter=emitter(
        texture_id="sprites/fx/soft_dot.png", emission_rate=60.0, max_particles=160, lifetime=[0.5, 1.1],
        speed=[20.0, 60.0], angle=[0.0, 6.28318], size_start=[7.0, 11.0], size_end=[2.0, 3.0],
        color_curve=[[0.0] + emissive(lin(0.8, 0.6, 1.0), 3.0)[:3] + [0.0],
                     [0.2] + emissive(lin(0.8, 0.6, 1.0), 3.0)[:3] + [1.0],
                     [1.0] + emissive(lin(0.4, 0.8, 1.0), 2.0)[:3] + [0.0]],
        emit_shape={"kind": "circle", "radius": 120.0, "edge": True}, blend_mode="Additive",
        world_space=True, z_order=34))
    sparks["parent"] = "Portal"
    ents.append(sparks)

    def neb(name, tex, x, y, size, colour, z, add=True):
        e = ent(name, transform=tr(x, y), masked={"by": "Portal", "outside": False},
                sprite=sprite(tex, size, colour, z=z))
        if add:
            e["components"]["material"] = additive()
        return e
    ents += [
        neb("NebulaDark", "", 0, 0, (W + 600, H + 600), lin(0.02, 0.01, 0.06), 28, add=False),
        neb("NebulaStars", "sprites/fx/stars_near.png", 0, 0, (W + 600, H + 400), lin(1.0, 1.0, 1.0, 0.9), 29),
        neb("NebulaVeil", "sprites/fx/nebula_veil.png", -200, 60, (900, 700), emissive(lin(0.6, 0.3, 0.9, 0.85), 1.4), 30),
        neb("NebulaVeil2", "sprites/fx/nebula_veil.png", 320, -80, (800, 600), emissive(lin(0.2, 0.6, 0.9, 0.75), 1.3), 30),
        neb("NebulaKnot", "sprites/fx/nebula_knot.png", 60, 40, (520, 520), emissive(lin(1.0, 0.6, 0.8, 0.9), 1.6), 31),
        neb("NebulaFlare", "sprites/fx/star_flare.png", -120, 140, (140, 140), emissive(lin(1.0, 0.95, 0.9, 1.0), 3.0), 32),
    ]
    ents += caption_entities(
        "28   Through the Window",
        "Mouse  move the portal   Up / Down  its size   1-4 post   Tab captions")
    ents.append(ent("Driver", transform=tr(), script=script("scripts/s28_through_the_window.lua")))
    pp = post(
        hdr={"tonemap": "aces", "exposure": 1.0},
        bloom={"threshold": 1.1, "intensity": 0.6, "blur_size": 0.0},
        vignette={"intensity": 0.4, "smoothness": 0.55, "color": [0.0, 0.0, 0.03, 1.0]},
        grade={"brightness": 1.0, "contrast": 1.05, "saturation": 1.05, "tint": [0.9, 0.95, 1.0, 0.05]},
        chromatic={"strength": 0.0015, "on": False})
    return {"name": "28 - Through the Window", "post_process": pp, "entities": ents}



# ── 29 Atlas of the Deep ──────────────────────────────────────────────────
#
# A sea chart you zoom from the whole ocean down to one harbour. What to look
# at: every word on it is world text in the built-in font, which is a signed
# distance field now - so a harbour's name nine times nearer is as sharp as at
# its own size, and so are the turned island names, while the chart's own
# texture softens. The names come and go by zoom, as a real atlas's do: the
# oceans from afar, the towns close, the quays closer.
# Wheel zooms toward the mouse, arrows pan; left alone, it tours.

import chart as ad

AD_INK = lin(0.24, 0.16, 0.1)


def atlas_of_the_deep():
    ents = [camera()]
    ents[0]["components"]["camera"]["zoom"] = 0.48
    ents.append(ent("Chart", transform=tr(0, 0),
                    sprite=sprite("sprites/env/ad_chart.png", ad.WORLD, (1.0, 1.0, 1.0, 1.0), z=-10)))

    def label(name, tier, x, y, txt, scale, rot=0.0, colour=AD_INK, align="center"):
        e = ent(name, transform=tr(x, y, rot=rot), tags=[f"label_{tier}"],
                text=text(txt, scale, colour, z=10, align=align))
        return e
    (ox1, oy1), (ox2, oy2) = ad.deepest(2)
    ents.append(label("OceanSalt", "ocean", ox1, oy1, "T H E   S A L T   D E E P", 6.0, rot=-0.04,
                      colour=lin(0.18, 0.3, 0.34)))
    ents.append(label("OceanGrey", "ocean", ox2, oy2, "G R E Y   S H A L L O W S", 3.6, rot=0.06,
                      colour=lin(0.18, 0.3, 0.34)))
    harbour = None
    for i, (kind, name, x, y, extent) in enumerate(ad.places()):
        if kind == "isle":
            scale = max(0.8, min(3.0, extent / 280.0))
            rot = ((i * 37) % 11 - 5) * 0.025
            ents.append(label(f"Isle{i}", "isle", x, y, name, scale, rot=rot))
        else:
            ents.append(ent(f"TownDot{i}", transform=tr(x, y),
                            sprite=sprite("sprites/fx/soft_dot.png", (9, 9), AD_INK, z=9)))
            ents.append(label(f"Town{i}", "town", x + 9, y + 2, name, 0.6, align="left"))
            # The tour's harbour: the one nearest the middle of the chart.
            if harbour is None or x * x + y * y < harbour[0] ** 2 + harbour[1] ** 2:
                harbour = (x, y, name)
    # The quays of the first harbour, for the closest look.
    hx, hy, hname = harbour
    for j, (dx, dy, txt) in enumerate(((-34, -18, "old pier"), (22, 26, "lighthouse"), (-6, 40, "customs house"),
                                       (30, -30, "fish market"), (-46, 14, "ropewalk"))):
        ents.append(ent(f"DetailDot{j}", transform=tr(hx + dx, hy + dy),
                        sprite=sprite("sprites/fx/soft_dot.png", (3, 3), AD_INK, z=9)))
        ents.append(label(f"Detail{j}", "detail", hx + dx + 3, hy + dy, txt, 0.2, align="left"))
    ents += ui_captions(
        "29   Atlas of the Deep",
        "Wheel  zoom   Arrows  pan   Space  tour   1-4 post   Tab captions")
    ents.append(ent("Driver", transform=tr(), script=script("scripts/s29_atlas_of_the_deep.lua")))
    write_atlas_script(hx, hy, [(x, y) for kind, _, x, y, _ in ad.places() if kind == "isle"][:3])
    pp = post(
        bloom={"threshold": 1.5, "intensity": 0.1, "blur_size": 0.0},
        vignette={"intensity": 0.45, "smoothness": 0.5, "color": [0.1, 0.06, 0.02, 1.0]},
        grade={"brightness": 1.0, "contrast": 1.03, "saturation": 0.95, "tint": [1.0, 0.95, 0.85, 0.05]},
        chromatic={"strength": 0.0015, "on": False})
    return {"name": "29 - Atlas of the Deep", "post_process": pp, "entities": ents}


def write_atlas_script(hx, hy, isles):
    """The tour's stops are the chart's own places, so the script is written
    here, beside them."""
    stops = [(0.0, 0.0, 0.48)] + [(x, y, 1.6) for x, y in isles[:2]] + [(hx, hy, 3.0), (hx, hy, 8.5), (0.0, 0.0, 0.48)]
    rows = "\n".join(f"    {{ {x:.1f}, {y:.1f}, {z} }}," for x, y, z in stops)
    (ASSETS / "scripts" / "s29_atlas_of_the_deep.lua").write_text(ATLAS_LUA.replace("@STOPS@", rows),
                                                                           encoding="utf-8", newline="\n")


ATLAS_LUA = """-- 29 Atlas of the Deep: the camera, and which names show at which zoom.
-- The lettering is the engine's (world text in a distance-field font).
-- Generated by tools/gen_scenes.py with the tour's stops. Wheel: zoom toward
-- the mouse.  Arrows: pan.  Space: tour now.  Left alone, it tours.

script = { tick_rate = 60 }

local nav = require("nav")
local SCENE = "scenes/29-atlas-of-the-deep.scene"
local MIN_ZOOM, MAX_ZOOM = 0.45, 10.0
local INK = { 0.0484, 0.0222, 0.0100 }
local SEA = { 0.0273, 0.0742, 0.0953 }
local STOPS = {
@STOPS@
}
-- name tier, zoom it fades in from, to, fades out from, to
local TIERS = {
    { "label_ocean", 0.0, 0.0, 0.9, 1.6, SEA },
    { "label_isle", 0.0, 0.0, 5.0, 7.0, INK },
    { "label_town", 1.0, 1.5, 99, 99, INK },
    { "label_detail", 3.5, 5.0, 99, 99, INK },
}

local post_on = nav.post_all_on(SCENE)
local captions = true
local status, cam
local x, y, zoom = 0.0, 0.0, 0.48
local tx, ty, tz = 0.0, 0.0, 0.48
local quiet, touring, stop, held = 0.0, true, 1, 0.0
local labels = {}

local function smooth(a, b, v)
    if v <= a then return 0 end
    if v >= b then return 1 end
    local t = (v - a) / (b - a)
    return t * t * (3 - 2 * t)
end

local function tier_alpha(t, z)
    local fade_in = (t[3] > t[2]) and smooth(t[2], t[3], z) or 1
    return fade_in * (1 - smooth(t[4], t[5], z))
end

function init(entity)
    status = Entity.find_by_name("Status")
    cam = Entity.find_by_name("Camera")
    for i, t in ipairs(TIERS) do
        labels[i] = { entities = Entity.find_by_tag(t[1]) or {}, alpha = -1 }
    end
end

function update(entity, dt)
    nav.tick(SCENE)
    nav.post_keys(post_on)
    if Input.is_key_just_pressed("Tab") then captions = nav.toggle_ui_captions(captions) end
    if Input.is_key_just_pressed("Space") then touring, stop, held = true, 1, 0 end

    local wheel = Input.get_mouse_wheel() or 0
    local pan_x, pan_y = 0, 0
    if Input.is_key_pressed("Left") then pan_x = -1 end
    if Input.is_key_pressed("Right") then pan_x = 1 end
    if Input.is_key_pressed("Up") then pan_y = 1 end
    if Input.is_key_pressed("Down") then pan_y = -1 end
    if wheel ~= 0 or pan_x ~= 0 or pan_y ~= 0 then
        touring, quiet = false, 0
        if wheel ~= 0 then
            -- Toward the mouse: the point under it stays under it.
            local mx, my = Input.get_mouse_world_position()
            local nz = math.max(MIN_ZOOM, math.min(MAX_ZOOM, tz * (1.18 ^ wheel)))
            tx = mx + (tx - mx) * tz / nz
            ty = my + (ty - my) * tz / nz
            tz = nz
        end
        tx = tx + pan_x * dt * 600 / tz
        ty = ty + pan_y * dt * 600 / tz
    else
        quiet = quiet + dt
        if quiet > 6 then touring = true end
    end
    if touring then
        local s = STOPS[stop]
        tx, ty, tz = s[1], s[2], s[3]
        held = held + dt
        if held > 4.5 then
            held = 0
            stop = stop % #STOPS + 1
        end
    end

    -- Ease, the zoom in log space so it travels evenly.
    local k = 1 - math.exp(-dt * 2.2)
    x = x + (tx - x) * k
    y = y + (ty - y) * k
    zoom = math.exp(math.log(zoom) + (math.log(tz) - math.log(zoom)) * k)
    if cam then
        Transform.set_position(cam, x, y)
        Camera.set_zoom(zoom)
    end

    for i, t in ipairs(TIERS) do
        local a = tier_alpha(t, zoom)
        local l = labels[i]
        if math.abs(a - l.alpha) > 0.01 then
            l.alpha = a
            for _, e in ipairs(l.entities) do
                Text.set_color(e, t[6][1], t[6][2], t[6][3], a)
            end
        end
    end
    if status then
        UI.set_text(status, "zoom x" .. string.format("%.1f", zoom / 0.48) .. (touring and "   touring" or ""))
    end
end
"""



# ── 30 Spell Storm ────────────────────────────────────────────────────────
#
# Spellcraft's mage at the heart of a storm of two hundred thousand sparks.
# What to look at:
#   - every spark is a `gpu_particles` particle: a closed form of its index
#     and the time, evaluated in the vertex shader - no particle exists on
#     the CPU, so the whole storm is three draw calls and three uniforms;
#   - the vortex on the floor (a cloud squashed by its emitter's scale into
#     the floor's perspective), the column rising off the rune ring, and the
#     knot at the staff - each turned (`swirl`), drawn in (`attract`) and
#     slowed (`drag`) by the same closed form;
#   - it sorts by z with the sprites: the vortex passes behind the mage's
#     feet and the column in front of her.
# Up / Down: how many (50k to 400k)   Space: stop time   1-4 post   Tab captions


def spell_storm():
    scene = spellcraft()
    ents = [e for e in scene["entities"]
            if e["name"] not in ("Title", "Hint", "Status", "Driver", "Motes")]
    mx, my = SC_MAGE
    tx, ty = SC_TIP

    def storm(name, x, y, z, sx, sy, **fields):
        g = {"count": 10000, "blend_mode": "Additive", "z_order": z,
             "color_start": emissive(ARCANE[:3] + [0.0], 1.8),
             "color_mid": emissive(ARCANE[:3] + [0.3], 1.8),
             "color_end": emissive(FROST[:3] + [0.0], 1.2)}
        g.update(fields)
        return ent(name, transform=tr(x, y, sx=sx, sy=sy), unlit={}, gpu_particles=g)
    ents += [
        # The vortex: launched outward, turned and slowed - spiral arms - on
        # the floor, so squashed to its perspective. Behind the mage's feet.
        storm("StormVortex", mx, my + 4, -36, 1.0, 0.36, count=140000, lifetime=[2.5, 4.5],
              speed=[60.0, 240.0], drag=0.8, swirl=1.1, arms=4, radius=40.0, size=[2.2, 0.8], stretch=1.5,
              noise=18.0, noise_speed=3.0, seed=11),
        # The column off the rune ring: risen, turning slowly, thinning out.
        # Squashed to the floor like the vortex, so its ring is the rune
        # circle's ellipse - and its rise three times faster to make up.
        storm("StormColumn", mx, my + 10, 24, 1.0, 0.36, count=50000, lifetime=[2.0, 4.0],
              speed=[2.0, 18.0], angle=[1.37, 1.77], gravity=[0.0, 170.0], radius=230.0, edge=True,
              size=[2.4, 0.4], stretch=1.0, noise=20.0, noise_speed=2.0,
              color_start=emissive(FROST[:3] + [0.0], 2.4), color_mid=emissive(FROST[:3] + [0.55], 2.4),
              color_end=emissive(ARCANE[:3] + [0.0], 1.2), seed=23),
        # The knot at the staff: thrown out and drawn back in, fast.
        storm("StormKnot", tx, ty, 26, 1.0, 1.0, count=20000, lifetime=[0.7, 1.5], speed=[80.0, 160.0],
              drag=1.5, attract=2.5, swirl=3.5, size=[1.8, 0.4], stretch=2.0,
              color_start=emissive(lin(0.85, 0.95, 1.0, 0.0), 2.0),
              color_mid=emissive(lin(0.85, 0.95, 1.0, 0.3), 2.0),
              color_end=emissive(ARCANE[:3] + [0.0], 1.5), seed=37),
    ]
    # UI captions, drawn after the post chain: the storm's bloom stays off them.
    ents += ui_captions(
        "30   Spell Storm",
        "Up / Down  how many   Space  stop time   1-4 post   Tab captions")
    ents.append(ent("Driver", transform=tr(), script=script("scripts/s30_spell_storm.lua")))
    scene["name"] = "30 - Spell Storm"
    scene["entities"] = ents
    return scene



# ── 24 Collapse ───────────────────────────────────────────────────────────
#
# A tower of stone in a courtyard at night, and a boulder thrown at it. What
# to look at:
#   - it breaks: every block is `breakable` - hit hard enough (its velocity
#     jolted past `break_speed`) it comes apart into pieces cut from its own
#     sprite and normal map, each a body that carries on with the part's
#     velocity - and dust bursts where it broke;
#   - the shadows: every block and piece casts one onto the wall behind,
#     from two braziers, so the whole tower's shadow falls as it falls;
#   - the fire: flickering light raking across the normal-mapped stone.
# Space throws the boulder now; R rebuilds the tower. Left alone it throws,
# waits, and rebuilds by itself.

CL_FLOOR = -280.0
CL_BLOCK = (64.0, 32.0)
CL_TOWER_X = 170.0
CL_ROWS = 11


def cl_block(name, x, y, w, uv):
    return ent(name, transform=tr(x, y),
               sprite={**sprite("sprites/env/cl_block.png", (w, CL_BLOCK[1]), lin(0.86, 0.84, 0.82), z=0),
                       "uv_rect": uv},
               material={"material_id": "lit_sprite", "normal_map_id": "sprites/env/cl_block_n.png"},
               rigid_body={"body_type": "Dynamic", "mass": w / CL_BLOCK[0], "gravity_scale": 1.0,
                           "linear_damping": 0.05, "angular_damping": 0.2, "fixed_rotation": False, "ccd": True},
               collider={"shape": {"Box": {"width": w - 0.5, "height": CL_BLOCK[1] - 0.5}}, "friction": 0.8,
                         "restitution": 0.05},
               light_occluder={"enabled": True, "size": [w, CL_BLOCK[1]], "shadows_casters": False},
               breakable={"break_speed": 320.0, "cols": 2, "rows": 1, "generations": 0, "scatter": 25.0,
                          "piece_lifetime": 0.0, "debris": "Dust", "debris_count": 14})


def collapse():
    ents = [camera()]
    ents.append(ent("Ambient", transform=tr(), ambient_light={"color": lin(0.45, 0.52, 0.8)[:3], "intensity": 0.22}))
    ents.append(ent("Wall", transform=tr(0, 60),
                    sprite=sprite("sprites/env/cl_wall.png", (W + 300, H + 300), lin(0.8, 0.78, 0.76), z=-80,
                                  fill={"mode": "tile", "tile_size": [256.0, 256.0]}),
                    material={"material_id": "lit_sprite", "normal_map_id": "sprites/env/cl_wall_n.png"}))
    ents.append(ent("Floor", transform=tr(0, CL_FLOOR),
                    sprite=sprite("sprites/env/flagstones.png", (W + 400, 160), lin(0.55, 0.52, 0.50), z=-20,
                                  anchor=(0.5, 1.0), fill={"mode": "tile", "tile_size": [220.0, 110.0]}),
                    rigid_body={"body_type": "Static", "mass": 1.0, "gravity_scale": 1.0, "linear_damping": 0.0,
                                "angular_damping": 0.0, "fixed_rotation": True},
                    collider={"shape": {"Box": {"width": W + 800.0, "height": 200.0}}, "offset": [0.0, -100.0],
                              "friction": 0.9, "restitution": 0.0}))
    # The tower: courses of five blocks, every other one offset by half a
    # block with half blocks at its ends.
    bw, bh = CL_BLOCK
    n = 0
    for row in range(CL_ROWS):
        y = CL_FLOOR + bh * (row + 0.5)
        if row % 2 == 0:
            for c in range(5):
                x = CL_TOWER_X + (c - 2) * bw
                n += 1
                ents.append(cl_block(f"Block{n}", x, y, bw, [0.0, 0.0, 1.0, 1.0]))
        else:
            xs = [CL_TOWER_X - 2.5 * bw + bw / 4] + [CL_TOWER_X + (c - 1.5) * bw for c in range(4)] + \
                 [CL_TOWER_X + 2.5 * bw - bw / 4]
            for k, x in enumerate(xs):
                half = k in (0, len(xs) - 1)
                n += 1
                ents.append(cl_block(f"Block{n}", x, y, bw / 2 if half else bw,
                                     [0.0, 0.0, 0.5, 1.0] if half else [0.0, 0.0, 1.0, 1.0]))
    # The boulder, waiting off stage left.
    ents.append(ent("Boulder", transform=tr(-900, -150),
                    sprite=sprite("sprites/env/cl_boulder.png", (76, 76), (1.0, 1.0, 1.0, 1.0), z=5),
                    material={"material_id": "lit_sprite", "normal_map_id": "sprites/env/cl_boulder_n.png"},
                    rigid_body={"body_type": "Dynamic", "mass": 40.0, "gravity_scale": 1.0, "linear_damping": 0.0,
                                "angular_damping": 0.1, "fixed_rotation": False, "ccd": True},
                    collider={"shape": {"Circle": {"radius": 38.0}}, "friction": 0.6, "restitution": 0.1,
                              "density": 12.0},
                    light_occluder={"enabled": True, "polygon": polygon_circle(36.0, 10), "shadows_casters": False}))
    # Braziers: the light, and what the shadows are cast from.
    for name, x in (("BrazierL", -380.0), ("BrazierR", 560.0)):
        ents.append(ent(name, transform=tr(x, CL_FLOOR),
                        sprite=sprite("sprites/env/cl_brazier.png", (54, 82), lin(0.16, 0.14, 0.13), z=8,
                                      anchor=(0.5, 0.0))))
        ents.append(ent(f"{name}Fire", transform=tr(x, CL_FLOOR + 74), particle_emitter=emitter(
            texture_id="sprites/fx/soft_dot.png", emission_rate=70.0, max_particles=160, lifetime=[0.35, 0.8],
            speed=[30.0, 80.0], angle=[1.3, 1.85], size_start=[18.0, 26.0], size_end=[4.0, 8.0],
            color_curve=[[0.0] + emissive(lin(1.0, 0.75, 0.35), 5.0)[:3] + [0.0],
                         [0.15] + emissive(lin(1.0, 0.6, 0.25), 5.0)[:3] + [1.0],
                         [1.0] + emissive(lin(0.9, 0.25, 0.08), 3.0)[:3] + [0.0]],
            emit_shape={"kind": "line", "length": 30.0}, blend_mode="Additive",
            turbulence={"strength": 30.0, "scale": 40.0, "speed": 1.0}, z_order=9)))
        ents.append(ent(f"{name}Light", transform=tr(x, CL_FLOOR + 110),
                        point_light=point_light(lin(1.0, 0.62, 0.30), 1.7, 950, 1.2, softness=6.0)))
    # Dust where stone breaks: bursts only.
    ents.append(ent("Dust", transform=tr(0, 0), particle_emitter=emitter(
        texture_id="sprites/fx/soft_dot.png", emission_rate=0.0, max_particles=900, lifetime=[1.0, 2.2],
        speed=[30.0, 170.0], angle=[0.0, 6.28318], size_start=[8.0, 14.0], size_end=[30.0, 52.0],
        color_curve=[[0.0] + lin(0.62, 0.56, 0.48, 0.0), [0.1] + lin(0.62, 0.56, 0.48, 0.55),
                     [1.0] + lin(0.5, 0.46, 0.4, 0.0)],
        gravity_modifier=-0.02, drag=2.2, turbulence={"strength": 20.0, "scale": 90.0, "speed": 0.3}, z_order=12)))
    ents += caption_entities(
        "24   Collapse",
        "Space  throw   R  rebuild   1-4 post   Tab captions")
    ents.append(ent("Driver", transform=tr(), script=script("scripts/s24_collapse.lua")))
    pp = post(
        hdr={"tonemap": "aces", "exposure": 1.05},
        bloom={"threshold": 1.1, "intensity": 0.55, "blur_size": 0.0},
        vignette={"intensity": 0.5, "smoothness": 0.55, "color": [0.02, 0.01, 0.0, 1.0]},
        grade={"brightness": 1.0, "contrast": 1.06, "saturation": 1.05, "tint": [1.0, 0.9, 0.78, 0.06]},
        chromatic={"strength": 0.0015, "on": False})
    return {"name": "24 - Collapse", "post_process": pp, "entities": ents}



# ── 25 Cloth & Rope ───────────────────────────────────────────────────────
#
# A rope bridge over a gorge late in the day, a traveller crossing it, and
# flags and banners in a gusting wind. What to look at:
#   - the cloth: every flag and banner is a `cloth` - a grid of points the
#     engine moves each frame (wind that gusts, a flutter of curl noise,
#     gravity) and writes into the entity's mesh, the texture laid over the
#     grid, folds shaded darker;
#   - the bridge: planks on revolute joints, a real rapier chain, and the
#     traveller a character whose `push_mass` weighs it down - it dips
#     under each step;
#   - the ropes: `rope` components pinned to the planks and posts, so the
#     handrails and the deck ropes follow the bridge as it sways, and a
#     lantern's rope follows the lantern it hangs on.
# W changes the wind (calm, breeze, gale); Space hurries the traveller.

CB_DECK_Y = -40.0
CB_GAP = 390.0            # the bridge's posts at -CB_GAP and +CB_GAP
CB_PLANKS = 21
CB_PITCH = 40.0           # plank to plank, joint to joint
CB_PLANK = (36.0, 9.0)


def cb_bridge_points():
    """Where each plank's two joints sit at rest: a parabola through both
    posts whose length is the chain's, so the joints start satisfied."""
    length = CB_PLANKS * CB_PITCH
    lo, hi = 0.0, 400.0
    for _ in range(60):
        sag = (lo + hi) / 2
        xs = [-CB_GAP + 2 * CB_GAP * i / 400 for i in range(401)]
        ys = [CB_DECK_Y - sag * (1 - (x / CB_GAP) ** 2) for x in xs]
        arc = sum(math.hypot(xs[i + 1] - xs[i], ys[i + 1] - ys[i]) for i in range(400))
        lo, hi = (sag, hi) if arc < length else (lo, sag)
    # Walk the curve, a joint every CB_PITCH of arc.
    pts, acc, want = [(xs[0], ys[0])], 0.0, CB_PITCH
    for i in range(400):
        seg = math.hypot(xs[i + 1] - xs[i], ys[i + 1] - ys[i])
        while acc + seg >= want and len(pts) < CB_PLANKS + 1:
            f = (want - acc) / seg
            pts.append((xs[i] + (xs[i + 1] - xs[i]) * f, ys[i] + (ys[i + 1] - ys[i]) * f))
            want += CB_PITCH
        acc += seg
    pts[-1] = (CB_GAP, CB_DECK_Y)
    return pts


def cb_cloth(name, x, y, tex, size, grid, anchor, pin, z, wind, flutter, wave, colour=(1.0, 1.0, 1.0, 1.0)):
    return ent(name, transform=tr(x, y),
               mesh={"texture_id": tex, "color": list(colour), "z_order": z, "vertices": [], "indices": []},
               cloth={"size": list(size), "cols": grid[0], "rows": grid[1], "anchor": list(anchor), "pin": pin,
                      "gravity": [0.0, -450.0], "wind": list(wind), "gust": 0.35, "flutter": flutter,
                      "flutter_scale": 70.0, "wave": wave, "wave_length": 150.0, "wave_speed": 1.3, "damping": 1.2, "stiffness": 1.0, "iterations": 8, "bend": 0.25,
                      "shade": 0.5})


def cb_rope(name, x, y, z, length, segments, width, end="", end_offset=(0.0, 0.0), pins=(), start_offset=(0.0, 0.0),
            colour=(1.0, 1.0, 1.0, 1.0), wind=(0.0, 0.0)):
    return ent(name, transform=tr(x, y),
               mesh={"texture_id": "sprites/env/cb_rope.png", "color": list(colour), "z_order": z,
                     "vertices": [], "indices": []},
               rope={"length": length, "segments": segments, "width": width, "start_offset": list(start_offset),
                     "end": end, "end_offset": list(end_offset),
                     "pins": [{"at": a, "entity": e, "offset": list(o)} for a, e, o in pins],
                     "gravity": [0.0, -700.0], "wind": list(wind), "gust": 0.5, "damping": 2.0, "iterations": 16})


def cloth_and_rope():
    ents = [camera()]
    ents.append(ent("Sky", transform=tr(0, 0),
                    sprite=sprite("sprites/env/cb_sky.png", (W + 200, H + 200), (1.0, 1.0, 1.0, 1.0), z=-100)))
    ents.append(ent("Sun", transform=tr(-300, 120),
                    sprite=sprite("sprites/fx/glow.png", (620, 620), emissive(lin(1.0, 0.8, 0.55, 0.6), 1.3), z=-99),
                    material=additive()))
    ents.append(ent("PeaksFar", transform=tr(0, 40),
                    sprite=sprite("sprites/env/cb_peaks_far.png", (W + 200, 520), lin(1.0, 1.0, 1.0), z=-95,
                                  fill={"mode": "tile", "tile_size": [1024.0, 520.0]})))
    ents.append(ent("PeaksNear", transform=tr(120, -40),
                    sprite=sprite("sprites/env/cb_peaks_near.png", (W + 400, 520), lin(1.0, 1.0, 1.0), z=-90,
                                  fill={"mode": "tile", "tile_size": [1024.0, 520.0]})))
    ents.append(ent("GorgeFloor", transform=tr(0, -300),
                    sprite=sprite("", (W + 200, 200), lin(0.2, 0.2, 0.3), z=-89)))
    # Mist rising out of the gorge.
    ents.append(ent("Mist", transform=tr(0, -380), particle_emitter=emitter(
        texture_id="sprites/fx/smoke.png", emission_rate=5.0, max_particles=80, lifetime=[7.0, 11.0],
        speed=[8.0, 22.0], angle=[1.3, 1.85], size_start=[260.0, 380.0], size_end=[420.0, 620.0],
        color_curve=[[0.0] + lin(0.95, 0.88, 0.86, 0.0), [0.3] + lin(0.95, 0.88, 0.86, 0.2),
                     [1.0] + lin(0.9, 0.84, 0.86, 0.0)],
        emit_shape={"kind": "line", "length": 700.0}, z_order=-50,
        turbulence={"strength": 12.0, "scale": 300.0, "speed": 0.1})))
    # The two cliffs, their grass, and the posts the bridge hangs from.
    for side in (-1, 1):
        cx = side * (CB_GAP + 212)
        ents.append(ent(f"Cliff{'L' if side < 0 else 'R'}", transform=tr(cx, CB_DECK_Y + 4),
                        sprite=sprite("sprites/env/cb_cliff.png", (400, 420), lin(0.86, 0.8, 0.76), z=-10,
                                      anchor=(0.5, 1.0), fill={"mode": "tile", "tile_size": [300.0, 300.0]}),
                        rigid_body={"body_type": "Static", "mass": 1.0, "gravity_scale": 1.0, "linear_damping": 0.0,
                                    "angular_damping": 0.0, "fixed_rotation": True},
                        collider={"shape": {"Box": {"width": 400.0, "height": 420.0}}, "offset": [0.0, -210.0],
                                  "friction": 0.9, "restitution": 0.0}))
        ents.append(ent(f"Grass{'L' if side < 0 else 'R'}", transform=tr(cx, CB_DECK_Y + 4),
                        sprite=sprite("sprites/env/cb_grass.png", (400, 40), (1.0, 1.0, 1.0, 1.0), z=-4,
                                      anchor=(0.5, 0.38), fill={"mode": "tile", "tile_size": [256.0, 32.0]})))
        post_name = "PostL" if side < 0 else "PostR"
        ents.append(ent(post_name, transform=tr(side * CB_GAP, CB_DECK_Y),
                        sprite=sprite("sprites/env/cb_post.png", (16, 150), lin(0.85, 0.8, 0.75), z=4,
                                      anchor=(0.5, 0.3)),
                        rigid_body={"body_type": "Static", "mass": 1.0, "gravity_scale": 1.0, "linear_damping": 0.0,
                                    "angular_damping": 0.0, "fixed_rotation": True}))
    # The bridge: a chain of planks, each jointed to the one before; the
    # right post holds the last (one joint per entity).
    pts = cb_bridge_points()
    for i in range(CB_PLANKS):
        (x0, y0), (x1, y1) = pts[i], pts[i + 1]
        ang = math.atan2(y1 - y0, x1 - x0)
        target = "PostL" if i == 0 else f"Plank{i - 1}"
        anchor_b = [0.0, 0.0] if i == 0 else [CB_PITCH / 2, 0.0]
        ents.append(ent(f"Plank{i}", transform=tr((x0 + x1) / 2, (y0 + y1) / 2, ang),
                        sprite=sprite("sprites/env/cb_plank.png", (CB_PLANK[0], CB_PLANK[1] + 3), lin(1.0, 0.95, 0.9),
                                      z=2),
                        rigid_body={"body_type": "Dynamic", "mass": 3.0, "gravity_scale": 1.0, "linear_damping": 0.4,
                                    "angular_damping": 0.8, "fixed_rotation": False},
                        collider={"shape": {"Box": {"width": CB_PLANK[0], "height": CB_PLANK[1]}}, "friction": 0.9,
                                  "restitution": 0.0},
                        joint={"target_entity": target, "joint_type": {"Revolute": {
                            "anchor": [-CB_PITCH / 2, 0.0], "anchor_b": anchor_b, "limits": None,
                            "motor_speed": 0.0, "motor_max_torque": 0.0}}, "collide_connected": False}))
    for e in ents:
        if e["name"] == "PostR":
            e["components"]["joint"] = {"target_entity": f"Plank{CB_PLANKS - 1}", "joint_type": {"Revolute": {
                "anchor": [0.0, 0.0], "anchor_b": [CB_PITCH / 2, 0.0], "limits": None,
                "motor_speed": 0.0, "motor_max_torque": 0.0}}, "collide_connected": False}
    # Ropes: two under the deck, two handrails - each pinned to every plank,
    # so it rides the bridge and sags between.
    segs = CB_PLANKS * 3
    deck = [((i + 0.5) / CB_PLANKS, f"Plank{i}", (0.0, -4.0)) for i in range(CB_PLANKS)]
    rail = [((i + 0.5) / CB_PLANKS, f"Plank{i}", (0.0, 58.0)) for i in range(1, CB_PLANKS - 1, 2)]
    ents.append(cb_rope("DeckRope", -CB_GAP, CB_DECK_Y, 3, CB_PLANKS * CB_PITCH + 6, segs, 5.0,
                        end="PostR", end_offset=(0.0, -4.0), pins=deck, start_offset=(0.0, -4.0),
                        colour=lin(0.8, 0.72, 0.62)))
    ents.append(cb_rope("Rail", -CB_GAP, CB_DECK_Y, 8, CB_PLANKS * CB_PITCH * 0.9, segs, 5.0,
                        end="PostR", end_offset=(0.0, 60.0), pins=rail, start_offset=(0.0, 60.0),
                        colour=lin(0.85, 0.76, 0.64)))
    # Ties from the handrail down to every other plank.
    for i in range(1, CB_PLANKS - 1, 2):
        ents.append(cb_rope(f"Tie{i}", 0.0, 0.0, 7, 58.0, 4, 3.0, colour=lin(0.75, 0.68, 0.58)))
        ents[-1]["parent"] = f"Plank{i}"
        ents[-1]["components"]["rope"]["end"] = f"Plank{i}"
        ents[-1]["components"]["rope"]["end_offset"] = [0.0, 58.0]
    # The traveller: a character that weighs the bridge down.
    ents.append(ent("Walker", transform=tr(-560, CB_DECK_Y + 50),
                    sprite=sprite("sprites/env/cb_walker.png", (42, 66), lin(1.0, 0.95, 0.9), z=6, anchor=(0.5, 0.36)),
                    rigid_body={"body_type": "Kinematic", "mass": 1.0, "gravity_scale": 1.0, "linear_damping": 0.0,
                                "angular_damping": 0.0, "fixed_rotation": True},
                    collider={"shape": {"Capsule": {"half_height": 14.0, "radius": 10.0}}, "friction": 0.5,
                              "restitution": 0.0},
                    character_controller={"max_slope_deg": 60.0, "step_height": 16.0, "snap_to_ground": 14.0,
                                          "push_mass": 40.0}))
    # A flag on a tall pole each side, and a banner under each post's arm.
    wind = (900.0, 60.0)
    for name, x in (("FlagL", -620.0), ("FlagR", 520.0)):
        ents.append(ent(f"{name}Pole", transform=tr(x, CB_DECK_Y - 10),
                        sprite=sprite("sprites/env/cb_post.png", (10, 290), lin(0.7, 0.62, 0.55), z=3,
                                      anchor=(0.5, 0.0))))
        ents.append(cb_cloth(name, x + 4, CB_DECK_Y + 270, "sprites/env/cb_flag.png", (190, 88), (20, 10),
                             (0.0, 1.0), "Left", 3, wind, 300.0, 1600.0))
    for name, x in (("BannerL", -CB_GAP - 60), ("BannerR", CB_GAP + 60)):
        arm_x = x + (30 if x < 0 else -30)
        ents.append(ent(f"{name}Arm", transform=tr(arm_x, CB_DECK_Y + 104),
                        sprite=sprite("sprites/env/cb_post.png", (86, 10), lin(0.7, 0.62, 0.55), z=5)))
        ents.append(cb_cloth(name, x, CB_DECK_Y + 100, "sprites/env/cb_banner.png", (62, 150), (7, 14),
                             (0.5, 1.0), "Top", 5, (wind[0] * 0.35, 0.0), 150.0, 260.0))
    # A lantern on a rope at the end of each arm: a body on a rapier rope
    # joint, the rope drawn by a `rope` that follows it.
    for name, x in (("LanternL", -CB_GAP - 88), ("LanternR", CB_GAP + 88)):
        hook = f"{name}Hook"
        ents.append(ent(hook, transform=tr(x, CB_DECK_Y + 100),
                        rigid_body={"body_type": "Static", "mass": 1.0, "gravity_scale": 1.0, "linear_damping": 0.0,
                                    "angular_damping": 0.0, "fixed_rotation": True}))
        ents.append(ent(name, transform=tr(x, CB_DECK_Y + 40),
                        sprite=sprite("sprites/fx/lantern.png", (22, 30), (1.0, 1.0, 1.0, 1.0), z=6),
                        rigid_body={"body_type": "Dynamic", "mass": 1.0, "gravity_scale": 1.0, "linear_damping": 0.2,
                                    "angular_damping": 1.0, "fixed_rotation": False},
                        collider={"shape": {"Box": {"width": 18.0, "height": 26.0}}, "friction": 0.5,
                                  "restitution": 0.1, "is_sensor": True},
                        joint={"target_entity": hook, "joint_type": {"Rope": {
                            "anchor_a": [0.0, 13.0], "anchor_b": [0.0, 0.0], "max_distance": 48.0}},
                            "collide_connected": False}))
        ents.append(ent(f"{name}Glow", transform=tr(0, 0),
                        sprite=sprite("sprites/fx/glow.png", (90, 90), emissive(lin(1.0, 0.7, 0.35, 0.8), 1.6), z=7),
                        material=additive()))
        ents[-1]["parent"] = name
        ents.append(cb_rope(f"{name}Rope", x, CB_DECK_Y + 100, 5, 48.0, 8, 2.5, end=name, end_offset=(0.0, 13.0),
                            colour=lin(0.4, 0.35, 0.3)))
    ents += caption_entities(
        "25   Cloth & Rope",
        "W  wind   Space  hurry   1-4 post   Tab captions")
    ents.append(ent("Driver", transform=tr(), script=script("scripts/s25_cloth_rope.lua")))
    pp = post(
        bloom={"threshold": 1.1, "intensity": 0.4, "blur_size": 0.0},
        vignette={"intensity": 0.35, "smoothness": 0.6, "color": [0.08, 0.04, 0.06, 1.0]},
        grade={"brightness": 1.0, "contrast": 1.05, "saturation": 1.08, "tint": [1.0, 0.9, 0.8, 0.06]},
        chromatic={"strength": 0.0015, "on": False})
    return {"name": "25 - Cloth & Rope", "post_process": pp, "entities": ents}


