def write_cove_script():
    kelp = ", ".join(f"{{ x = {x} }}" for x, _ in SC_KELP)
    fish = ", ".join(f"{{ x = {x}, y = {y} }}" for x, y in SC_FISH)
    src = """-- 46 Sea Cove: swims the listener and keeps the cove alive. How it sounds is
-- the engine's: the cave and the water are `audio_zone`s, so the drips ring
-- once you are in the cave and the whole world goes dull under the surface.
-- Generated by tools/gen_scenes.py.

script = { tick_rate = 60 }

local nav = require("nav")
local SCENE = "scenes/46-sea-cove.scene"
local WATER_Y = %.1f
local SPEED = 230
local KELP = { %s }
local FISH = { %s }
local captions = true
local swimmer, bubbles, status, cave_zone, water_zone, music
local foams, gulls = {}, {}
local px, py = -300, WATER_Y + 6
local was_under = false
local zones_on, music_on = true, true
local t, facing = 0, 1

function init(entity)
    swimmer = Entity.find_by_name("Swimmer")
    bubbles = Entity.find_by_name("Bubbles")
    status = Entity.find_by_name("Status")
    cave_zone = Entity.find_by_name("CaveZone")
    water_zone = Entity.find_by_name("WaterZone")
    music = Entity.find_by_name("Music")
    for i = 1, 2 do
        foams[i] = Entity.find_by_name("Foam" .. i)
        gulls[i] = Entity.find_by_name("Gull" .. i)
    end
    for i, k in ipairs(KELP) do k.e = Entity.find_by_name("Kelp" .. i) end
    for i, f in ipairs(FISH) do f.e = Entity.find_by_name("Fish" .. i); f.phase = i * 1.7 end
end

local function held(a, b) return Input.is_key_pressed(a) or Input.is_key_pressed(b) end

function update(entity, dt)
    nav.tick(SCENE)
    if Input.is_key_just_pressed("Tab") then captions = nav.toggle_ui_captions(captions) end
    t = t + dt

    local dx, dy = 0, 0
    if held("A", "Left") then dx = dx - 1 end
    if held("D", "Right") then dx = dx + 1 end
    if held("W", "Up") then dy = dy + 1 end
    if held("S", "Down") then dy = dy - 1 end
    px = math.max(-600, math.min(600, px + dx * SPEED * dt))
    -- Swimmers float: above the surface only a little.
    py = math.max(-300, math.min(WATER_Y + 10, py + dy * SPEED * dt))
    if dx ~= 0 then facing = dx end
    local bob = (py >= WATER_Y - 2) and math.sin(t * 2.2) * 3 or 0
    if swimmer then
        Transform.set_position(swimmer, px, py + bob)
        Transform.set_scale(swimmer, facing, 1)
    end

    local under = py < WATER_Y - 12
    if under ~= was_under then
        Audio.play_sound_at("sounds/cove_splash.wav", px, WATER_Y, 0.8)
        was_under = under
    end
    if bubbles then
        Transform.set_position(bubbles, px + facing * 30, py + 6)
        Particles.set_active(bubbles, under)
    end

    if Input.is_key_just_pressed("E") then
        zones_on = not zones_on
        Transform.set_position(cave_zone, zones_on and 390 or 5000, 40)
        Transform.set_position(water_zone, zones_on and 0 or 5000, WATER_Y - 200)
    end
    if Input.is_key_just_pressed("M") and music then
        music_on = not music_on
        Audio.set_bus_volume("music", music_on and 1 or 0)
    end

    -- The cove moves: foam drifts, kelp sways, fish wander, gulls glide.
    for i, f in ipairs(foams) do
        if f then Transform.set_position(f, ((t * (i == 1 and 30 or -45)) %% 256) - 128, WATER_Y + (i - 1) * 3) end
    end
    for i, k in ipairs(KELP) do
        if k.e then Transform.set_rotation(k.e, 0.08 * math.sin(t * 0.9 + i * 1.3)) end
    end
    for _, f in ipairs(FISH) do
        if f.e then
            local s = math.sin(t * 0.35 + f.phase)
            Transform.set_position(f.e, f.x + 90 * s, f.y + 10 * math.sin(t * 1.3 + f.phase))
            Transform.set_scale(f.e, (math.cos(t * 0.35 + f.phase) >= 0) and 1 or -1, 1)
        end
    end
    for i, g in ipairs(gulls) do
        if g then
            local gx = ((t * (25 + 10 * i) + i * 500) %% 1600) - 800
            Transform.set_position(g, gx, 230 + 40 * i + 12 * math.sin(t * 0.8 + i))
        end
    end

    if status then
        local where = "open air"
        if under then where = "under water - everything muffled"
        elseif px > 200 and py > -60 then where = "in the cave - the drips ring" end
        if not zones_on then where = where .. "  (zones off)" end
        UI.set_text(status, where)
    end
end
""" % (SC_WATER_Y, kelp, fish)
    path = ASSETS / "scripts" / "s46_cove.lua"
    path.write_text(src, encoding="utf-8", newline="\n")


# ── 47 Autumn Run ──────────────────────────────────────────────────────
# A fox runs and jumps across autumn hills, and the camera is the subject:
# `camera_follow` with a **dead zone** (it holds while the fox moves inside
# a box, so jumps do not bob the view) and **look-ahead** (it leads the way
# the fox runs, so you see what is coming). Keys 1-4 switch between plain
# follow, dead zone, look-ahead and both, through Camera.set_follow; B draws
# the dead zone where Camera.get_position says the camera is. The parallax
# layers are placed from Camera.get_position too.

AR_GROUND = [(float(x), round(-170 + 60 * math.sin(x / 430) + 35 * math.sin(x / 170 + 1.3) + 18 * math.sin(x / 97), 1))
             for x in range(-1000, 7401, 60)]
AR_TREES = [(-300, 0.9), (420, 1.1), (900, 0.8), (1500, 1.2), (2150, 0.95), (2700, 1.05), (3300, 0.85),
            (3950, 1.15), (4500, 0.9), (5200, 1.1), (5800, 0.95), (6400, 1.0)]
AR_LAYERS = [("Mountains", "sprites/run/mountains.png", 0.12, -10.0, (1024.0, 512.0), -50),
             ("HillsFar", "sprites/run/hills.png", 0.35, -120.0, (1024.0, 512.0), -45)]
AR_RANGE = 6700.0


def ar_ground_y(x):
    xs = [p[0] for p in AR_GROUND]
    for i in range(1, len(xs)):
        if x <= xs[i]:
            (x0, y0), (x1, y1) = AR_GROUND[i - 1], AR_GROUND[i]
            return y0 + (y1 - y0) * (x - x0) / (x1 - x0)
    return AR_GROUND[-1][1]


def autumn_run():
    ents = [camera()]
    ents.append(ent("Sky", transform=tr(0, 0),
                    sprite=sprite("sprites/run/sky.png", (W + 200, H + 200), (1, 1, 1, 1), z=-60)))
    ents.append(ent("Sun", transform=tr(320, 150), unlit={}, material=additive(),
                    sprite=sprite("sprites/fx/glow.png", (420, 420), lin(1.0, 0.88, 0.6, 0.8), z=-58)))
    for name, tex, f, y, tile, z in AR_LAYERS:
        width = 2 * (AR_RANGE * f + 900)
        ents.append(ent(name, transform=tr(0, y),
                        sprite=sprite(tex, (width, tile[1]), (1, 1, 1, 1), z=z,
                                      fill={"mode": "tile", "tile_size": [tile[0], tile[1]]})))
    for i, (x, s) in enumerate(AR_TREES):
        ents.append(ent(f"Tree{i + 1}", transform=tr(x, ar_ground_y(x) - 20, 0.0, s, s),
                        sprite=sprite("sprites/run/tree.png", (220, 320), (1, 1, 1, 1), z=-20, anchor=(0.5, 0.0))))
    ents.append(ent("Ground", transform=tr(0, 0),
                    spline_shape=spline(AR_GROUND, smooth=False, fill_texture="sprites/env/rh_soil.png",
                                        edge_texture="sprites/run/edge.png", edge_width=64.0, edge_offset=0.5,
                                        fill_bottom=-900.0, collider=False, z_order=0)))
    ents.append(ent("Fox", transform=tr(0, ar_ground_y(0)),
                    sprite=sprite("sprites/run/fox.png", (104, 60), (1, 1, 1, 1), z=10, anchor=(0.5, 0.08)),
                    camera_follow={"smoothing": 0.12, "dead_zone": [360.0, 240.0], "look_ahead": 0.55,
                                   "look_ahead_max": 240.0, "bounds": [-250.0, -120.0, AR_RANGE - 50.0, 260.0]}))
    ents.append(ent("Leaves", transform=tr(0, 420), particle_emitter=emitter(
        texture_id="sprites/run/leaf.png", emission_rate=9.0, max_particles=140, lifetime=[6.0, 9.0],
        speed=[20.0, 60.0], angle=[3.5, 4.4], size_start=[11.0, 16.0], size_end=[11.0, 16.0],
        gravity_modifier=0.05, angular_velocity=[-3.0, 3.0], color_start=[1.0, 1.0, 1.0, 1.0],
        color_end=[1.0, 1.0, 1.0, 0.0], z_order=20, emit_shape={"kind": "rect", "size": [1700.0, 10.0]},
        turbulence={"strength": 40.0, "scale": 220.0, "speed": 0.4})))
    for side in ("Top", "Bottom", "Left", "Right"):
        ents.append(ent("Zone" + side, transform=tr(), unlit={},
                        sprite=sprite("__white", (1, 1), lin(1.0, 0.9, 0.5, 0.75), z=30)))
    ents.append(ent("Aim", transform=tr(), unlit={},
                    sprite=sprite("sprites/fx/ring.png", (26, 26), lin(1.0, 0.9, 0.5, 0.9), z=30)))
    ents += ui_captions("47   Autumn Run",
                        "A / D  run   Space  jump   1 follow   2 dead zone   3 look-ahead   4 both   B  box   Tab captions")
    ents.append(ent("Driver", transform=tr(), script=script("scripts/s47_run.lua")))
    pp = post(
        bloom={"threshold": 1.0, "intensity": 0.25, "blur_size": 0.0},
        vignette={"intensity": 0.35, "smoothness": 0.65, "color": [0.05, 0.02, 0.0, 1.0]},
        grade={"brightness": 1.02, "contrast": 1.05, "saturation": 1.1, "tint": [1.0, 0.92, 0.8, 0.05]},
        chromatic={"strength": 0.0015, "on": False})
    return {"name": "47 - Autumn Run", "post_process": pp, "entities": ents}


def write_run_script():
    ground = ", ".join(f"{{ {x}, {y} }}" for x, y in AR_GROUND)
    layers = ", ".join(f'{{ name = "{n}", f = {f}, y = {y} }}' for n, _, f, y, _, _ in AR_LAYERS)
    src = """-- 47 Autumn Run: runs the fox and switches how the camera follows it. The
-- following itself is the engine's - `camera_follow` with a dead zone and
-- look-ahead, changed by Camera.set_follow - and the parallax and the dead
-- zone box are placed from Camera.get_position. Generated by
-- tools/gen_scenes.py.

script = { tick_rate = 60 }

local nav = require("nav")
local SCENE = "scenes/47-autumn-run.scene"
local GROUND = { %s }
local LAYERS = { %s }
local RANGE = %.1f
local MODES = {
    { name = "plain follow", zone = { 0, 0 }, ahead = 0 },
    { name = "dead zone", zone = { 360, 240 }, ahead = 0 },
    { name = "look-ahead", zone = { 0, 0 }, ahead = 0.55 },
    { name = "dead zone + look-ahead", zone = { 360, 240 }, ahead = 0.55 },
}
local captions, show_box = true, true
local fox, leaves, aim, status, sky, sun
local bars = {}
local mode = 4
local x, y, vx, vy = 0, 0, 0, 0
local grounded, facing, t = true, 1, 0

local function ground_y(px)
    for i = 2, #GROUND do
        if px <= GROUND[i][1] then
            local a, b = GROUND[i - 1], GROUND[i]
            return a[2] + (b[2] - a[2]) * (px - a[1]) / (b[1] - a[1])
        end
    end
    return GROUND[#GROUND][2]
end

local function apply(m)
    mode = m
    Camera.set_follow(fox, "dead_zone", MODES[m].zone)
    Camera.set_follow(fox, "look_ahead", MODES[m].ahead)
end

function init(entity)
    fox = Entity.find_by_name("Fox")
    leaves = Entity.find_by_name("Leaves")
    aim = Entity.find_by_name("Aim")
    status = Entity.find_by_name("Status")
    sky = Entity.find_by_name("Sky")
    sun = Entity.find_by_name("Sun")
    for _, l in ipairs(LAYERS) do l.e = Entity.find_by_name(l.name) end
    for _, side in ipairs({ "Top", "Bottom", "Left", "Right" }) do bars[side] = Entity.find_by_name("Zone" .. side) end
    y = ground_y(x)
    apply(4)
end

local function held(a, b) return Input.is_key_pressed(a) or Input.is_key_pressed(b) end

function update(entity, dt)
    nav.tick(SCENE)
    if Input.is_key_just_pressed("Tab") then captions = nav.toggle_ui_captions(captions) end
    for i = 1, 4 do
        if Input.is_key_just_pressed(tostring(i)) then apply(i) end
    end
    if Input.is_key_just_pressed("B") then show_box = not show_box end
    t = t + dt

    -- Run and jump over the ground the spline shape draws.
    local want = 0
    if held("A", "Left") then want = want - 1 end
    if held("D", "Right") then want = want + 1 end
    if want ~= 0 then facing = want end
    vx = vx + (want * 420 - vx) * math.min(1, dt * (want ~= 0 and 3.5 or 5))
    if grounded and (Input.is_key_just_pressed("Space") or Input.is_key_just_pressed("W") or Input.is_key_just_pressed("Up")) then
        vy = 640
        grounded = false
    end
    x = math.max(-700, math.min(RANGE + 300, x + vx * dt))
    local g = ground_y(x)
    if not grounded then
        vy = vy - 1600 * dt
        y = y + vy * dt
        if y <= g then y = g; vy = 0; grounded = true end
    else
        y = g
    end
    local slope = (ground_y(x + 8) - ground_y(x - 8)) / 16
    local bob = (grounded and math.abs(vx) > 30) and math.abs(math.sin(t * 14)) * 4 or 0
    if fox then
        Transform.set_position(fox, x, y + bob)
        Transform.set_scale(fox, facing, 1)
        Transform.set_rotation(fox, grounded and math.atan(slope) * 0.8 or math.max(-0.35, math.min(0.35, vy * 0.0006 * facing)))
    end

    -- Parallax from where the camera is.
    local cx, cy = Camera.get_position()
    for _, l in ipairs(LAYERS) do
        if l.e then Transform.set_position(l.e, cx * (1 - l.f), l.y + cy * (1 - l.f) * 0.6) end
    end
    if sky then Transform.set_position(sky, cx, cy) end
    if sun then Transform.set_position(sun, cx + 320, cy + 150) end
    if leaves then Transform.set_position(leaves, cx + 200, cy + 420) end

    -- The dead zone, drawn round the camera's centre.
    local z = MODES[mode].zone
    local w, h = show_box and z[1] or 0, show_box and z[2] or 0
    Transform.set_position(bars.Top, cx, cy + h / 2)
    Transform.set_position(bars.Bottom, cx, cy - h / 2)
    Transform.set_position(bars.Left, cx - w / 2, cy)
    Transform.set_position(bars.Right, cx + w / 2, cy)
    Transform.set_scale(bars.Top, w, 3)
    Transform.set_scale(bars.Bottom, w, 3)
    Transform.set_scale(bars.Left, 3, h)
    Transform.set_scale(bars.Right, 3, h)
    if aim then
        Transform.set_position(aim, cx, cy)
        Transform.set_scale(aim, show_box and 1 or 0, show_box and 1 or 0)
    end
    if status then UI.set_text(status, "camera: " .. MODES[mode].name) end
end
""" % (ground, layers, AR_RANGE)
    path = ASSETS / "scripts" / "s47_run.lua"
    path.write_text(src, encoding="utf-8", newline="\n")


