    # The meadow: rows from far to near, blades and flowers in the same material.
    for k, (foot, height, width, count, tint, wind) in enumerate(WM_ROWS):
        uniforms = {"wind": {"Float": wind}}
        for i in range(count):
            x = rng.uniform(-W / 2 - 30, W / 2 + 30)
            y = foot + rng.uniform(-14, 14)
            h = height * rng.uniform(0.7, 1.25)
