# ── 65 Two Views of the Railway ─────────────────────────────────────────
# Model Railway's board as a split screen: the left half rides with the
# train, the right half with a car on the road, each turned so what it
# follows points up the screen, and the whole board in an inset map - three
# cameras, each given its part of the screen by one field (`screen_rect`).


def two_views_of_the_railway():
    scene = model_railway()
    keep = [e for e in scene["entities"] if e["name"] not in ("Title", "Hint", "Status", "Driver", "Camera")]

    def cam(name, zoom, rect):
        c = {"zoom": zoom, "is_active": True, "viewport_width": float(W), "viewport_height": float(H),
             "screen_rect": rect}
        return ent(name, transform=tr(), camera=c)

    # The main camera draws behind the three parts and shows only in the gap
    # between the halves: it looks at nothing, so the gap is a clean line.
    ents = [ent("Camera", transform=tr(40000, 40000), camera={"zoom": 1.0, "is_active": True,
                                                              "viewport_width": float(W), "viewport_height": float(H)})]
    ents.append(cam("TrainCam", 1.7, [0.0, 0.0, 0.497, 1.0]))
    ents.append(cam("CarCam", 1.7, [0.503, 0.0, 0.497, 1.0]))
    ents.append(cam("MapCam", 0.17, [0.38, 0.68, 0.24, 0.28]))
    # The table the board stands on, for where a turned view sees past it.
    ents.append(ent("Table", transform=tr(0, 0),
                    sprite=sprite("__white", (4200, 3400), lin(0.20, 0.12, 0.07), z=-110)))
    ents += keep
    ents += ui_captions("65   Two Views of the Railway",
                        "1  side by side   2  top / bottom   Space  turn with them / north up   Tab captions")
    ents.append(ent("Driver", transform=tr(), script=script("scripts/s65_two_views.lua")))
    pp = dict(scene["post_process"])
    pp["effects"] = [e for e in pp["effects"] if e["name"] != "tilt_shift"]
    return {"name": "65 - Two Views of the Railway", "post_process": pp, "entities": ents}


def write_two_views_script():
    src = """-- 65 Two Views of the Railway: three cameras, each drawing onto its own
-- part of the screen (`screen_rect`, changed with Camera.set_screen_rect).
-- This only moves them: each follows what it watches and turns with it, so
-- the train and the car point up their halves. Generated by tools/gen_scenes.py.

script = { tick_rate = 60 }

local nav = require("nav")
local SCENE = "scenes/65-two-views-of-the-railway.scene"
local captions, turning = true, true
local layout = 1
local train, car, train_cam, car_cam, map_cam, status
local LAYOUTS = {
    { { 0.0, 0.0, 0.497, 1.0 }, { 0.503, 0.0, 0.497, 1.0 }, { 0.38, 0.68, 0.24, 0.28 } },
    { { 0.0, 0.0, 1.0, 0.496 }, { 0.0, 0.504, 1.0, 0.496 }, { 0.74, 0.36, 0.24, 0.28 } },
}

function init(entity)
    train = Entity.find_by_name("Engine")
    car = Entity.find_by_name("Car2")
    train_cam = Entity.find_by_name("TrainCam")
    car_cam = Entity.find_by_name("CarCam")
    map_cam = Entity.find_by_name("MapCam")
    status = Entity.find_by_name("Status")
end

local function apply()
    local l = LAYOUTS[layout]
    Camera.set_screen_rect(train_cam, l[1][1], l[1][2], l[1][3], l[1][4])
    Camera.set_screen_rect(car_cam, l[2][1], l[2][2], l[2][3], l[2][4])
    Camera.set_screen_rect(map_cam, l[3][1], l[3][2], l[3][3], l[3][4])
end

local function follow(cam, what)
    if not (cam and what) then return end
    local x, y = Transform.get_world_position(what)
    Transform.set_position(cam, x, y)
    -- A camera turned anticlockwise swings the world clockwise: turned by
    -- the heading less a quarter, what it follows points up.
    Transform.set_rotation(cam, turning and (Transform.get_world_rotation(what) - math.pi / 2) or 0)
end

function update(entity, dt)
    nav.tick(SCENE)
    if Input.is_key_just_pressed("Tab") then captions = nav.toggle_ui_captions(captions) end
    if Input.is_key_just_pressed("1") then layout = 1; apply() end
    if Input.is_key_just_pressed("2") then layout = 2; apply() end
    if Input.is_key_just_pressed("Space") then turning = not turning end
    follow(train_cam, train)
    follow(car_cam, car)
    if status then
        UI.set_text(status, (layout == 1 and "side by side" or "top / bottom") .. (turning and "   turning" or "   north up"))
    end
end
"""
