# ── 66 Puppet Theatre ────────────────────────────────────────────────────
# A toy theatre's play, all of it one `timeline` on the stage manager: the
# curtains, the walk and bob of the card actors, the sun and moon on their
# arcs, the night backdrop fading in, the house and spot lights, the
# captions - tracks over any component's fields - and event keys that call
# its script for the thunder and the applause. It loops.

PT_FLOOR = -168.0   # where the actors stand


def pt_track(target, component, field, keys, ease="linear"):
    return {"target": target, "component": component, "field": field, "keys": keys, "ease": ease}


def pt_walk(t0, t1, x0, x1, step=0.4, lift=7.0):
    """Keys for a card actor walking: along x, bobbing up on every step."""
    keys = []
    n = max(1, int(round((t1 - t0) / step)))
    for i in range(n + 1):
        f = i / n
        keys.append([round(t0 + (t1 - t0) * f, 3), [round(x0 + (x1 - x0) * f, 1), PT_FLOOR + (lift if i % 2 else 0.0)]])
    return keys


def pt_rock(t0, t1, amount, step=0.4):
    return [[round(t0 + i * step, 3), amount if i % 2 else -amount] for i in range(int((t1 - t0) / step) + 1)]


def puppet_theatre():
    import math
    warm, night = [1.0, 0.85, 0.62], [0.45, 0.55, 1.0]
    ents = [camera()]
    ents.append(ent("Room", transform=tr(0, 0), unlit={}, sprite=sprite("__white", (W + 200, H + 200), lin(0.03, 0.02, 0.02), z=-200)))
