    ents.append(ent("CurtainL", transform=tr(-232, 0), sprite=sprite("sprites/theatre/curtain.png", (480, 520), (1, 1, 1, 1), z=-10)))
    ents.append(ent("CurtainR", transform=tr(232, 0), sprite=sprite("sprites/theatre/curtain.png", (480, 520), (1, 1, 1, 1), z=-10)))
