            pt_track("SpotL", "spot_light", "intensity", [[1.0, 0.0], [3.0, 2.6], [22.0, 2.6], [24.0, 0.0]]),
            pt_track("SpotR", "spot_light", "intensity", [[1.0, 0.0], [3.0, 2.6], [22.0, 2.6], [24.0, 0.0]]),
