            pt_track("SpotR", "spot_light", "color", [[9.0, warm], [10.5, night], [18.5, night], [19.5, warm]]),
            pt_track("Footlights", "point_light", "intensity", [[0.0, 0.3], [2.0, 1.6], [9.0, 1.6], [10.5, 0.5],
                                                               [18.5, 0.5], [19.5, 1.8], [23.0, 1.8], [25.0, 0.3]]),
