def write_moon_lander_script():
    src = """-- 68 Moon Lander: the autopilot is fixed_update - called once before every
-- physics step with the step's dt, reading where the module is after the
-- last step - so it flies the same whatever the frame rate. update only
-- draws the flame and the log. Generated by tools/gen_scenes.py.

script = { tick_rate = 60 }

local nav = require("nav")
local SCENE = "scenes/68-moon-lander.scene"
local PAD_X, PAD_Y = %.1f, %.1f
local MASS, G = 10, 162            -- the Moon's 1.62 m/s, a hundred units a metre
local MAX_UP, MAX_SIDE = 520, 90
local STARTS = { { -420, 220 }, { 470, 240 }, { -180, 260 }, { 300, 180 }, { -520, 120 } }
local captions = true
local module, flame, dust, dust_left, status
local landing, start, phase, wait = 0, 1, "flying", 0
local thrust, log = 0, ""

local function clamp(v, lo, hi) return math.max(lo, math.min(hi, v)) end

local function begin(i)
    start = i
    phase, wait, landing = "flying", 0, landing + 1
    Transform.set_position(module, STARTS[i][1], STARTS[i][2])
    Physics.set_velocity(module, (i %% 2 == 0) and -40 or 50, 0)
end

function init(entity)
    module = Entity.find_by_name("Module")
    flame = Entity.find_by_name("Flame")
    dust = Entity.find_by_name("Dust")
    dust_left = Entity.find_by_name("DustLeft")
    status = Entity.find_by_name("Status")
    Physics.set_gravity(0, -1.62)
    begin(1)
end

-- The autopilot, a step at a time: steer over the pad, and come down at a
-- speed that shrinks with the height left.
function fixed_update(entity, dt)
    if phase ~= "flying" then thrust = 0 return end
    local x, y = Transform.get_position(module)
    local vx, vy = Physics.get_velocity(module)
    local alt = y - 37 - (PAD_Y + 5)     -- the feet over the pad's top
    local ax = clamp((PAD_X - x) * 0.9 - vx * 1.8, -MAX_SIDE, MAX_SIDE)
    local want = -clamp(alt * 0.7, 12, 150)
    -- Not over the pad yet: hold a hundred and forty up, come down after.
    if math.abs(PAD_X - x) > 50 then want = math.max(want, clamp((140 - alt) * 1.2, -150, 80)) end
    local ay = clamp((want - vy) * 4 + G, 0, MAX_UP)
    thrust = ay / MAX_UP
    Physics.apply_force(module, ax * MASS, ay * MASS)
    if alt < 3 and math.abs(vy) < 25 then
        phase = "down"
        log = "landing " .. landing .. ":  " .. math.floor(math.abs(x - PAD_X) + 0.5) .. " from the pad's centre, touched at "
            .. string.format("%%.1f", math.abs(vy)) .. " a second"
        if dust then Particles.emit_burst(dust, 60) end
        if dust_left then Particles.emit_burst(dust_left, 60) end
    end
end

function update(entity, dt)
    nav.tick(SCENE)
    if Input.is_key_just_pressed("Tab") then captions = nav.toggle_ui_captions(captions) end
    if Input.is_key_just_pressed("Space") then begin(start %% #STARTS + 1) end
    if flame then Particles.set_rate(flame, 700 * thrust) end
    if phase == "down" then
        wait = wait + dt
        if wait > 3 then begin(start %% #STARTS + 1) end
    end
    if status then UI.set_text(status, log) end
end
""" % (ML_PAD_X, ML_PAD_Y)
    (ASSETS / "scripts" / "s68_moon_lander.lua").write_text(src, encoding="utf-8", newline="\n")


# ── 69 The Kraken ────────────────────────────────────────────────────────
# A ship in a storm, and tentacles rising out of the sea to coil about its
# masts. Each tentacle is eleven bones with an `ik_chain` on the last: FABRIK
# bends the whole limb so its tip reaches a target the script sweeps round a
# mast, and `max_bend` keeps every joint from folding sharper than a curl.
# The ship rocks on a looping timeline; lightning is a flash and a shake.

KR_SEGS = 11
KR_LEN = 40.0
KR_ROOTS = [(-330.0, -320.0), (-150.0, -335.0), (170.0, -335.0), (350.0, -320.0)]


def kr_tentacle(i, x, y):
    out = [ent(f"Tentacle{i}", transform=tr(x, y), skeleton_root={"name": f"t{i}"})]
    parent = f"Tentacle{i}"
    for k in range(KR_SEGS):
        name = f"T{i}Seg{k}"
        width = 46.0 - k * 3.2
        # At rest each joint curls a little, the outer pair inward.
        curl = (-0.16 if x < 0 else 0.16)
        comps = {
            "transform": tr(0 if k == 0 else KR_LEN, 0, 1.5708 if k == 0 else curl),
            "bone": {"name": name, "length": KR_LEN},
            "sprite": sprite("sprites/kraken/segment.png", (KR_LEN + width * 0.6, width), (1, 1, 1, 1), z=-5 + (i % 2),
                             anchor=(0.12, 0.5)),
        }
        if k == KR_SEGS - 1:
            comps["ik_chain"] = {"target": [x, y + 300], "bones": KR_SEGS, "iterations": 14, "tolerance": 0.5,
                                 "max_bend": 0.45, "weight": 1.0}
        out.append({"name": name, "parent": parent, "components": comps})
        parent = name
    return out


def the_kraken():
    ents = [camera()]
    ents.append(ent("Sky", transform=tr(0, 60), unlit={}, sprite=sprite("sprites/kraken/sky.png", (W + 120, H + 160), (1, 1, 1, 1), z=-100)))
    ents.append(ent("Clouds", transform=tr(0, 230), unlit={}, oscillator={"amplitude": [60.0, 0.0], "frequency": [0.02, 0.0]},
                    sprite=sprite("sprites/kraken/clouds.png", (W + 400, 330), (1, 1, 1, 1), z=-95)))
    ents.append(ent("WavesBack", transform=tr(0, -170), unlit={}, oscillator={"amplitude": [40.0, 6.0], "frequency": [0.07, 0.25]},
                    sprite=sprite("sprites/kraken/waves.png", (W + 300, 200), lin(0.8, 0.85, 0.9), z=-30,
                                  fill={"mode": "tile", "tile_size": [512.0, 200.0]})))
    ents.append(ent("Ship", transform=tr(0, -60), unlit={}, sprite=sprite("sprites/kraken/ship.png", (360, 330), (1, 1, 1, 1), z=-10)))
    for i, (x, y) in enumerate(KR_ROOTS):
        ents += kr_tentacle(i, x, y)
    ents.append(ent("WavesFront", transform=tr(0, -300), unlit={}, oscillator={"amplitude": [-55.0, 8.0], "frequency": [0.09, 0.3]},
                    sprite=sprite("sprites/kraken/waves.png", (W + 300, 230), (1, 1, 1, 1), z=20,
                                  fill={"mode": "tile", "tile_size": [512.0, 230.0]})))
    ents.append(ent("Rain", transform=tr(0, 400), unlit={}, particle_emitter=emitter(
        texture_id="__white", emission_rate=260.0, max_particles=900, lifetime=[0.9, 1.3], speed=[700.0, 900.0],
        angle=[4.35, 4.45], size_start=[1.5, 2.0], size_end=[1.5, 2.0], stretch=0.03,
        color_start=list(lin(0.7, 0.75, 0.85, 0.35)), color_end=list(lin(0.7, 0.75, 0.85, 0.2)), z_order=30,
        emit_shape={"kind": "rect", "size": [1700.0, 10.0]})))
    ents.append(ent("Flash", transform=tr(), unlit={}, material=additive(),
                    sprite=sprite("__white", (W + 200, H + 200), lin(0.75, 0.8, 1.0, 0.0), z=40)))
    rock = [[round(k * 0.75, 3), v] for k, v in enumerate([0.0, 0.07, 0.0, -0.06, 0.0, 0.08, 0.0, -0.05, 0.0])]
    bob = [[round(k * 0.75, 3), [0.0, -60.0 + (8.0 if k % 2 else -4.0)]] for k in range(9)]
    flash = [[0.0, 0.0], [2.2, 0.0], [2.25, 0.55], [2.5, 0.05], [2.6, 0.4], [2.9, 0.0], [6.0, 0.0]]
    storm = {"duration": 6.0, "tracks": [
        {"target": "Ship", "component": "transform", "field": "rotation", "keys": rock, "ease": "in_out"},
        {"target": "Ship", "component": "transform", "field": "position", "keys": bob, "ease": "in_out"},
        {"target": "Flash", "component": "sprite", "field": "color.3", "keys": flash},
    ], "events": [[2.25, "thunder"]]}
    ents.append(ent("Storm", transform=tr(), timeline={"clips": {"storm": storm}, "looping": True},
                    script=script("scripts/s69_kraken.lua")))
    ents += ui_captions("69   The Kraken", "Space  the kraken lets go / takes hold   Tab captions")
    pp = post(
        bloom={"threshold": 0.9, "intensity": 0.4, "blur_size": 0.0},
        vignette={"intensity": 0.6, "smoothness": 0.55, "color": [0.0, 0.0, 0.02, 1.0]},
        grade={"brightness": 1.0, "contrast": 1.08, "saturation": 0.95, "tint": [0.85, 0.95, 1.0, 0.08]},
        chromatic={"strength": 0.0015, "on": False})
    return {"name": "69 - The Kraken", "post_process": pp, "entities": ents}


def write_kraken_script():
    src = """-- 69 The Kraken: each tentacle is eleven bones with an ik_chain on the last;
-- this sweeps each chain's target about a mast (Skeleton.set_ik_target) and
-- FABRIK bends the whole limb to it. The storm - the ship's rocking, the
-- lightning - is the timeline on this entity; its event key calls on_thunder.
-- Generated by tools/gen_scenes.py.

script = { tick_rate = 60 }

local nav = require("nav")
local SCENE = "scenes/69-the-kraken.scene"
local N, SEGS = %d, %d
local ROOTS = { %s }
local captions, holding = true, true
local ends, ship = {}, nil
local t = 0

function init(entity)
    ship = Entity.find_by_name("Ship")
    for i = 0, N - 1 do ends[i] = Entity.find_by_name("T" .. i .. "Seg" .. (SEGS - 1)) end
end

function on_thunder(entity)
    Camera.shake(6, 0.4, 16)
end

function update(entity, dt)
    nav.tick(SCENE)
    if Input.is_key_just_pressed("Tab") then captions = nav.toggle_ui_captions(captions) end
    if Input.is_key_just_pressed("Space") then holding = not holding end
    t = t + dt
    local sx, sy = Transform.get_position(ship)
    local rot = Transform.get_rotation(ship)
    for i = 0, N - 1 do
        local e = ends[i]
        if e then
            local root = ROOTS[i + 1]
            local tx, ty
            if holding then
                -- A point on a mast that turns with the ship, swept in a loop.
                local mast = (i < 2) and -50 or 60
                local up = 40 + 60 * (0.5 + 0.5 * math.sin(t * 0.7 + i * 1.7))
                local lx, ly = mast + 55 * math.cos(t * 1.3 + i), up + 30 * math.sin(t * 1.1 + i * 2)
                tx = sx + lx * math.cos(rot) - ly * math.sin(rot)
                ty = sy + lx * math.sin(rot) + ly * math.cos(rot)
            else
                -- Let go: the tentacles wave above the water.
                tx = root[1] + 90 * math.sin(t * 0.9 + i * 1.3)
                ty = root[2] + 230 + 50 * math.sin(t * 1.4 + i)
            end
            Skeleton.set_ik_target(e, tx, ty)
        end
    end
end
""" % (len(KR_ROOTS), KR_SEGS, ", ".join("{ %.1f, %.1f }" % r for r in KR_ROOTS))
    (ASSETS / "scripts" / "s69_kraken.lua").write_text(src, encoding="utf-8", newline="\n")


# ── 70 Eight Ways ────────────────────────────────────────────────────────
# A top-down ranger crossing a forest clearing, always aiming at a hay
# target while it walks, runs and stops in every direction. Its body turns
# to aim; its feet step the way it is actually going *relative to that aim*
# - forwards, backwards, sideways, and every diagonal between - because the
# skeletal player is a 2D blend space of nine clips (idle, and a walk and a
# run each way), steered by the velocity turned into the body's frame. The
# inset at the bottom right is the blend space itself, its dot the position.

RG_WALK, RG_RUN = 95.0, 200.0
RG_DIRS = {"fwd": (1.0, 0.0), "back": (-1.0, 0.0), "left": (0.0, 1.0), "right": (0.0, -1.0)}
RG_GAITS = {"walk": {"period": 0.9, "stride": 15.0, "lift": 0.3, "sway": 0.14},
            "run": {"period": 0.56, "stride": 23.0, "lift": 0.45, "sway": 0.22}}
RG_TARGETS = [(-430.0, 170.0), (440.0, 205.0), (360.0, -215.0), (-400.0, -200.0)]
RG_INSET = (520.0, -235.0, 34.0)


def rg_clip(name, gait, d):
    """One clip: the feet stepping along `d` (the body's frame, +x ahead)."""
    import math as m
    n = 24
    keys = {"foot_l": [], "foot_r": [], "chest": []}
    if gait is None:
        period = 1.6
        for i in range(n + 1):
            ph = i / n
            t = round(ph * period, 5)
            keys["foot_l"].append((t, (-2.0, 14.0), 1.0))
            keys["foot_r"].append((t, (-2.0, -14.0), 1.0))
            keys["chest"].append((t, 0.0, 1.0 + 0.03 * m.sin(m.tau * ph)))
    else:
        g = RG_GAITS[gait]
        period = g["period"]
        side = abs(d[1]) > 0
        a = g["stride"] * (0.6 if side else 1.0)
        for i in range(n + 1):
            ph = i / n
            t = round(ph * period, 5)
            s, c = m.sin(m.tau * ph), m.cos(m.tau * ph)
            # The feet swing in antiphase along the way of travel; the one
            # swinging forward is lifted (drawn bigger).
            keys["foot_l"].append((t, (-2.0 + d[0] * a * s, 14.0 + d[1] * a * s), 1.0 + g["lift"] * max(0.0, c)))
            keys["foot_r"].append((t, (-2.0 - d[0] * a * s, -14.0 - d[1] * a * s), 1.0 + g["lift"] * max(0.0, -c)))
            # Shoulders counter the stride when walking ahead or back.
            keys["chest"].append((t, -g["sway"] * s * d[0], 1.0))
    tracks = []
    for bone in ("foot_l", "foot_r"):
        tracks.append({"bone_name": bone,
                       "position": [{"time": t, "value": [round(p[0], 3), round(p[1], 3)]} for t, p, _ in keys[bone]],
                       "scale": [{"time": t, "value": [round(k, 4), round(k, 4)]} for t, _, k in keys[bone]]})
    tracks.append({"bone_name": "chest",
                   "rotation": [{"time": t, "value": round(r, 5)} for t, r, _ in keys["chest"]],
                   "scale": [{"time": t, "value": [round(k, 4), round(k, 4)]} for t, _, k in keys["chest"]]})
    return {"name": name, "duration": period, "tracks": tracks}


def rg_points():
    pts = [("animations/rg_idle.skelanim", [0.0, 0.0])]
    for gait, r in (("walk", 1.0), ("run", 2.0)):
        for dn, d in RG_DIRS.items():
            pts.append((f"animations/rg_{gait}_{dn}.skelanim", [d[0] * r, d[1] * r]))
    return pts


def write_ranger_clips():
    import json as _json
    docs = {"animations/rg_idle.skelanim": rg_clip("rg_idle", None, (0.0, 0.0))}
    for gait in RG_GAITS:
        for dn, d in RG_DIRS.items():
            docs[f"animations/rg_{gait}_{dn}.skelanim"] = rg_clip(f"rg_{gait}_{dn}", gait, d)
    for path, doc in docs.items():
        out = ASSETS / path
        out.parent.mkdir(parents=True, exist_ok=True)
        out.write_text(_json.dumps(doc, indent=1) + "\n", encoding="utf-8", newline="\n")


