# ── 73 Spirograph ────────────────────────────────────────────────────────
# Wire figures turning on dark paper - hypotrochoids, a gear rolling inside
# a ring with a pen through it - drawn as 2-pixel lines, and a pen tracing
# the large one with a glowing trail. Every edge here is thin and turning,
# which is exactly what stair-steps without anti-aliasing: the `fxaa` post
# effect blends the stairs. F switches it to compare.

import math as _sp_math

SP_FIGURES = [
    # name, centre, R, r, d, scale, width, colour from, colour to, spin
    ("Rose", (0.0, 10.0), 96, 36, 60, 1.75, 2.0, (1.0, 0.75, 0.35), (1.0, 0.35, 0.55), 0.05),
    ("Tide", (-440.0, 170.0), 75, 25, 40, 1.1, 1.6, (0.35, 0.85, 0.95), (0.3, 0.5, 1.0), -0.12),
    ("Iris", (440.0, 170.0), 100, 35, 75, 0.95, 1.6, (0.75, 0.5, 1.0), (1.0, 0.45, 0.8), 0.09),
    ("Fern", (-440.0, -170.0), 80, 48, 32, 1.25, 1.6, (0.5, 1.0, 0.55), (0.9, 1.0, 0.4), 0.1),
    ("Ember", (440.0, -170.0), 90, 27, 55, 1.05, 1.6, (1.0, 0.6, 0.25), (1.0, 0.9, 0.5), -0.08),
]


def sp_curve(R, r, d, scale, steps_per_turn=160):
    turns = r // _sp_math.gcd(R, r)
    n = steps_per_turn * turns
    pts = []
    for i in range(n):
        t = i / n * 2 * _sp_math.pi * turns
        x = (R - r) * _sp_math.cos(t) + d * _sp_math.cos((R - r) / r * t)
        y = (R - r) * _sp_math.sin(t) - d * _sp_math.sin((R - r) / r * t)
        pts.append([round(x * scale, 2), round(y * scale, 2)])
    return pts


def spirograph():
    ents = [camera()]
    ents.append(ent("Paper", transform=tr(), unlit={}, sprite=sprite("sprites/spiro/paper.png", (W + 80, H + 80), (1, 1, 1, 1), z=-100,
                                                                     fill={"mode": "tile", "tile_size": [256.0, 256.0]})))
    for name, (cx, cy), R, r, d, scale, width, c0, c1, _spin in SP_FIGURES:
        g0, g1 = lin(*c0), lin(*c1)
        stops = [[0.0, *g0[:3], 0.9], [0.5, *g1[:3], 0.9], [1.0, *g0[:3], 0.9]]
        ents.append(ent(name, transform=tr(cx, cy), unlit={}, line={
            "points": sp_curve(R, r, d, scale), "closed": True, "width": width, "color": [1.0, 1.0, 1.0, 1.0],
            "gradient": stops, "joint": "bevel", "z_order": 5, "blend_mode": "Additive"}))
    # The pen on the large figure, its trail the line it draws.
    ents.append(ent("Pen", transform=tr(0, 10), unlit={},
                    sprite=sprite("sprites/fx/soft_dot.png", (18, 18), lin(1.0, 0.95, 0.8), z=8),
                    material=additive(),
                    trail={"lifetime": 2.2, "width": 3.0, "width_end": 0.5, "color": list(lin(1.0, 0.95, 0.75, 1.0)),
                           "color_end": list(lin(1.0, 0.5, 0.4, 0.0)), "min_distance": 2.0, "z_order": 7,
                           "emitting": True, "blend_mode": "Additive"}))
    ents.append(ent("Driver", transform=tr(), script=script("scripts/s73_spirograph.lua")))
    ents += ui_captions("73   Spirograph", "F  anti-aliasing on / off   Tab captions")
    pp = post(
        bloom={"threshold": 0.7, "intensity": 0.55, "blur_size": 0.0},
        vignette={"intensity": 0.5, "smoothness": 0.6, "color": [0.0, 0.0, 0.02, 1.0]},
        grade={"brightness": 1.0, "contrast": 1.05, "saturation": 1.05, "tint": [1.0, 1.0, 1.0, 0.0]},
        chromatic={"strength": 0.0015, "on": False})
    pp["effects"].append({"name": "fxaa", "enabled": True, "params": {"span": {"Float": 8.0}}})
    return {"name": "73 - Spirograph", "post_process": pp, "entities": ents}


def write_spirograph_script():
    name, (cx, cy), R, r, d, scale = SP_FIGURES[0][:6]
    spins = ", ".join("{ \"%s\", %s }" % (f[0], f[9]) for f in SP_FIGURES)
    src = """-- 73 Spirograph: wire figures turning, and a pen tracing the large one
-- with a trail. Every edge is thin and turning - what stair-steps without
-- anti-aliasing; the scene's `fxaa` post effect blends the stairs, and F
-- switches it (PostProcess.set_enabled). Generated by tools/gen_scenes.py.

script = { tick_rate = 60 }

local nav = require("nav")
local SCENE = "scenes/73-spirograph.scene"
local SPINS = { %s }
local CX, CY, R, r, d, S = %s, %s, %s, %s, %s, %s
local captions, aa = true, true
local figures, pen, status = {}, nil, nil
local t, u = 0, 0

function init(entity)
    for i, f in ipairs(SPINS) do figures[i] = { e = Entity.find_by_name(f[1]), spin = f[2] } end
    pen = Entity.find_by_name("Pen")
    status = Entity.find_by_name("Status")
end

function update(entity, dt)
    nav.tick(SCENE)
    if Input.is_key_just_pressed("Tab") then captions = nav.toggle_ui_captions(captions) end
    if Input.is_key_just_pressed("F") then
        aa = not aa
        PostProcess.set_enabled("fxaa", aa)
    end
    t = t + dt
    for _, f in ipairs(figures) do
        if f.e then Transform.set_rotation(f.e, t * f.spin) end
    end
    -- The pen runs along the large figure, turning with it.
    u = u + dt * 1.6
    local x = (R - r) * math.cos(u) + d * math.cos((R - r) / r * u)
    local y = (R - r) * math.sin(u) - d * math.sin((R - r) / r * u)
    local a = t * figures[1].spin
    local px, py = (x * math.cos(a) - y * math.sin(a)) * S, (x * math.sin(a) + y * math.cos(a)) * S
    if pen then Transform.set_position(pen, CX + px, CY + py) end
    if status then UI.set_text(status, "anti-aliasing " .. (aa and "on (fxaa)" or "off")) end
end
""" % (spins, cx, cy, R, r, d, scale)
    (ASSETS / "scripts" / "s73_spirograph.lua").write_text(src, encoding="utf-8", newline="\n")


# ── 74 Baggage Claim ─────────────────────────────────────────────────────
# Bags come through the rubber flaps of a hatch, ride a sloping belt down
# onto the long belt below, ride it to the far end and tumble off onto a
# heap. Each belt is a static collider with a `conveyor`: what rests on it
# is carried by friction while the collider never moves (the slats are
# sprites sliding with `velocity` + `wrap_bounds`, for the eye). The bags
# are prefabs with `sprite_collider`, so the heap settles by their shapes.

BC_BAGS = {
    # name: size (the sprite's own), mass
    "case_red": ((120, 90), 18.0),
    "case_blue": ((100, 78), 14.0),
    "case_silver": ((90, 104), 16.0),
    "duffel": ((140, 64), 10.0),
    "backpack": ((76, 96), 8.0),
    "guitar": ((190, 66), 9.0),
    "box": ((96, 72), 12.0),
}
BC_FEED = ((560.0, 150.0), (250.0, 30.0), 170.0)     # from, to, speed
BC_MAIN = ((330.0, -70.0), (-490.0, -70.0), 150.0)
BC_FLOOR = -300.0


def baggage_prefabs():
    out = {}
    for name, ((w, h), mass) in BC_BAGS.items():
        out[f"Bc_{name}"] = prefab(
            f"Bc_{name}",
            sprite=sprite(f"sprites/baggage/{name}.png", (w, h), (1, 1, 1, 1), z=6),
            rigid_body={"body_type": "Dynamic", "mass": mass, "gravity_scale": 1.0, "linear_damping": 0.05,
                        "angular_damping": 0.4, "fixed_rotation": False, "ccd": False},
            collider={"shape": {"Box": {"width": float(w), "height": float(h)}}, "friction": 0.8, "restitution": 0.05},
            sprite_collider={"alpha_cutoff": 0.5, "alpha_tolerance": 1.5})
    return out


def bc_belt(ents, name, a, b, speed, slat_z=3):
    import math as m
    (x0, y0), (x1, y1) = a, b
    dx, dy = x1 - x0, y1 - y0
    length = m.hypot(dx, dy)
    rot = m.atan2(dy, dx)  # +x runs from `a` to `b`
    cx, cy = (x0 + x1) / 2, (y0 + y1) / 2
    ux, uy = dx / length, dy / length
    # The belt: a static collider whose surface runs at `speed`.
    ents.append(ent(name, transform=tr(cx, cy, rot=rot), rigid_body={"body_type": "Static"},
                    collider={"shape": {"Box": {"width": length, "height": 16.0}}, "friction": 0.9},
                    conveyor={"speed": speed}))
    # Its frame, under the slats.
    nx, ny = -uy, ux  # the belt's up
    ents.append(ent(f"{name}Frame", transform=tr(cx - nx * 12, cy - ny * 12, rot=rot), unlit={},
                    sprite=sprite("sprites/baggage/frame.png", (length + 20, 22), (1, 1, 1, 1), z=slat_z - 1,
                                  fill={"mode": "tile", "tile_size": [128.0, 22.0]})))
    # The slats, sliding along it and wrapping at its ends.
    n = int(length // 41)
    lo = [min(x0, x1) - 0.5, min(y0, y1) - 0.5]
    hi = [max(x0, x1) + 0.5, max(y0, y1) + 0.5]
    for k in range(n):
        t = (k + 0.5) / n
        ents.append(ent(f"{name}Slat{k}", transform=tr(x0 + dx * t + nx * 2, y0 + dy * t + ny * 2, rot=rot), unlit={},
                        sprite=sprite("sprites/baggage/slat.png", (40, 14), (1, 1, 1, 1), z=slat_z),
                        velocity={"x": round(ux * speed, 3), "y": round(uy * speed, 3), "gravity": 0.0},
                        wrap_bounds={"min": lo, "max": hi}))


def baggage_claim():
    B = "sprites/baggage/"
    ents = [camera()]
    ents.append(ent("Wall", transform=tr(0, 60), unlit={}, sprite=sprite(B + "wall.png", (W + 80, H + 80), (1, 1, 1, 1), z=-100,
                                                                         fill={"mode": "tile", "tile_size": [256.0, 256.0]})))
    ents.append(ent("Window", transform=tr(-60, 170), unlit={}, sprite=sprite(B + "window.png", (900, 194), (1, 1, 1, 1), z=-90)))
    ents.append(ent("Floor", transform=tr(0, BC_FLOOR - 40), unlit={},
                    sprite=sprite(B + "floor.png", (W + 80, 80), (1, 1, 1, 1), z=-20, fill={"mode": "tile", "tile_size": [256.0, 80.0]}),
                    rigid_body={"body_type": "Static"},
                    collider={"shape": {"Box": {"width": float(W + 200), "height": 80.0}}, "friction": 0.8}))
    for name, x in (("WallL", -W / 2 - 20), ("WallR", W / 2 + 20)):
        ents.append(ent(name, transform=tr(x, 0), rigid_body={"body_type": "Static"},
                        collider={"shape": {"Box": {"width": 40.0, "height": 1400.0}}}))
    (fa, fb, fs), (ma, mb, ms) = BC_FEED, BC_MAIN
    bc_belt(ents, "Feed", fa, fb, fs)
    bc_belt(ents, "Main", ma, mb, ms)
    # The hatch the bags come through, its flaps in front of them.
    ents.append(ent("Hatch", transform=tr(600, 210), unlit={}, sprite=sprite("__white", (150, 130), lin(0.02, 0.02, 0.03), z=-5)))
    ents.append(ent("Flaps", transform=tr(600, 214), unlit={}, sprite=sprite(B + "flaps.png", (140, 112), (1, 1, 1, 0.92), z=12)))
    ents.append(ent("Sign", transform=tr(150, 300), unlit={}, sprite=sprite(B + "sign.png", (300, 76), (1, 1, 1, 1), z=-80)))
    ents.append(ent("SignText", transform=tr(150, 316), unlit={}, text={
        "text": "BAGGAGE CLAIM  3", "font_id": "", "font_scale": 1.6, "color": list(lin(0.08, 0.06, 0.02)),
        "z_order": -79, "align": "center"}))
    ents.append(ent("SignFlight", transform=tr(150, 288), unlit={}, text={
        "text": "AY 1234   HELSINKI   ON BELT", "font_id": "", "font_scale": 0.9, "color": list(lin(0.12, 0.09, 0.03)),
        "z_order": -79, "align": "center"}))
    ents.append(ent("Driver", transform=tr(), script=script("scripts/s74_baggage_claim.lua")))
    ents += ui_captions("74   Baggage Claim", "F4 colliders   Tab captions")
    pp = post(
        bloom={"threshold": 0.9, "intensity": 0.2, "blur_size": 0.0},
        vignette={"intensity": 0.45, "smoothness": 0.6, "color": [0.0, 0.0, 0.02, 1.0]},
        grade={"brightness": 1.0, "contrast": 1.05, "saturation": 1.0, "tint": [0.95, 0.97, 1.0, 0.05]},
        chromatic={"strength": 0.0015, "on": False})
    pp["effects"].append({"name": "fxaa", "enabled": True, "params": {"span": {"Float": 8.0}}})
    return {"name": "74 - Baggage Claim", "post_process": pp, "entities": ents}


def write_baggage_claim_script():
    names = ", ".join('"Bc_%s"' % n for n in BC_BAGS)
