def write_stained_light_script():
    src = """-- 82 Stained Light: the sun through coloured glass onto the floor, and
-- `global_illumination` bouncing it on to the wall and the pillars. The sun
-- drifts, so the patches walk across the floor and the glow follows them.
-- Generated by tools/gen_scenes.py.

script = { tick_rate = 60 }

local nav = require("nav")
local SCENE = "scenes/82-stained-light.scene"
local SUN = %s
local captions = true
local sun, status
local shafts = {}
local bounce = true
local t = 0

local function show()
    UI.set_text(status, "bounce light " .. (bounce and "on" or "off"))
end

function init(entity)
    sun = Entity.find_by_name("Sun")
    status = Entity.find_by_name("Status")
    for i = 1, 4 do shafts[i] = Entity.find_by_name("Shaft" .. (i - 1)) end
    show()
end

function update(entity, dt)
    nav.tick(SCENE)
    t = t + dt
    if Input.is_key_just_pressed("Tab") then captions = nav.toggle_ui_captions(captions) end
    if Input.is_key_just_pressed("G") then
        bounce = not bounce
        Lighting.set_global_illumination(bounce and 3 or 0)
        show()
    end
    -- The sun drifts: the light turns a little either way of where it was.
    local turn = math.sin(t * 0.12) * 0.1
    Transform.set_rotation(sun, turn)
    for _, e in ipairs(shafts) do Transform.set_rotation(e, SUN + turn) end
end
""" % CH_SUN
    (ASSETS / "scripts" / "s82_stained_light.lua").write_text(src, encoding="utf-8", newline="\n")


# ── 83 Siege Workshop ────────────────────────────────────────────────────
# A castle's siege yard. Every engine here is ONE prefab that is a
# hierarchy (`children` in the .prefab): a catapult is a frame, two wheels,
# an upright, a throwing arm with a bucket on it and a stone in that - seven
# entities from one `spawn_prefab`. The wheels are themselves a prefab
# (SwWheel) the others name as parts, a ballista's head is a part with parts
# of its own (stock, bow, bolt) that tilts as one, and the royal catapult is
# a variant of the catapult that adds a banner to the parts it inherits.
# Three stand on show, working: the script finds their arms and bolts with
# `Entity.find_child`. Below them a parade rolls out of the gate, each
# engine one spawn, its wheels turned by how far it has gone.

SW_KINDS = {
    # prefab: (root height above the road, parts)
    "SwCatapult": (56.0, 7),
    "SwBallista": (48.0, 8),
    "SwWagon": (62.0, 9),
    "SwRoyalCatapult": (56.0, 9),
}
SW_ROAD = -292.0
SW_PARADE = 0.8   # the parade's engines are scaled, parts and all
SW_SHOW = -40.0
SW_SHOWN = [
    # name, prefab, x, plaque
    ("ShowCatapult", "SwCatapult", -420.0, "CATAPULT  -  one prefab, 7 parts"),
    ("ShowBallista", "SwBallista", 0.0, "BALLISTA  -  its head a part with parts"),
    ("ShowRoyal", "SwRoyalCatapult", 420.0, "ROYAL CATAPULT  -  a variant + a banner"),
]


def sw_part(name, tex, size, x, y, z, rot=0.0, anchor=(0.5, 0.5), color=(1, 1, 1, 1), children=None, **extra):
    comps = {"transform": tr(x, y, rot=rot)}
    if tex:
        comps["sprite"] = sprite("sprites/siegeworks/" + tex, size, color, z=z, anchor=anchor)
    comps.update(extra)
    node = {"name": name, "components": comps}
    if children:
        node["children"] = children
    return node


def sw_wheel(name, x, y, size=None):
    over = {"sprite.size": [float(size), float(size)]} if size else {}
    return {"name": name, "components": {"transform": tr(x, y),
                                         "prefab_instance": {"prefab_id": "SwWheel", "overrides": over}}}


