        sw_part("Arm", "arm.png", (22, 170), 30, 14, 6, rot=1.25, anchor=(0.5, 0.0), children=[
            sw_part("Bucket", "bucket.png", (56, 40), 0, 176, 7, children=[
                sw_part("Stone", "stone.png", (34, 34), 0, 8, 8)])]),
