def write_snowfield_script():
    src = r'''-- 103 Snowfield: everything that crosses the snow presses its prints into
-- it. The paths, the trotting and the turning are the engine's
-- (`path_follow`); this script only watches how far each thing has come and,
-- every stride, presses a print where its feet are - Sprite.press dents the
-- snow's normal map, so the moon and the lantern catch the rim - and paints
-- a faint blue shadow into it with Sprite.paint.

script = { tick_rate = 60 }

local nav = require("nav")
local SCENE = "scenes/103-snowfield.scene"
local atan2 = math.atan2 or function(y, x) return math.atan(y, x) end

local SHADE = { 0.72, 0.8, 0.94 }   -- a print's shadow, multiplied in

local e = {}
local walkers = {}
local prints = 0
local captions = true
local lantern_on = true

-- What leaves prints: `feet` are { ahead, aside } offsets from the entity in
-- its own frame, taken in turn every `stride` units; a `run` is pressed
-- every step at every foot at once (a sled's runners).
local KINDS = {
    wolf = { stride = 15, size = 8, depth = 1.6, shape = "disc",
             feet = { { 14, 5 }, { -12, -5 }, { 14, -5 }, { -12, 5 } } },
    walker = { stride = 21, size = 14, depth = 1.5, shape = "streak", feet = { { 0, 6 }, { 0, -6 } } },
    sled = { stride = 6, size = 12, depth = 1.0, shape = "streak", run = true, feet = { { -10, 15 }, { -10, -15 } } },
    dog = { stride = 13, size = 6, depth = 1.3, shape = "disc",
            feet = { { 76, 11 }, { 114, -11 }, { 76, -11 }, { 114, 11 } } },
}

local function track(name, kind)
    local id = Entity.find_by_name(name)
    local x, y = Transform.get_position(id)
    walkers[#walkers + 1] = { e = id, kind = KINDS[kind], x = x, y = y, gone = 0, foot = 1, heading = 0 }
end

local function press_at(w, foot, x, y)
    local k = w.kind
    local c, s = math.cos(w.heading), math.sin(w.heading)
    local px = x + c * foot[1] - s * foot[2]
    local py = y + s * foot[1] + c * foot[2]
    Sprite.press(e.Snow, px, py, k.size, k.depth, k.shape, w.heading)
    Sprite.paint(e.Snow, px, py, k.size * 1.3, SHADE[1], SHADE[2], SHADE[3], 0.5, k.shape, w.heading)
    prints = prints + 1
end

local function step(w)
    local x, y = Transform.get_position(w.e)
    local dx, dy = x - w.x, y - w.y
    local d = math.sqrt(dx * dx + dy * dy)
    w.x, w.y = x, y
    if d < 0.01 or d > 200 then return end
    w.heading = atan2(dy, dx)
    w.gone = w.gone + d
    while w.gone >= w.kind.stride do
        w.gone = w.gone - w.kind.stride
        if w.kind.run then
            for _, foot in ipairs(w.kind.feet) do press_at(w, foot, x, y) end
        else
            press_at(w, w.kind.feet[w.foot], x, y)
            w.foot = w.foot % #w.kind.feet + 1
        end
    end
end

function init(entity)
    for _, n in ipairs({ "Snow", "Lantern", "Status" }) do e[n] = Entity.find_by_name(n) end
    for i = 0, 2 do track("Wolf" .. i, "wolf") end
    track("Sled", "sled")
    track("Sled", "dog")
    track("Walker", "walker")
end

function update(entity, dt)
    nav.tick(SCENE)
    if Input.is_key_just_pressed("Tab") then captions = nav.toggle_ui_captions(captions) end
    if Input.is_key_just_pressed("L") then
        lantern_on = not lantern_on
        Lighting.set_intensity(e.Lantern, lantern_on and 1.3 or 0)
        Sprite.set_color(e.Lantern, 4.0, 3.0, 1.6, lantern_on and 1 or 0)
    end
    for _, w in ipairs(walkers) do step(w) end
    UI.set_text(e.Status, string.format("prints pressed: %d", math.floor(prints)))
end
'''
    (ASSETS / "scripts" / "s103_snowfield.lua").write_text(src, encoding="utf-8", newline="\n")


# ── 104 Wildfire ────────────────────────────────────────────────────────
# Lightning starts a fire in a dry meadow at dusk; the wind drives it east,
# a firebreak turns it, the river stops it, and a water bomber makes passes
# over the front. The fire is a grid in the script - fuel from noise, none on
# the firebreaks or the river - and everything it does is painted: each cell
# alight is painted into three transparent canvases (`paintable` with
# `alpha_cutoff` 0), and the canvases are where the particles start
# (`emit_shape: sprite`, which reads the painted copy as it changes) - the
# glowing front and its flames, embers that light the grass, the smoke. A
# cell burnt out is rubbed out of them (`Sprite.paint` with `erase`) and
# painted into the meadow as char, then ash.

WF_TREES = [(-560, 380), (-470, 430), (-640, -330), (-120, 300), (-60, 380), (-30, -360), (60, -280),
            (-400, -20), (120, 60), (700, 300), (760, -200), (820, 120), (-820, -60), (-140, -120)]
WF_CANVAS = "sprites/wildfire/canvas.png"
# The meadow's geometry, as gen_textures.py paints it: the fire reads the
# same firebreaks and river.
WF_RIVER_W = 70.0
WF_BREAKS = [(-262, -560, -232, 300), (-960, -152, -500, -124)]


def wf_canvas(name, z, color, emitter_fields, extra=None):
    comps = {
        "transform": tr(0, 0),
        "sprite": sprite(WF_CANVAS, (1920, 1080), color, z=z),
        "paintable": {"blend": "over", "alpha_cutoff": 0.0},
        "particle_emitter": emitter(emit_shape={"kind": "sprite", "edge": False, "cutoff": 0.5}, **emitter_fields),
    }
    comps.update(extra or {})
    return {"name": name, "components": comps}


def wildfire():
    C = "sprites/wildfire/"
    F = "sprites/fx/"
    cam = camera()
    cam["components"]["camera"]["zoom"] = 0.7
    ents = [cam]
    ents.append(ent("Ambient", transform=tr(), ambient_light={"color": lin(0.6, 0.5, 0.7)[:3], "intensity": 0.55}))
    ents.append(ent("Dusk", transform=tr(0, 0, rot=0.25), directional_light={
        "color": lin(1.0, 0.62, 0.42)[:3], "intensity": 0.8, "height": 0.3, "softness": 8.0, "casts_shadows": False}))
    floor = bumpy("Meadow", C + "meadow.png", (1920, 1080), (0, 0), -60)
    floor[0]["components"]["paintable"] = {"blend": "over"}
    floor[0]["components"]["material"].update({"specular": 0.7, "shininess": 30.0})
    ents += floor
    for i, (x, y) in enumerate(WF_TREES):
        k = 0.85 + 0.35 * ((i * 37) % 10) / 10
        t = bumpy(f"Oak{i}", C + "oak.png", (150 * k, 150 * k), (x, y), 15, rot=(i * 1.7) % 6.28)[0]
        t["components"]["light_occluder"] = sf_occluder(60 * k, 2.0)
        ents.append(t)
        ents.append(sf_drop(f"Oak{i}", C + "oak.png", (150 * k, 150 * k), (x, y), (i * 1.7) % 6.28, 30 * k))
    hot = lambda c, k: emissive(lin(*c), k)
    # The fire, painted into three canvases.
    ents.append(wf_canvas("Heat", -40, emissive(lin(1.0, 0.45, 0.14), 3.0), dict(
        texture_id=F + "flame.png", emission_rate=320.0, max_particles=900, blend_mode="Additive",
        lifetime=[0.35, 0.8], speed=[25.0, 70.0], angle=[-0.35, 0.35], size_start=[16.0, 30.0], size_end=[5.0, 9.0],
        color_curve=[[0.0] + hot((1.0, 0.85, 0.5, 0.0), 4.0), [0.15] + hot((1.0, 0.7, 0.3, 1.0), 4.0),
                     [0.6] + hot((1.0, 0.35, 0.08, 0.7), 2.5), [1.0, 0.3, 0.05, 0.02, 0.0]],
        turbulence={"strength": 60.0, "scale": 80.0, "speed": 1.4}, z_order=30),
        {"material": additive(), "unlit": {}}))
    ents.append(wf_canvas("Embers", -39, [1, 1, 1, 0.0], dict(
        texture_id=F + "ember.png", emission_rate=70.0, max_particles=240, blend_mode="Additive",
        lifetime=[1.2, 2.6], speed=[50.0, 140.0], angle=[-0.5, 0.5], size_start=[4.0, 7.0], size_end=[1.0, 2.0],
        color_start=hot((1.0, 0.6, 0.2, 1.0), 5.0), color_end=hot((1.0, 0.3, 0.05, 0.0), 2.0),
        turbulence={"strength": 80.0, "scale": 120.0, "speed": 0.9}, drag=0.5, z_order=32,
        light={"every": 3, "max": 36, "radius": 80.0, "intensity": 1.5}), {"unlit": {}}))
    ents.append(wf_canvas("Smoke", -38, [1, 1, 1, 0.0], dict(
        texture_id=F + "smoke.png", emission_rate=36.0, max_particles=260, blend_mode="Alpha",
        lifetime=[4.5, 7.5], speed=[40.0, 95.0], angle=[-0.3, 0.3], size_start=[50.0, 80.0], size_end=[220.0, 320.0],
        color_curve=[[0.0, 0.55, 0.28, 0.12, 0.0], [0.08, 0.42, 0.24, 0.14, 0.42], [0.45, 0.24, 0.22, 0.22, 0.34],
                     [1.0, 0.2, 0.2, 0.21, 0.0]],
        turbulence={"strength": 35.0, "scale": 280.0, "speed": 0.35}, drag=0.25, z_order=40), {"unlit": {}}))
    # Lights the script hangs over the front, and the lightning's.
    for i in range(8):
        ents.append(ent(f"FireLight{i}", transform=tr(0, -2000),
                        point_light=point_light(lin(1.0, 0.55, 0.22), 0.0, 280, falloff=1.3, softness=6.0, height=0.2)))
    ents.append(ent("Strike", transform=tr(0, -2000),
                    point_light=point_light(lin(0.75, 0.8, 1.0), 0.0, 900, falloff=1.0, softness=4.0, height=0.4)))
    # The water bomber, its shadow, its drop, and the steam where it lands.
    ents.append(ent("Bomber", transform=tr(-1400, 0), sprite=sprite(C + "bomber.png", (160, 130), (1, 1, 1, 1), z=55)))
    ents.append({"name": "BomberShadow", "parent": "Bomber", "components": {
        "transform": tr(-40, -55), "material": {"material_id": "default_sprite", "blend_mode": "Multiply", "uniforms": {}},
        "sprite": sprite(C + "bomber.png", (160, 130), lin(0.45, 0.42, 0.5), z=20)}})
    ents.append({"name": "Drop", "parent": "Bomber", "components": {
        "transform": tr(-10, 0), "unlit": {}, "particle_emitter": emitter(
            texture_id=F + "soft_dot.png", emission_rate=260.0, max_particles=500, active=False, blend_mode="Alpha",
            lifetime=[0.6, 1.1], speed=[40.0, 160.0], angle=[0.0, 6.28318], size_start=[10.0, 18.0],
            size_end=[40.0, 70.0], color_start=lin(0.75, 0.85, 0.95, 0.55), color_end=lin(0.8, 0.88, 0.95, 0.0),
            drag=2.0, z_order=50)}})
    ents.append(ent("Steam", transform=tr(0, -2000), unlit={}, particle_emitter=emitter(
        texture_id=F + "smoke.png", emission_rate=0.0, burst_count=8, max_particles=200, active=False,
        blend_mode="Alpha", lifetime=[1.5, 3.0], speed=[20.0, 60.0], size_start=[40.0, 60.0], size_end=[120.0, 180.0],
        color_curve=[[0.0, 0.8, 0.82, 0.86, 0.0], [0.15, 0.8, 0.82, 0.86, 0.45], [1.0, 0.7, 0.72, 0.76, 0.0]],
        turbulence={"strength": 25.0, "scale": 200.0, "speed": 0.4}, z_order=45)))
    ents.append(ent("Driver", transform=tr(), script=script("scripts/s104_wildfire.lua")))
    ents += ui_captions("104   Wildfire", "the fire is painted into canvases its flames start from   W turn the wind   Tab captions")
    pp = post(
        bloom={"threshold": 1.0, "intensity": 0.6, "blur_size": 0.0},
        vignette={"intensity": 0.5, "smoothness": 0.5, "color": [0.04, 0.01, 0.0, 1.0]},
        grade={"brightness": 1.0, "contrast": 1.08, "saturation": 1.05, "tint": [1.0, 0.9, 0.82, 0.05]},
        chromatic={"strength": 0.0012, "on": False},
        hdr={"tonemap": "aces", "exposure": 1.15})
    pp["effects"].append({"name": "film_grain", "enabled": True, "params": {"intensity": {"Float": 0.04}, "size": {"Float": 1.4}}})
    return {"name": "104 - Wildfire", "post_process": pp, "entities": ents}


def write_wildfire_script():
    trees = "{ " + ", ".join(f"{{ {x}, {y} }}" for x, y in WF_TREES) + " }"
    breaks = "{ " + ", ".join("{ " + ", ".join(str(v) for v in b) + " }" for b in WF_BREAKS) + " }"
    src = r'''-- 104 Wildfire: a fire on a grid of cells over the meadow. Each cell has
-- fuel (noise; none on the firebreaks or the river); a burning cell lights
-- its neighbours, downwind more readily, then smoulders, then is ash. The
-- script decides who burns - and paints it: each burning cell into three
-- transparent canvases (the glowing front, embers, smoke) that the flames,
-- embers and smoke are emitted from (`emit_shape: sprite`), rubbed out of
-- them as it dies (`Sprite.paint` with "erase"), and into the meadow as char
-- and then ash.

script = { tick_rate = 60 }

local nav = require("nav")
local SCENE = "scenes/104-wildfire.scene"

local CELL, GW, GH = 20, 96, 54
local X0, Y0 = -960, -540
local TREES = %(trees)s
local BREAKS = %(breaks)s
local RIVER_HALF = %(river_half)f
local START = { -700, 260 }

local UNBURNT, BURNING, SMOULDER, ASH = 0, 1, 2, 3

local e = {}
local fuel, state, timer, tree_of, wet = {}, {}, {}, {}, {}
local active = {}          -- cells burning or smouldering
local tree_state = {}
local burning, burnt = 0, 0
local t, tick = 0, 0
local wind_a, wind_k = 0.15, 1.6
local lit = false
local quiet = 0
local captions = true
local rng = 104
local bomber = { x = -1400, y = 0, wait = 10, flying = false, dropping = false }
local strike = 0

local function rand()
    rng = (rng * 16807) %% 2147483647
    return rng / 2147483647
end

local function river_x(y)
    return 360 + 140 * math.sin(y * 0.0042 + 0.6) + 35 * math.sin(y * 0.013)
end

local function centre(i, j) return X0 + (i - 0.5) * CELL, Y0 + (j - 0.5) * CELL end
local function index(i, j) return (j - 1) * GW + i end

local function on_break(x, y)
    for _, b in ipairs(BREAKS) do
        if x > b[1] - 10 and x < b[3] + 10 and y > b[2] - 10 and y < b[4] + 10 then return true end
    end
    return false
end

local function paint_all(x, y, size, r, g, b, a, blend)
    Sprite.paint(e.Heat, x, y, size, r, g, b, a, "disc", 0, blend)
    Sprite.paint(e.Embers, x, y, size * 0.9, 1, 1, 1, a, "disc", 0, blend)
    Sprite.paint(e.Smoke, x, y, size * 1.1, 1, 1, 1, a, "disc", 0, blend)
end

local function ignite(k, i, j)
    if state[k] ~= UNBURNT or fuel[k] <= 0.05 then return end
    state[k] = BURNING
    timer[k] = 1.2 + 2.4 * fuel[k] + rand() * 0.8
    active[#active + 1] = k
    burning = burning + 1
    local x, y = centre(i, j)
    Sprite.paint(e.Heat, x, y, 30, 1.0, 0.62, 0.25, 0.95, "disc", 0, "over")
    Sprite.paint(e.Embers, x, y, 28, 1, 1, 1, 1, "disc", 0, "over")
    Sprite.paint(e.Smoke, x, y, 34, 1, 1, 1, 1, "disc", 0, "over")
    local tr = tree_of[k]
    if tr and tree_state[tr] == 0 then
        tree_state[tr] = 1
        local p = TREES[tr]
        Sprite.paint(e.Heat, p[1], p[2], 110, 1.0, 0.7, 0.3, 1.0, "disc", 0, "over")
        Sprite.paint(e.Embers, p[1], p[2], 90, 1, 1, 1, 1, "disc", 0, "over")
        Sprite.set_color(e["Oak" .. (tr - 1)], 0.35, 0.22, 0.12, 1)
    end
end

local function douse(cx, cy, radius)
    local i0 = math.max(1, math.floor((cx - radius - X0) / CELL) + 1)
    local i1 = math.min(GW, math.floor((cx + radius - X0) / CELL) + 1)
    local j0 = math.max(1, math.floor((cy - radius - Y0) / CELL) + 1)
    local j1 = math.min(GH, math.floor((cy + radius - Y0) / CELL) + 1)
    local hissed = false
    for j = j0, j1 do
        for i = i0, i1 do
            local x, y = centre(i, j)
            if (x - cx) ^ 2 + (y - cy) ^ 2 < radius * radius then
                local k = index(i, j)
                if state[k] == BURNING or state[k] == SMOULDER then
                    if state[k] == BURNING then burning = burning - 1 end
                    state[k] = ASH
                    burnt = burnt + 1
                    paint_all(x, y, 46, 0, 0, 0, 1, "erase")
                    hissed = true
                elseif state[k] == UNBURNT then
                    state[k] = ASH
                end
                fuel[k] = 0
                -- Wet ground, darkened in - once a cell, or a drop held over
                -- it a second darkens it to black.
                if not wet[k] then
                    wet[k] = true
                    Sprite.paint(e.Meadow, x, y, 30, 0.6, 0.66, 0.76, 0.5, "disc", 0, "multiply")
                end
            end
        end
    end
    if hissed then
        Transform.set_position(e.Steam, cx, cy)
        Particles.emit_burst(e.Steam, 6)
    end
end

local function step_fire(dt)
    local wx, wy = math.cos(wind_a), math.sin(wind_a)
    -- The cells alight when the tick began; those ignited during it are
    -- kept for the next one.
    local n = #active
    local keep = {}
    for i = 1, n do
        local k = active[i]
        local ci = (k - 1) %% GW + 1
        local cj = math.floor((k - 1) / GW) + 1
        timer[k] = timer[k] - dt
        local x, y = centre(ci, cj)
        if state[k] == BURNING then
            for dj = -1, 1 do
                for di = -1, 1 do
                    local ni, nj = ci + di, cj + dj
                    if (di ~= 0 or dj ~= 0) and ni >= 1 and ni <= GW and nj >= 1 and nj <= GH then
                        local nk = index(ni, nj)
                        if state[nk] == UNBURNT and fuel[nk] > 0.05 then
                            local len = math.sqrt(di * di + dj * dj)
                            local push = 1 + wind_k * (di * wx + dj * wy) / len
                            local p = 0.55 * fuel[nk] * math.max(0.05, push) ^ 2 * dt / len
                            if rand() < p then ignite(nk, ni, nj) end
                        end
                    end
                end
            end
            if timer[k] <= 0 then
                state[k] = SMOULDER
                timer[k] = 3 + rand() * 3
                burning = burning - 1
                Sprite.paint(e.Heat, x, y, 26, 0, 0, 0, 0.65, "disc", 0, "erase")
                Sprite.paint(e.Meadow, x, y, 30, 0.05, 0.04, 0.035, 0.85, "disc", 0, "over")
            end
            keep[#keep + 1] = k
        elseif state[k] ~= SMOULDER then
            -- Doused while alight: already ash, already rubbed out.
        elseif timer[k] <= 0 then
            state[k] = ASH
            burnt = burnt + 1
            paint_all(x, y, 46, 0, 0, 0, 1, "erase")
            Sprite.paint(e.Meadow, x + rand() * 8 - 4, y + rand() * 8 - 4, 36, 0.24, 0.23, 0.22, 0.28, "disc", 0, "over")
            local tr = tree_of[k]
            if tr and tree_state[tr] == 1 then
                tree_state[tr] = 2
                Sprite.set_color(e["Oak" .. (tr - 1)], 0.1, 0.08, 0.07, 1)
            end
        else
            keep[#keep + 1] = k
        end
    end
    for i = n + 1, #active do keep[#keep + 1] = active[i] end
    active = keep
end

local function set_wind(a)
    wind_a = a
    for _, name in ipairs({ "Heat", "Embers", "Smoke" }) do
        local spread = name == "Smoke" and 0.3 or 0.45
        Particles.set(e[name], "angle", { a - spread, a + spread })
    end
end

local function lights(dt)
    -- Hang the fire lights over burning cells, a few at a time.
    for n = 0, 7 do
        local light = e["FireLight" .. n]
        if burning > 0 and #active > 0 then
            if rand() < dt * 3 then
                for _ = 1, 6 do
                    local k = active[1 + math.floor(rand() * #active)]
                    if state[k] == BURNING then
                        local x, y = centre((k - 1) %% GW + 1, math.floor((k - 1) / GW) + 1)
                        Transform.set_position(light, x, y)
                        break
                    end
                end
            end
            Lighting.set_intensity(light, 1.4 + 0.5 * math.sin(t * 17 + n * 2.3) + 0.3 * rand())
        else
            Lighting.set_intensity(light, 0)
        end
    end
end

local function fly(dt)
    local b = bomber
    if not b.flying then
        b.wait = b.wait - dt
        if b.wait <= 0 and burning > 8 then
            -- A pass along the middle of the front.
            local sy, n = 0, 0
            for _, k in ipairs(active) do
                if state[k] == BURNING then
                    sy = sy + (Y0 + (math.floor((k - 1) / GW) + 0.5) * CELL)
                    n = n + 1
                end
            end
            b.y = n > 0 and sy / n or 0
            b.x = -1250
            b.flying = true
        end
        return
    end
    b.x = b.x + 330 * dt
    Transform.set_position(e.Bomber, b.x, b.y + math.sin(t * 1.3) * 6)
    Transform.set_rotation(e.Bomber, math.sin(t * 1.3) * 0.03)
    -- Drop over fire.
    local i = math.floor((b.x - X0) / CELL) + 1
    local j = math.floor((b.y - Y0) / CELL) + 1
    local over = false
    for dj = -3, 3 do
        for di = -2, 2 do
            local ni, nj = i + di, j + dj
            if ni >= 1 and ni <= GW and nj >= 1 and nj <= GH and state[index(ni, nj)] == BURNING then over = true end
        end
    end
    if over ~= b.dropping then
        b.dropping = over
        Particles.set_active(e.Drop, over)
    end
    if over then douse(b.x - 20, b.y, 70) end
    if b.x > 1250 then
        b.flying, b.dropping = false, false
        Particles.set_active(e.Drop, false)
        b.wait = 7
    end
end

function init(entity)
    for _, n in ipairs({ "Meadow", "Heat", "Embers", "Smoke", "Strike", "Bomber", "Drop", "Steam", "Status" }) do
        e[n] = Entity.find_by_name(n)
    end
    for n = 0, 7 do e["FireLight" .. n] = Entity.find_by_name("FireLight" .. n) end
    for n = 1, #TREES do
        e["Oak" .. (n - 1)] = Entity.find_by_name("Oak" .. (n - 1))
        tree_state[n] = 0
    end
    for j = 1, GH do
        for i = 1, GW do
            local x, y = centre(i, j)
            local k = index(i, j)
            local f = 0.55 + 1.1 * Noise.perlin(x / 300, y / 300, 104)
            if on_break(x, y) or math.abs(x - river_x(y)) < RIVER_HALF + 12 then f = 0 end
            fuel[k] = math.max(0, math.min(1, f))
            state[k] = UNBURNT
            timer[k] = 0
        end
    end
    for n, p in ipairs(TREES) do
        for j = 1, GH do
            for i = 1, GW do
                local x, y = centre(i, j)
                if (x - p[1]) ^ 2 + (y - p[2]) ^ 2 < 50 * 50 then
                    local k = index(i, j)
                    tree_of[k] = n
                    fuel[k] = 1
                end
            end
        end
    end
    set_wind(wind_a)
end

function update(entity, dt)
    nav.tick(SCENE)
    t = t + dt
    if Input.is_key_just_pressed("Tab") then captions = nav.toggle_ui_captions(captions) end
    if Input.is_key_just_pressed("W") then set_wind(wind_a + math.pi / 4) end
    -- The lightning that starts it.
    if not lit and t > 1.2 then
        lit = true
        strike = 0.5
        Transform.set_position(e.Strike, START[1], START[2])
        Camera.flash(0.12, 0.85, 0.9, 1.0, 0.7)
        Camera.shake(6, 0.3, 30)
        Sprite.paint(e.Meadow, START[1], START[2], 70, 0.04, 0.035, 0.03, 0.9, "splat", 0.4, "over")
        local i = math.floor((START[1] - X0) / CELL) + 1
        local j = math.floor((START[2] - Y0) / CELL) + 1
        for dj = -1, 1 do
            for di = -1, 1 do ignite(index(i + di, j + dj), i + di, j + dj) end
        end
    end
    if strike > 0 then
        strike = math.max(0, strike - dt)
        Lighting.set_intensity(e.Strike, (strike / 0.5) ^ 2 * 6.0 * (0.6 + 0.4 * rand()))
    end
    -- The wind wanders a little round where it was set.
    tick = tick + dt
    if tick >= 0.1 then
        step_fire(tick)
        tick = 0
    end
    lights(dt)
    fly(dt)
    -- Once it is out, it starts again.
    if lit and #active == 0 then
        quiet = quiet + dt
        if quiet > 5 then Scene.load(SCENE) end
    else
        quiet = 0
    end
    local arrows = { "E", "NE", "N", "NW", "W", "SW", "S", "SE" }
    local w = arrows[(math.floor((wind_a %% (2 * math.pi)) / (math.pi / 4) + 0.5) %% 8) + 1]
    UI.set_text(e.Status, string.format("burning %%d   burnt %%d   wind %%s", math.floor(burning), math.floor(burnt), w))
end
''' % {"trees": trees, "breaks": breaks, "river_half": WF_RIVER_W / 2}
    (ASSETS / "scripts" / "s104_wildfire.lua").write_text(src, encoding="utf-8", newline="\n")


# ── 105 Graffiti Alley ──────────────────────────────────────────────────
# A brick wall in an alley at night, straight on: a street lamp, a neon
# sign, rain, steam from a grate, and now and then a car's headlights
# sweeping the wall. Two taggers walk in and spray bubble letters along the
# lower wall - outline, fill, highlights, then the drips run - and every
# stroke is two stamps: a speckled `spray` of colour into the wall, and a
# `gloss` that wets its normal map's alpha, so fresh paint shines under the
# lamp and the passing lights and dries matt over half a minute
# (`dry_seconds`). When the wall is full a buffer rolls grey over it.

GA_SLOTS = [(-660, -250), (-220, -250), (220, -250), (660, -250)]
GA_OLD = [("NEON", -380, 300, 190, (0.85, 0.35, 0.6), (0.18, 0.06, 0.2)),
          ("ZAP", 420, 330, 170, (0.4, 0.75, 0.3), (0.06, 0.12, 0.06)),
          ("OK", 820, 90, 150, (0.9, 0.6, 0.2), (0.15, 0.08, 0.04)),
          ("GIN", -760, 60, 140, (0.3, 0.6, 0.85), (0.04, 0.08, 0.16))]
GA_FEET = -440.0
GA_SCALE = 1.6


def graffiti_alley():
    C = "sprites/alley/"
    F = "sprites/fx/"
    cam = camera()
    cam["components"]["camera"]["zoom"] = 0.7
    ents = [cam]
    ents.append(ent("Ambient", transform=tr(), ambient_light={"color": lin(0.4, 0.45, 0.7)[:3], "intensity": 0.24}))
    wall = bumpy("Wall", C + "wall.png", (1920, 960), (0, 60), -60)
    wall[0]["components"]["paintable"] = {"blend": "over", "dry_seconds": 28.0}
    wall[0]["components"]["material"].update({"specular": 1.0, "shininess": 55.0})
    ents += wall
    ground = bumpy("Ground", C + "ground.png", (1920, 240), (0, -490), -40)
    ground[0]["components"]["material"].update({"specular": 1.0, "shininess": 80.0})
    ents += ground
    # The street lamp on the wall, the neon sign, the headlights.
    ents.append(ent("LampHead", transform=tr(-100, 470), unlit={},
                    sprite=sprite(C + "lamp.png", (130, 58), emissive(lin(1.0, 0.9, 0.75), 1.6), z=20)))
    ents.append(ent("Lamp", transform=tr(-100, 430),
                    point_light=point_light(lin(1.0, 0.78, 0.5), 1.6, 1000, falloff=1.2, softness=0.0, height=0.45)))
    # A cold strip light over a side door out of sight, low on the right.
    ents.append(ent("Strip", transform=tr(520, 10),
                    point_light=point_light(lin(0.7, 0.85, 1.0), 1.1, 700, falloff=1.3, softness=0.0, height=0.35)))
    neon = emissive(lin(1.0, 0.25, 0.6), 5.0)
    ents.append(ent("Neon", transform=tr(700, 370), unlit={}, text={
        "text": "BAR", "font_id": "", "font_scale": 6.0, "color": neon, "z_order": 20, "align": "center",
        "wrap_width": 0.0, "outline": {"width": 2.0, "color": emissive(lin(1.0, 0.2, 0.5, 0.6), 2.0)}}))
    ents.append(ent("NeonLight", transform=tr(700, 360),
                    point_light=point_light(lin(1.0, 0.25, 0.6), 1.3, 520, falloff=1.3, softness=0.0, height=0.3)))
    ents.append(ent("Headlights", transform=tr(1600, -380),
                    point_light=point_light(lin(1.0, 0.95, 0.85), 0.0, 650, falloff=1.1, softness=0.0, height=0.22)))
    # Rain, lit by whatever it falls past, and steam from a grate.
    ents.append(ent("Rain", transform=tr(0, 620), particle_emitter=emitter(
        texture_id=F + "soft_dot.png", emission_rate=260.0, max_particles=700, blend_mode="Alpha",
        lifetime=[1.0, 1.4], speed=[1000.0, 1250.0], angle=[-1.68, -1.6], size_start=[2.5, 3.5], size_end=[2.5, 3.5],
        emit_shape={"kind": "line", "length": 2200.0}, stretch=0.022,
        color_start=lin(0.75, 0.8, 0.9, 0.5), color_end=lin(0.75, 0.8, 0.9, 0.35), z_order=45)))
    ents.append(ent("Steam", transform=tr(320, -470), unlit={}, particle_emitter=emitter(
        texture_id=F + "smoke.png", emission_rate=5.0, max_particles=40, blend_mode="Alpha",
        lifetime=[3.0, 4.5], speed=[30.0, 60.0], angle=[1.35, 1.8], size_start=[40.0, 60.0], size_end=[160.0, 240.0],
        color_curve=[[0.0, 0.5, 0.52, 0.6, 0.0], [0.15, 0.5, 0.52, 0.6, 0.1], [1.0, 0.45, 0.47, 0.55, 0.0]],
        turbulence={"strength": 20.0, "scale": 200.0, "speed": 0.4}, z_order=44)))
    # The two taggers and the buffer: a body, an arm, a can, and the mist.
    for name, tint in (("TaggerA", (1, 1, 1, 1)), ("TaggerB", lin(0.75, 0.65, 0.9)), ("Buffer", lin(1.0, 0.55, 0.2))):
        ents.append(ent(name, transform=tr(-1400, GA_FEET),
                        sprite=sprite(C + "tagger.png", (80 * GA_SCALE, 170 * GA_SCALE), tint, z=30, anchor=(0.5, 0.0))))
        ents.append(ent(f"{name}Arm", transform=tr(-1400, GA_FEET),
                        sprite=sprite(C + "arm.png", (70 * GA_SCALE, 16 * GA_SCALE), tint, z=31, anchor=(0.0, 0.5))))
        ents.append({"name": f"{name}Can", "parent": f"{name}Arm", "components": {
            "transform": tr(70 * GA_SCALE - 6, 10),
            "sprite": sprite(C + "can.png", (16 * GA_SCALE, 34 * GA_SCALE), (1, 1, 1, 1), z=32)}})
        ents.append(ent(f"{name}Mist", transform=tr(-1400, GA_FEET), unlit={}, particle_emitter=emitter(
            texture_id=F + "soft_dot.png", emission_rate=90.0, max_particles=160, active=False, blend_mode="Alpha",
            lifetime=[0.4, 0.9], speed=[10.0, 40.0], size_start=[6.0, 10.0], size_end=[26.0, 40.0],
            color_start=[1.0, 1.0, 1.0, 0.3], color_end=[1.0, 1.0, 1.0, 0.0], drag=1.5, z_order=33)))
    ents.append(ent("Driver", transform=tr(), script=script("scripts/s105_graffiti_alley.lua")))
    ents += ui_captions("105   Graffiti Alley", "every stroke is sprayed into the wall - fresh paint shines and dries   Tab captions")
    pp = post(
        bloom={"threshold": 1.0, "intensity": 0.6, "blur_size": 0.0},
        vignette={"intensity": 0.5, "smoothness": 0.5, "color": [0.01, 0.0, 0.03, 1.0]},
        grade={"brightness": 1.0, "contrast": 1.08, "saturation": 1.08, "tint": [0.9, 0.92, 1.0, 0.05]},
        chromatic={"strength": 0.0015, "on": True},
        hdr={"tonemap": "aces", "exposure": 1.05})
    pp["effects"].append({"name": "film_grain", "enabled": True, "params": {"intensity": {"Float": 0.04}, "size": {"Float": 1.3}}})
    return {"name": "105 - Graffiti Alley", "post_process": pp, "entities": ents}


def write_graffiti_alley_script():
    slots = "{ " + ", ".join(f"{{ {x}, {y} }}" for x, y in GA_SLOTS) + " }"
    old = "{ " + ", ".join(
        f'{{ "{w}", {x}, {y}, {h}, {{ {f[0]}, {f[1]}, {f[2]} }}, {{ {o[0]}, {o[1]}, {o[2]} }} }}'
        for w, x, y, h, f, o in GA_OLD) + " }"
    src = r'''-- 105 Graffiti Alley: taggers spray bubble letters into a brick wall.
-- Every stroke is stamped twice: a `spray` of colour (Sprite.paint), and a
-- `gloss` that wets the wall's normal map, so fresh paint shines under the
-- lamp and the passing headlights and dries matt (`dry_seconds` on the
-- paintable). The letters are strokes in a little font below; a piece is an
-- outline pass, a fill pass, highlights and drips.

script = { tick_rate = 60 }

local nav = require("nav")
local SCENE = "scenes/105-graffiti-alley.scene"
local atan2 = math.atan2 or function(y, x) return math.atan(y, x) end

local SLOTS = %(slots)s
local OLD = %(old)s
local FEET = %(feet)f
local SCALE = %(scale)f
local SHOULDER = { -30 * SCALE / 1.6, 198 * SCALE / 1.6 }
local REACH = 108 * SCALE / 1.6
local BUFF = { 0.33, 0.31, 0.3 }

-- Strokes in a unit box, y up.
local CIRCLE = {}
for i = 0, 16 do
    local a = math.pi / 2 + i / 16 * 2 * math.pi
    CIRCLE[#CIRCLE + 1] = { 0.5 + 0.5 * math.cos(a), 0.5 + 0.5 * math.sin(a) }
end
local FONT = {
    Z = { { { 0, 1 }, { 1, 1 }, { 0, 0 }, { 1, 0 } } },
    A = { { { 0, 0 }, { 0.5, 1 }, { 1, 0 } }, { { 0.22, 0.4 }, { 0.78, 0.4 } } },
    P = { { { 0, 0 }, { 0, 1 }, { 0.75, 1 }, { 1, 0.86 }, { 1, 0.64 }, { 0.75, 0.5 }, { 0, 0.5 } } },
    O = { CIRCLE },
    K = { { { 0, 0 }, { 0, 1 } }, { { 1, 1 }, { 0, 0.45 }, { 1, 0 } } },
    E = { { { 1, 1 }, { 0, 1 }, { 0, 0 }, { 1, 0 } }, { { 0, 0.5 }, { 0.75, 0.5 } } },
    N = { { { 0, 0 }, { 0, 1 }, { 1, 0 }, { 1, 1 } } },
    J = { { { 1, 1 }, { 1, 0.25 }, { 0.8, 0 }, { 0.2, 0 }, { 0, 0.25 } } },
    I = { { { 0.5, 0 }, { 0.5, 1 } } },
    G = { { { 1, 0.85 }, { 0.8, 1 }, { 0.2, 1 }, { 0, 0.75 }, { 0, 0.25 }, { 0.2, 0 }, { 0.8, 0 }, { 1, 0.25 },
            { 1, 0.5 }, { 0.55, 0.5 } } },
    W = { { { 0, 1 }, { 0.22, 0 }, { 0.5, 0.6 }, { 0.78, 0 }, { 1, 1 } } },
    R = { { { 0, 0 }, { 0, 1 }, { 0.75, 1 }, { 1, 0.86 }, { 1, 0.64 }, { 0.75, 0.5 }, { 0, 0.5 }, { 1, 0 } } },
    S = { { { 1, 0.85 }, { 0.8, 1 }, { 0.2, 1 }, { 0, 0.8 }, { 0.15, 0.55 }, { 0.85, 0.45 }, { 1, 0.2 }, { 0.8, 0 },
            { 0.2, 0 }, { 0, 0.15 } } },
}
local WORDS = { "ZAP", "OKE", "NEON", "JIG", "WIRE", "SPIN", "GRAZ", "ROK" }
local PALETTES = {
    { { 1.0, 0.25, 0.55 }, { 0.12, 0.02, 0.1 } },
    { { 0.6, 0.95, 0.1 }, { 0.02, 0.05, 0.02 } },
    { { 1.0, 0.55, 0.05 }, { 0.03, 0.04, 0.14 } },
    { { 0.1, 0.85, 0.95 }, { 0.25, 0.02, 0.22 } },
    { { 0.95, 0.9, 0.2 }, { 0.2, 0.05, 0.02 } },
}

local e = {}
local t = 0
local rng = 105
local slot_taken = {}
local pieces = 0
local drips = {}
local backlog = {}
local captions = true
local crew = {}
local headlight_wait = 4
local headlight_x = nil

local function rand()
    rng = (rng * 16807) %% 2147483647
    return rng / 2147483647
end

-- A word's strokes in world points: letters slanted, side by side.
local function word_strokes(word, cx, cy, h)
    local w = h * 0.62
    local adv = w * 1.32
    local total = adv * (#word - 1) + w
    local out = {}
    for n = 1, #word do
        local glyph = FONT[word:sub(n, n)] or FONT.O
        local ox = cx - total / 2 + (n - 1) * adv
        for _, stroke in ipairs(glyph) do
            local pts = {}
            for _, p in ipairs(stroke) do
                local y = cy - h / 2 + p[2] * h
                pts[#pts + 1] = { ox + p[1] * w + (p[2] - 0.5) * h * 0.22, y }
            end
            out[#out + 1] = pts
        end
    end
    return out
end

-- The wall at once (the old pieces): queued, drawn a little each frame,
-- since a sprite keeps a thousand stamps at most between two frames.
local function queue_word(word, cx, cy, h, fill, outline)
    for pass = 1, 2 do
        local size = pass == 1 and h * 0.34 or h * 0.22
        local col = pass == 1 and outline or fill
        for _, stroke in ipairs(word_strokes(word, cx, cy, h)) do
            for i = 1, #stroke - 1 do
                local a, b = stroke[i], stroke[i + 1]
                local len = math.sqrt((b[1] - a[1]) ^ 2 + (b[2] - a[2]) ^ 2)
                local n = math.max(1, math.floor(len / (size * 0.25)))
                for k = 0, n do
                    local f = k / n
                    backlog[#backlog + 1] = { a[1] + (b[1] - a[1]) * f, a[2] + (b[2] - a[2]) * f, size, col }
                end
            end
        end
    end
end

-- A stamp of paint: a solid core, a speckled overspray round it, and - when
-- fresh - the wet shine.
local function spray(x, y, size, col, wet)
    Sprite.paint(e.Wall, x, y, size * 1.35, col[1], col[2], col[3], 0.3, "spray", 0)
    Sprite.paint(e.Wall, x, y, size, col[1], col[2], col[3], 0.95, "disc", 0)
    if wet then Sprite.paint(e.Wall, x, y, size * 1.1, 1, 1, 1, 1.0, "disc", 0, "gloss") end
end

-- ── a crew member's job ─────────────────────────────────────────────────

local function free_slot()
    local free = {}
    for i = 1, #SLOTS do if not slot_taken[i] then free[#free + 1] = i end end
    if #free == 0 then return nil end
    return free[1 + math.floor(rand() * #free)]
end

local function plan_piece(m, slot)
    local s = SLOTS[slot]
    local word = WORDS[1 + math.floor(rand() * #WORDS)]
    local pal = PALETTES[1 + math.floor(rand() * #PALETTES)]
    local h = 140
    local strokes = word_strokes(word, s[1], s[2], h)
    local passes = {
        { strokes = strokes, size = h * 0.34, col = pal[2], speed = 520 },
        { strokes = strokes, size = h * 0.22, col = pal[1], speed = 380 },
    }
    -- Highlights: a thin white line up and to the left of a few strokes.
    local hl = {}
    for i, stroke in ipairs(strokes) do
        if i %% 2 == 1 then
            local pts = {}
            for _, p in ipairs(stroke) do pts[#pts + 1] = { p[1] - h * 0.04, p[2] + h * 0.04 } end
            hl[#hl + 1] = pts
        end
    end
    passes[#passes + 1] = { strokes = hl, size = h * 0.05, col = { 1, 1, 1 }, speed = 300 }
    m.job = { kind = "piece", slot = slot, passes = passes, pass = 1, stroke = 1, seg = 1, along = 0, since = 0,
              fill = pal[1], drips = 3 + math.floor(rand() * 4) }
end

local function plan_buff(m)
    -- Rolled grey over the lower wall, a band at a time.
    local strokes = {}
    for row = 0, 3 do
        local y = -330 + row * 52
        strokes[#strokes + 1] = { { -930, y }, { 930, y } }
    end
    m.job = { kind = "buff", passes = { { strokes = strokes, size = 90, col = BUFF, speed = 700 } },
              pass = 1, stroke = 1, seg = 1, along = 0, since = 0 }
end

local function finish(m)
    local job = m.job
    if job.kind == "piece" then
        pieces = pieces + 1
        -- Drips from points along the fill.
        local fill = job.passes[2].strokes
        for _ = 1, job.drips do
            local stroke = fill[1 + math.floor(rand() * #fill)]
            local p = stroke[1 + math.floor(rand() * #stroke)]
            drips[#drips + 1] = { x = p[1] + rand() * 8 - 4, y = p[2] - 8, left = 30 + rand() * 70,
                                  speed = 22 + rand() * 30, col = job.fill }
        end
    else
        for i = 1, #SLOTS do slot_taken[i] = nil end
    end
    m.job = nil
    m.leaving = true
end

-- Advance a job's nozzle along its strokes; spray as it goes. Returns where
-- the nozzle is.
local function work(m, dt)
    local job = m.job
    local pass = job.passes[job.pass]
    local stroke = pass.strokes[job.stroke]
    local a, b = stroke[job.seg], stroke[job.seg + 1]
    local dx, dy = b[1] - a[1], b[2] - a[2]
    local len = math.max(1e-3, math.sqrt(dx * dx + dy * dy))
    job.along = job.along + pass.speed * dt
    local step = pass.size * 0.3
    while job.since <= job.along do
        local f = math.min(1, job.since / len)
        spray(a[1] + dx * f, a[2] + dy * f, pass.size, pass.col, true)
        job.since = job.since + step
    end
    local f = math.min(1, job.along / len)
    local nx, ny = a[1] + dx * f, a[2] + dy * f
    if job.along >= len then
        job.along, job.since = 0, 0
        job.seg = job.seg + 1
        if job.seg >= #stroke then
            job.seg = 1
            job.stroke = job.stroke + 1
            if job.stroke > #pass.strokes then
                job.stroke = 1
                job.pass = job.pass + 1
                if job.pass > #job.passes then finish(m) end
            end
        end
    end
    return nx, ny, pass.col
end

local function crew_member(name, buffer)
    return { name = name, body = Entity.find_by_name(name), arm = Entity.find_by_name(name .. "Arm"),
             mist = Entity.find_by_name(name .. "Mist"), x = -1300, buffer = buffer, job = nil,
             leaving = false, wait = buffer and 1e9 or 1 + rand() * 3, spraying = false }
end

local function step_crew(m, dt)
    if m.leaving then
        m.x = m.x - 320 * dt
        if m.x < -1300 then
            m.leaving = false
            m.wait = 2 + rand() * 4
        end
    elseif not m.job then
        m.wait = m.wait - dt
        if m.wait <= 0 then
            if m.buffer then
                plan_buff(m)
            else
                local slot = free_slot()
                if slot then
                    slot_taken[slot] = true
                    plan_piece(m, slot)
                else
                    m.wait = 3
                end
            end
        end
    end
    local nx, ny, col
    if m.job then
        -- Walk to where the nozzle is going before spraying.
        local job = m.job
        local stroke = job.passes[job.pass].strokes[job.stroke]
        local target = stroke[job.seg]
        local want = target[1] - SHOULDER[1] - 50
        if math.abs(want - m.x) > 40 and job.along == 0 and job.since == 0 then
            m.x = m.x + math.max(-320 * dt, math.min(320 * dt, want - m.x))
        else
            m.x = m.x + (want - m.x) * math.min(1, dt * 3)
            nx, ny, col = work(m, dt)
        end
    end
    local bob = (m.job or m.leaving) and math.abs(math.sin(t * 8)) * 6 or 0
    Transform.set_position(m.body, m.x, FEET + bob)
    local sx, sy = m.x + SHOULDER[1], FEET + bob + SHOULDER[2]
    Transform.set_position(m.arm, sx, sy)
    local spraying = nx ~= nil
    if spraying then
        local a = atan2(ny - sy, nx - sx)
        local d = math.sqrt((nx - sx) ^ 2 + (ny - sy) ^ 2)
        Transform.set_rotation(m.arm, a)
        Transform.set_scale(m.arm, math.max(0.4, math.min(1.3, d / REACH)), 1)
        Transform.set_position(m.mist, nx, ny)
        if col ~= m.mist_col then
            m.mist_col = col
            Particles.set(m.mist, "color_start", { col[1], col[2], col[3], 0.3 })
            Particles.set(m.mist, "color_end", { col[1], col[2], col[3], 0.0 })
        end
    else
        Transform.set_rotation(m.arm, -1.3)
        Transform.set_scale(m.arm, 0.8, 1)
    end
    if spraying ~= m.spraying then
        m.spraying = spraying
        Particles.set_active(m.mist, spraying)
    end
end

function init(entity)
    for _, n in ipairs({ "Wall", "Headlights", "Neon", "NeonLight", "Status" }) do e[n] = Entity.find_by_name(n) end
    crew = { crew_member("TaggerA", false), crew_member("TaggerB", false), crew_member("Buffer", true) }
    for _, o in ipairs(OLD) do queue_word(o[1], o[2], o[3], o[4], o[5], o[6]) end
end

function update(entity, dt)
    nav.tick(SCENE)
    t = t + dt
    if Input.is_key_just_pressed("Tab") then captions = nav.toggle_ui_captions(captions) end
    -- The old pieces, a few hundred stamps a frame.
    for _ = 1, math.min(#backlog, 400) do
        local b = table.remove(backlog)
        spray(b[1], b[2], b[3], { b[4][1] * 0.75, b[4][2] * 0.75, b[4][3] * 0.75 }, false)
    end
    for _, m in ipairs(crew) do step_crew(m, dt) end
    -- The buffer comes when every slot is taken and the taggers are gone.
    local full = true
    for i = 1, #SLOTS do if not slot_taken[i] then full = false end end
    local buffer = crew[3]
    if full and not buffer.job and not buffer.leaving and buffer.wait > 1e8 then
        local busy = crew[1].job or crew[2].job
        if not busy then buffer.wait = 6 end
    end
    -- Drips run down the wall.
    for i = #drips, 1, -1 do
        local d = drips[i]
        local step = d.speed * dt
        d.y = d.y - step
        d.left = d.left - step
        d.speed = d.speed * (1 - dt * 0.4)
        spray(d.x, d.y, 5, d.col, true)
        if d.left <= 0 then
            Sprite.paint(e.Wall, d.x, d.y - 2, 8, d.col[1], d.col[2], d.col[3], 0.95, "disc", 0)
            table.remove(drips, i)
        end
    end
    -- A car goes by now and then; the neon stutters.
    if headlight_x then
        headlight_x = headlight_x - 900 * dt
        Transform.set_position(e.Headlights, headlight_x, -360)
        Lighting.set_intensity(e.Headlights, 2.4)
        if headlight_x < -1500 then
            headlight_x = nil
            Lighting.set_intensity(e.Headlights, 0)
            headlight_wait = 9 + rand() * 8
        end
    else
        headlight_wait = headlight_wait - dt
        if headlight_wait <= 0 then headlight_x = 1500 end
    end
    local flick = (math.sin(t * 37) > 0.93 and rand() < 0.5) and 0.15 or 1.0
    Lighting.set_intensity(e.NeonLight, 1.3 * flick)
    Text.set_color(e.Neon, 5.0 * flick, 1.25 * flick, 3.0 * flick, 1)
    UI.set_text(e.Status, string.format("pieces %%d   drips running %%d", math.floor(pieces), math.floor(#drips)))
end
''' % {"slots": slots, "old": old, "feet": GA_FEET, "scale": GA_SCALE}
    (ASSETS / "scripts" / "s105_graffiti_alley.lua").write_text(src, encoding="utf-8", newline="\n")


# ── 106 The Foundry ─────────────────────────────────────────────────────
# A foundry side on. A crucible on an overhead crane travels to three sand
# moulds in turn and tips molten metal into each: a `fluid` that pours from
# its lip, splashes, runs into the cavity and levels out, cooling from white
# through orange and red to the dull grey of a casting as it sets - the dots
# merged into one surface by a `canvas_group` with a `threshold`. Sparks fly
# off the stream and bounce, steam and smoke rise off the moulds, the air
# over them shimmers, the hot metal lights the shop, and a furnace roars in
# the back. When the castings are cold they are knocked out and it begins
# again.

FD_MOULD_X = [-150.0, 150.0, 450.0]
FD_CRUCIBLE_Y = 20.0
FD_RAIL_Y = 470.0
FD_LIP = (95.0, 62.0)


def fd_static_box(name, x, y, w, h):
    return ent(name, transform=tr(x, y), collider={
        "shape": {"Box": {"width": float(w), "height": float(h)}}, "offset": [0.0, 0.0], "is_sensor": False,
        "friction": 0.5, "restitution": 0.0, "density": 1.0})


def foundry():
    C = "sprites/foundry/"
    F = "sprites/fx/"
    cam = camera()
    cam["components"]["camera"]["zoom"] = 0.7
    ents = [cam]
    ents.append(ent("Ambient", transform=tr(), ambient_light={"color": lin(0.7, 0.58, 0.52)[:3], "intensity": 0.3}))
    ents += bumpy("Wall", C + "wall.png", (1920, 1080), (0, 0), -60)
    # A work lamp hanging out of sight over the left of the shop.
    ents.append(ent("WorkLamp", transform=tr(-460, 380),
                    point_light=point_light(lin(1.0, 0.82, 0.6), 1.0, 950, falloff=1.2, softness=6.0, height=0.45)))
    # The furnace at the back, its fire behind its mouth.
    ents.append(ent("FurnaceFire", transform=tr(690, -150), unlit={}, material=additive(),
                    sprite=sprite(F + "glow.png", (300, 320), emissive(lin(1.0, 0.45, 0.12), 3.5), z=-52)))
    ents.append(ent("FurnaceFlames", transform=tr(690, -250), unlit={}, particle_emitter=emitter(
        texture_id=F + "flame.png", emission_rate=40.0, max_particles=120, blend_mode="Additive",
        lifetime=[0.5, 1.0], speed=[30.0, 80.0], angle=[1.3, 1.85], size_start=[30.0, 50.0], size_end=[8.0, 12.0],
        emit_shape={"kind": "line", "length": 120.0},
        color_curve=[[0.0] + emissive(lin(1.0, 0.85, 0.5, 0.0), 4.0), [0.2] + emissive(lin(1.0, 0.65, 0.25, 1.0), 4.0),
                     [1.0, 0.4, 0.06, 0.02, 0.0]],
        turbulence={"strength": 50.0, "scale": 70.0, "speed": 1.2}, z_order=-51)))
    ents += bumpy("Furnace", C + "furnace.png", (360, 420), (690, -110), -50)
    ents.append(ent("FurnaceLight", transform=tr(690, -200),
                    point_light=point_light(lin(1.0, 0.5, 0.18), 2.0, 900, falloff=1.3, softness=4.0, height=0.25)))
    ents.append(ent("Chimney", transform=tr(690, 110), unlit={}, particle_emitter=emitter(
        texture_id=F + "ember.png", emission_rate=10.0, max_particles=60, blend_mode="Additive",
        lifetime=[1.5, 3.0], speed=[60.0, 140.0], angle=[1.3, 1.85], size_start=[4.0, 7.0], size_end=[1.0, 2.0],
        color_start=emissive(lin(1.0, 0.6, 0.2, 1.0), 5.0), color_end=emissive(lin(1.0, 0.3, 0.05, 0.0), 2.0),
        turbulence={"strength": 60.0, "scale": 120.0, "speed": 0.8}, z_order=-49)))
    # The casting bed and the shapes the metal meets.
    ents += bumpy("Bed", C + "bed.png", (1920, 240), (0, -420), -30)
    ents.append(fd_static_box("BedFloor", 0, -456, 1920, 168))
    for i, (x, w) in enumerate(((-595, 730), (0, 140), (300, 140), (745, 430))):
        ents.append(fd_static_box(f"BedWall{i}", x, -336, w, 72))
    # The crane: rail, trolley, chains, crucible and its glow.
    ents.append(ent("Rail", transform=tr(0, FD_RAIL_Y), sprite=sprite(C + "rail.png", (1980, 30), (1, 1, 1, 1), z=-10)))
    ents.append(ent("Trolley", transform=tr(-650, FD_RAIL_Y - 10),
                    sprite=sprite(C + "trolley.png", (120, 70), (1, 1, 1, 1), z=-9)))
    for side in ("L", "R"):
        ents.append(ent(f"Chain{side}", transform=tr(), line={
            "points": [[0.0, 0.0], [0.0, -1.0]], "width": 5.0, "color": lin(0.12, 0.11, 0.11),
            "z_order": -8, "begin_cap": "round", "end_cap": "round"}))
    ents += bumpy("Crucible", C + "crucible.png", (220, 200), (-650, FD_CRUCIBLE_Y), 8)
    ents.append({"name": "CrucibleGlow", "parent": "Crucible", "components": {
        "transform": tr(0, 0), "unlit": {}, "material": additive(),
        "sprite": sprite(C + "crucible_glow.png", (220, 200), emissive(lin(1.0, 0.75, 0.35), 4.0), z=9)}})
    ents.append({"name": "CrucibleLight", "parent": "Crucible", "components": {
        "transform": tr(0, 90),
        "point_light": point_light(lin(1.0, 0.6, 0.25), 1.6, 420, falloff=1.4, softness=4.0, height=0.3)}})
    # The melt: a fluid in a thresholded canvas group, so its dots are one
    # surface. The script keeps it at the crucible's lip.
    ents.append(ent("MeltGroup", transform=tr(0, 0), canvas_group={"opacity": 1.0, "z_order": 6, "threshold": 0.42,
                                                                   "threshold_soft": 0.05}))
    hot = lambda c, k: emissive(lin(*c), k)
    ents.append({"name": "Melt", "parent": "MeltGroup", "components": {
        "transform": tr(-650, -60), "unlit": {},
        "fluid": {
            "radius": 16.0, "rest_density": 3.0, "stiffness": 0.06, "near_stiffness": 0.14, "viscosity": 5.0,
            "gravity": [0.0, -900.0], "max_particles": 1100, "pour_rate": 0.0, "pour_at": [0.0, 0.0],
            "pour_angle": 0.0, "pour_speed": 70.0, "pour_width": 12.0, "cooling": 0.042, "freeze_below": 0.17,
            "size": 36.0, "texture_id": F + "soft_dot.png", "z_order": 6,
            "gradient": [[0.0] + lin(0.13, 0.12, 0.12), [0.17] + lin(0.2, 0.15, 0.13), [0.3] + hot((1.0, 0.18, 0.04, 1.0), 1.2),
                         [0.55] + hot((1.0, 0.32, 0.06, 1.0), 3.0), [0.8] + hot((1.0, 0.6, 0.2, 1.0), 4.5),
                         [1.0] + hot((1.0, 0.9, 0.65, 1.0), 7.0)],
            "lights": {"max": 10, "radius": 260.0, "intensity": 2.2, "color": lin(1.0, 0.5, 0.15)[:3]}}}})
    # Sparks off the stream where it lands, and off the lip.
    for name in ("SplashSparks", "LipSparks"):
        ents.append(ent(name, transform=tr(0, -2000), unlit={}, particle_emitter=emitter(
            texture_id=F + "spark.png", emission_rate=70.0 if name == "SplashSparks" else 25.0, max_particles=200,
            active=False, blend_mode="Additive", lifetime=[0.4, 1.1], speed=[120.0, 380.0], angle=[0.3, 2.85],
            size_start=[5.0, 8.0], size_end=[1.5, 2.0], gravity_modifier=1.0,
            color_curve=[[0.0] + hot((1.0, 0.9, 0.6, 1.0), 6.0), [1.0] + hot((1.0, 0.35, 0.08, 0.0), 2.0)],
            stretch=0.03, collision={"response": "bounce", "bounce": 0.35}, z_order=30,
            light={"every": 6, "max": 6, "radius": 70.0, "intensity": 1.2})))
    # Steam and smoke off each mould, and the shimmer over it.
    for i, x in enumerate(FD_MOULD_X):
        ents.append(ent(f"Steam{i}", transform=tr(x, -310), unlit={}, particle_emitter=emitter(
            texture_id=F + "smoke.png", emission_rate=10.0, max_particles=80, active=False, blend_mode="Alpha",
            lifetime=[2.5, 4.5], speed=[30.0, 70.0], angle=[1.35, 1.8], size_start=[40.0, 60.0], size_end=[180.0, 260.0],
            emit_shape={"kind": "line", "length": 140.0},
            color_curve=[[0.0, 0.5, 0.42, 0.38, 0.0], [0.15, 0.45, 0.4, 0.38, 0.3], [1.0, 0.25, 0.24, 0.24, 0.0]],
            turbulence={"strength": 30.0, "scale": 220.0, "speed": 0.4}, z_order=35)))
        ents.append(ent(f"Haze{i}", transform=tr(x, -180), material={"material_id": "materials/heat_haze"},
                        sprite=sprite("", (240, 300), (1, 1, 1, 0.0), z=34)))
    ents.append(ent("KnockOut", transform=tr(0, -2000), particle_emitter=emitter(
        texture_id=F + "smoke.png", emission_rate=0.0, burst_count=14, max_particles=60, active=False,
        blend_mode="Alpha", lifetime=[1.0, 2.0], speed=[40.0, 140.0], angle=[0.4, 2.7], size_start=[30.0, 50.0],
        size_end=[100.0, 160.0], color_start=lin(0.35, 0.3, 0.24, 0.6), color_end=lin(0.3, 0.27, 0.22, 0.0),
        emit_shape={"kind": "line", "length": 150.0}, z_order=36)))
    ents.append(ent("Driver", transform=tr(), script=script("scripts/s106_foundry.lua")))
    ents += ui_captions("106   The Foundry", "molten metal is a fluid: it pours, levels and sets   Space pour now   Tab captions")
    pp = post(
        bloom={"threshold": 1.0, "intensity": 0.75, "blur_size": 0.0},
        vignette={"intensity": 0.5, "smoothness": 0.5, "color": [0.03, 0.01, 0.0, 1.0]},
        grade={"brightness": 1.0, "contrast": 1.1, "saturation": 1.05, "tint": [1.0, 0.9, 0.8, 0.05]},
        chromatic={"strength": 0.0012, "on": False},
        hdr={"tonemap": "aces", "exposure": 1.0})
    pp["effects"].append({"name": "film_grain", "enabled": True, "params": {"intensity": {"Float": 0.04}, "size": {"Float": 1.4}}})
    return {"name": "106 - The Foundry", "post_process": pp, "entities": ents}


def write_foundry_script():
    moulds = "{ " + ", ".join(f"{x}" for x in FD_MOULD_X) + " }"
    src = r'''-- 106 The Foundry: the crane's cycle. The metal is the engine's `fluid`:
-- this script moves the crucible over each mould, tips it, and turns the
-- pour on (`Fluid.set(melt, "pour_rate", ...)`) while the lip is down; the
-- liquid does the rest - falls, splashes, levels out, cools and sets.

script = { tick_rate = 60 }

local nav = require("nav")
local SCENE = "scenes/106-foundry.scene"

local MOULDS = %(moulds)s
local CRUCIBLE_Y = %(cy)f
local RAIL_Y = %(rail)f
local LIP = { %(lipx)f, %(lipy)f }
local REST_X = -650
local TILT = -1.12
local POUR_RATE = 110

local e = {}
local t = 0
local x = REST_X
local tilt = 0
local phase = "rest"
local timer = 3
local mould = 1
local poured = 0
local hot = {}
local captions = true

local function lip()
    local c, s = math.cos(tilt), math.sin(tilt)
    return x + c * LIP[1] - s * LIP[2], CRUCIBLE_Y + s * LIP[1] + c * LIP[2]
end

local function pour(on)
    Fluid.set(e.Melt, "pour_rate", on and POUR_RATE or 0)
    Particles.set_active(e.SplashSparks, on)
    Particles.set_active(e.LipSparks, on)
    if on then
        Transform.set_position(e.SplashSparks, MOULDS[mould], -340)
        Particles.set_active(e["Steam" .. (mould - 1)], true)
        hot[mould] = 0
    end
end

local function approach(v, target, rate, dt)
    if v < target then return math.min(target, v + rate * dt) end
    return math.max(target, v - rate * dt)
end

function init(entity)
    for _, n in ipairs({ "Melt", "Crucible", "CrucibleGlow", "Trolley", "ChainL", "ChainR", "SplashSparks",
                         "LipSparks", "KnockOut", "FurnaceLight", "FurnaceFire", "Status" }) do
        e[n] = Entity.find_by_name(n)
    end
    for i = 0, 2 do
        e["Steam" .. i] = Entity.find_by_name("Steam" .. i)
        e["Haze" .. i] = Entity.find_by_name("Haze" .. i)
    end
end

function update(entity, dt)
    nav.tick(SCENE)
    t = t + dt
    if Input.is_key_just_pressed("Tab") then captions = nav.toggle_ui_captions(captions) end
    if Input.is_key_just_pressed("Space") and phase == "rest" then timer = 0 end
    timer = timer - dt
    -- The crane's cycle: travel, tip, pour, tip back - three times - then
    -- back to rest while the castings cool, then knock them out.
    if phase == "rest" then
        x = approach(x, REST_X, 220, dt)
        if timer <= 0 then
            phase, mould = "travel", 1
        end
    elseif phase == "travel" then
        local want = MOULDS[mould] - 122
        x = approach(x, want, 200, dt)
        if math.abs(x - want) < 1 then phase = "tip" end
    elseif phase == "tip" then
        tilt = approach(tilt, TILT, 0.9, dt)
        if tilt <= TILT then
            phase, timer = "pour", 2.0
            pour(true)
        end
    elseif phase == "pour" then
        poured = poured + dt
        if timer <= 0 then
            pour(false)
            phase = "untip"
        end
    elseif phase == "untip" then
        tilt = approach(tilt, 0, 1.0, dt)
        if tilt >= 0 then
            if mould < #MOULDS then
                mould = mould + 1
                phase = "travel"
            else
                phase, timer = "cool", 26
            end
        end
    elseif phase == "cool" then
        x = approach(x, REST_X, 220, dt)
        if timer <= 0 then
            -- Knocked out: the castings go, in a cloud of sand.
            for _, mx in ipairs(MOULDS) do
                Transform.set_position(e.KnockOut, mx, -320)
                Particles.emit_burst(e.KnockOut, 14)
            end
            Camera.shake(4, 0.3, 20)
            Fluid.set(e.Melt, "clear", true)
            poured = 0
            phase, timer = "rest", 4
        end
    end
    -- Place the crane, the crucible and the pour.
    Transform.set_position(e.Trolley, x, RAIL_Y - 10)
    Transform.set_position(e.Crucible, x, CRUCIBLE_Y)
    Transform.set_rotation(e.Crucible, tilt)
    local lx, ly = lip()
    Transform.set_position(e.Melt, lx + 4, ly - 2)
    Transform.set_rotation(e.Melt, tilt)
    Transform.set_position(e.LipSparks, lx, ly)
    Line.set(e.ChainL, "points", { { x - 30, RAIL_Y - 40 }, { x - 6, CRUCIBLE_Y + 8 } })
    Line.set(e.ChainR, "points", { { x + 30, RAIL_Y - 40 }, { x + 6, CRUCIBLE_Y + 8 } })
    -- The crucible's mouth dims as it empties.
    local full = math.max(0.15, 1 - poured / 6.5)
    Sprite.set_color(e.CrucibleGlow, 4.0 * full, 3.0 * full, 1.4 * full, 1)
    -- Steam and shimmer over each mould while it is hot.
    for i = 1, #MOULDS do
        if hot[i] then
            hot[i] = hot[i] + dt
            local k = math.max(0, 1 - hot[i] / 24)
            Sprite.set_color(e["Haze" .. (i - 1)], 1, 1, 1, 0.9 * k)
            if hot[i] > 20 then
                Particles.set_active(e["Steam" .. (i - 1)], false)
            end
            if hot[i] > 26 then hot[i] = nil end
        end
    end
    -- The furnace breathes.
    local f = 0.85 + 0.1 * math.sin(t * 7.3) + 0.06 * math.sin(t * 17.1)
    Lighting.set_intensity(e.FurnaceLight, 2.0 * f)
    UI.set_text(e.Status, phase == "pour" and string.format("pouring into mould %%d", math.floor(mould))
        or (phase == "cool" and string.format("cooling   %%d s", math.floor(math.max(0, timer)))) or phase)
end
''' % {"moulds": moulds, "cy": FD_CRUCIBLE_Y, "rail": FD_RAIL_Y, "lipx": FD_LIP[0], "lipy": FD_LIP[1]}
    (ASSETS / "scripts" / "s106_foundry.lua").write_text(src, encoding="utf-8", newline="\n")


# ── 107 Night Pursuit ───────────────────────────────────────────────────
# A getaway car tears down a wet city street at night with two police
# cruisers behind it and a helicopter's searchlight on it. The camera rides
# with the car, so the street streams past - everything else moves: the
# road, the lamps, the parked cars, the rooftops by a `velocity` each, the
# traffic and the police by the script - and `motion_blur` smears each by
# its own motion across the screen: the car stays sharp, the street streaks,
# the oncoming traffic smears hardest, and the police, keeping pace, barely.
# M turns the blur off to compare.

NP_SPEED = 1400.0
NP_PERIOD = 3600.0
NP_LANES_EAST = [-65.0, -195.0]
NP_LANES_WEST = [65.0, 195.0]


def np_moving(name, x, y, comps):
    comps = dict(comps)
    comps["transform"] = tr(x, y)
    comps["velocity"] = {"x": -NP_SPEED, "y": 0.0}
    return {"name": name, "components": comps}


def np_car(name, tex, x, y, facing, size=(128, 60), headlights=True, tint=(1, 1, 1, 1)):
    """A car and its lights: two headlight cones and its tail lights."""
    out = [ent(name, transform=tr(x, y, rot=facing), sprite=sprite(tex, size, tint, z=10))]
    if headlights:
        out.append({"name": f"{name}Beam", "parent": name, "components": {
            "transform": tr(size[0] * 0.5, 0), "spot_light": {
                "color": lin(1.0, 0.95, 0.82)[:3], "intensity": 1.5, "radius": 560.0, "angle": 0.42,
                "direction": 0.0, "falloff": 1.1, "shadow_softness": 0.0, "casts_shadows": False, "height": 0.2}}})
    out.append({"name": f"{name}Tail", "parent": name, "components": {
        "transform": tr(-size[0] * 0.5 + 4, 0), "unlit": {}, "material": additive(),
        "sprite": sprite("sprites/fx/soft_dot.png", (30, size[1] * 0.9), emissive(lin(1.0, 0.08, 0.05), 3.0), z=11)}})
    return out


def night_pursuit():
    C = "sprites/pursuit/"
    F = "sprites/fx/"
    cam = camera()
    cam["components"]["camera"]["zoom"] = 0.7
    ents = [cam]
    ents.append(ent("Ambient", transform=tr(), ambient_light={"color": lin(0.35, 0.42, 0.7)[:3], "intensity": 0.24}))
    # The street, three tiles that stream past and come round again.
    for i in range(3):
        tile = bumpy(f"Street{i}", C + "street.png", (1200, 900), (-1200 + i * 1200, 0), -60)[0]
        tile["components"]["material"].update({"specular": 1.0, "shininess": 60.0})
        tile["components"]["velocity"] = {"x": -NP_SPEED, "y": 0.0}
        ents.append(tile)
    # Rooftops along both sides, each a building of its own size and tone.
    rng = __import__("random").Random(107)
    x = -1800.0
    i = 0
    while x < -1800.0 + NP_PERIOD:
        w = rng.choice([260, 320, 380, 440])
        tone = rng.uniform(0.6, 1.1)
        for side in (1, -1):
            t = (tone * rng.uniform(0.85, 1.1), tone, tone * rng.uniform(0.95, 1.15), 1.0)
            roof = bumpy(f"Roof{i}{'N' if side > 0 else 'S'}", C + "roof.png", (w - 12, 240), (x + w / 2, side * 580), -40)[0]
            roof["components"]["sprite"]["color"] = list(t)
            roof["components"]["velocity"] = {"x": -NP_SPEED, "y": 0.0}
            ents.append(roof)
        # A neon sign on the building's street face, now and then.
        if rng.random() < 0.6:
            side = rng.choice([1, -1])
            col = rng.choice([(1.0, 0.2, 0.6), (0.2, 0.9, 1.0), (0.5, 1.0, 0.3), (1.0, 0.6, 0.1)])
            ents.append(np_moving(f"Neon{i}", x + w / 2, side * 455, {
                "unlit": {}, "sprite": sprite("sprites/fx/soft_dot.png", (w * 0.6, 16), emissive(lin(*col), 4.0), z=-30),
                "point_light": point_light(lin(*col), 0.8, 300, falloff=1.4, shadows=False, height=0.3)}))
        x += w
        i += 1
    # Street lamps along both pavements.
    for k in range(10):
        lx = -1800 + k * 360
        ly = 330 if k % 2 == 0 else -330
        ents.append(np_moving(f"Lamp{k}", lx, ly, {
            "unlit": {}, "material": additive(),
            "sprite": sprite(C + "lamp.png", (40, 40), emissive(lin(1.0, 0.85, 0.6), 3.0), z=-20),
            "point_light": point_light(lin(1.0, 0.75, 0.45), 2.1, 540, falloff=1.3, shadows=False, height=0.45)}))
    # Parked cars along the kerbs.
    for k, (px, side, tex) in enumerate([(-1500, 1, "sedan"), (-700, -1, "van"), (300, 1, "taxi"), (1100, -1, "sedan"),
                                         (1700, 1, "van"), (-200, -1, "sedan")]):
        size = (150, 66) if tex == "van" else (128, 60)
        ents.append(np_moving(f"Parked{k}", px, side * 228, {
            "sprite": sprite(C + f"{tex}.png", size, (0.8, 0.8, 0.85, 1), z=8)}))
    # The getaway car, the police, the traffic.
    ents += np_car("Coupe", C + "coupe.png", -200, NP_LANES_EAST[0], 0.0)
    for k in range(2):
        ents += np_car(f"Police{k}", C + "police.png", -700 - 260 * k, NP_LANES_EAST[k], 0.0)
        for side, col in ((1, (1.0, 0.1, 0.1)), (-1, (0.15, 0.35, 1.0))):
            tag = "Red" if side > 0 else "Blue"
            ents.append({"name": f"Police{k}{tag}", "parent": f"Police{k}", "components": {
                "transform": tr(2, side * 12), "unlit": {}, "material": additive(),
                "sprite": sprite(F + "soft_dot.png", (26, 26), emissive(lin(*col), 6.0), z=12),
                "point_light": point_light(lin(*col), 0.0, 380, falloff=1.2, shadows=False, height=0.3)}})
    for k in range(6):
        east = k < 3
        lane = (NP_LANES_EAST if east else NP_LANES_WEST)[k % 2]
        tex = ["sedan", "taxi", "van"][k % 3]
        size = (150, 66) if tex == "van" else (128, 60)
        ents += np_car(f"Traffic{k}", C + f"{tex}.png", 600 + k * 500, lane, 0.0 if east else 3.14159, size=size)
    # The helicopter: its searchlight on the car and its rotor's shadow.
    ents.append(ent("Searchlight", transform=tr(-200, -65),
                    point_light=point_light(lin(0.85, 0.92, 1.0), 2.2, 360, falloff=1.5, softness=0.0, height=0.5)))
    ents.append(ent("Rotor", transform=tr(-120, -10),
                    material={"material_id": "default_sprite", "blend_mode": "Multiply", "uniforms": {}},
                    sprite=sprite(C + "rotor.png", (620, 620), (0.45, 0.47, 0.55, 1.0), z=40)))
    ents.append(ent("Driver", transform=tr(), script=script("scripts/s107_night_pursuit.lua")))
    ents += ui_captions("107   Night Pursuit", "each thing is smeared by its own motion on screen   M motion blur   Tab captions")
    pp = post(
        bloom={"threshold": 1.0, "intensity": 0.6, "blur_size": 0.0},
        vignette={"intensity": 0.5, "smoothness": 0.5, "color": [0.0, 0.0, 0.03, 1.0]},
        grade={"brightness": 1.0, "contrast": 1.08, "saturation": 1.1, "tint": [0.9, 0.93, 1.0, 0.05]},
        chromatic={"strength": 0.0015, "on": True},
        hdr={"tonemap": "aces", "exposure": 1.1})
    pp["effects"].insert(0, {"name": "motion_blur", "enabled": True, "params": {
        "shutter": {"Float": 1.0}, "samples": {"Float": 12.0}, "max_length": {"Float": 0.08}}})
    pp["effects"].append({"name": "film_grain", "enabled": True, "params": {"intensity": {"Float": 0.035}, "size": {"Float": 1.3}}})
    return {"name": "107 - Night Pursuit", "post_process": pp, "entities": ents}


def write_night_pursuit_script():
    src = r'''-- 107 Night Pursuit: the camera rides with the getaway car, so the street
-- does the moving. The static things stream past on a `velocity` each and
-- are put back ahead when they leave; the traffic, the police and the car's
-- weaving are moved here. `motion_blur` (with its velocity pass) smears each
-- by its own motion across the screen - M switches it off to compare.

script = { tick_rate = 60 }

local nav = require("nav")
local SCENE = "scenes/107-night-pursuit.scene"

local SPEED = %(speed)f
local PERIOD = %(period)f
local LANES = { %(e0)f, %(e1)f, %(w0)f, %(w1)f }   -- two east, two west

local e = {}
local streaming = {}
local traffic = {}
local t = 0
local lane = 1
local car_y = LANES[1]
local blur_on = true
local captions = true
local rng = 107

local function rand()
    rng = (rng * 16807) %% 2147483647
    return rng / 2147483647
end

local function track(name)
    local id = Entity.find_by_name(name)
    if id then streaming[#streaming + 1] = id end
end

-- Is a lane clear around x?
local function clear(l, x)
    for _, c in ipairs(traffic) do
        if c.lane == l and math.abs(c.x - x) < 520 then return false end
    end
    return true
end

function init(entity)
    for _, n in ipairs({ "Coupe", "Searchlight", "Rotor", "Camera", "Status" }) do e[n] = Entity.find_by_name(n) end
    for i = 0, 2 do track("Street" .. i) end
    for i = 0, 40 do
        track("Roof" .. i .. "N")
        track("Roof" .. i .. "S")
        track("Neon" .. i)
    end
    for i = 0, 9 do track("Lamp" .. i) end
    for i = 0, 5 do track("Parked" .. i) end
    for k = 0, 5 do
        local east = k < 3
        traffic[#traffic + 1] = {
            e = Entity.find_by_name("Traffic" .. k), east = east, lane = east and (k %% 2 + 1) or (k %% 2 + 3),
            x = 600 + k * 500, speed = east and (650 + rand() * 250) or (800 + rand() * 300),
        }
    end
    for k = 0, 1 do
        e["Police" .. k] = Entity.find_by_name("Police" .. k)
        e["Police" .. k .. "Red"] = Entity.find_by_name("Police" .. k .. "Red")
        e["Police" .. k .. "Blue"] = Entity.find_by_name("Police" .. k .. "Blue")
    end
end

function update(entity, dt)
    nav.tick(SCENE)
    t = t + dt
    if Input.is_key_just_pressed("Tab") then captions = nav.toggle_ui_captions(captions) end
    if Input.is_key_just_pressed("M") then
        blur_on = not blur_on
        PostProcess.set_enabled("motion_blur", blur_on)
    end
    -- What streams past comes round again ahead.
    for _, id in ipairs(streaming) do
        local x, y = Transform.get_position(id)
        if x < -PERIOD / 2 then Transform.set_position(id, x + PERIOD, y) end
    end
    -- Traffic: east-bound slower than us, west-bound towards us.
    for _, c in ipairs(traffic) do
        local rel = c.east and (c.speed - SPEED) or (-c.speed - SPEED)
        c.x = c.x + rel * dt
        if c.x < -1500 then
            c.x = 1500 + rand() * 900
            c.speed = c.east and (650 + rand() * 250) or (800 + rand() * 300)
            for _ = 1, 4 do
                local l = c.east and (1 + math.floor(rand() * 2)) or (3 + math.floor(rand() * 2))
                if clear(l, c.x) then c.lane = l break end
            end
        end
        Transform.set_position(c.e, c.x, LANES[c.lane])
    end
    -- The getaway car weaves: if its lane is blocked ahead, it takes another
    -- - the oncoming ones too, when it must.
    local blocked = false
    for _, c in ipairs(traffic) do
        if c.lane == lane and c.x > -200 and c.x < 500 then blocked = true end
    end
    if blocked then
        for _, l in ipairs({ 1, 2, 3, 4 }) do
            if l ~= lane and clear(l, 100) then lane = l break end
        end
    end
    local target = LANES[lane]
    local dy = (target - car_y)
    car_y = car_y + dy * math.min(1, dt * 3.5)
    local x = -200 + math.sin(t * 0.7) * 60
    Transform.set_position(e.Coupe, x, car_y)
    Transform.set_rotation(e.Coupe, math.max(-0.35, math.min(0.35, dy * 0.004)))
    -- The police keep on its tail, closing and falling back.
    for k = 0, 1 do
        local px = x - 420 - 220 * k + math.sin(t * 0.9 + k * 2.1) * 140
        local py = car_y + (k == 0 and -1 or 1) * 70 + math.sin(t * 1.3 + k) * 30
        Transform.set_position(e["Police" .. k], px, py)
        Transform.set_rotation(e["Police" .. k], math.sin(t * 1.3 + k) * 0.06)
        local red = math.floor(t * 8 + k) %% 2 == 0
        Lighting.set_intensity(e["Police" .. k .. "Red"], red and 2.4 or 0)
        Lighting.set_intensity(e["Police" .. k .. "Blue"], red and 0 or 2.4)
        Sprite.set_color(e["Police" .. k .. "Red"], 6, 0.6, 0.6, red and 1 or 0.15)
        Sprite.set_color(e["Police" .. k .. "Blue"], 0.9, 2.1, 6, red and 0.15 or 1)
    end
    -- The helicopter's light hunts after the car, its rotor turning above.
    local sx = x + 40 * math.sin(t * 1.7)
    local sy = car_y + 30 * math.cos(t * 1.3)
    Transform.set_position(e.Searchlight, sx, sy)
    Transform.set_position(e.Rotor, sx + 90, sy + 60)
    Transform.set_rotation(e.Rotor, t * 26)
    -- The camera sways with the car.
    Transform.set_position(e.Camera, 0, car_y * 0.25)
    UI.set_text(e.Status, blur_on and "motion blur on" or "motion blur off")
end
''' % {"speed": NP_SPEED, "period": NP_PERIOD, "e0": NP_LANES_EAST[0], "e1": NP_LANES_EAST[1],
       "w0": NP_LANES_WEST[0], "w1": NP_LANES_WEST[1]}
    (ASSETS / "scripts" / "s107_night_pursuit.lua").write_text(src, encoding="utf-8", newline="\n")


# ── 108 Orbital Station ─────────────────────────────────────────────────
# A station over a planet, its shield up, under attack. Raiders (red
# crescents) make passes and fire bolts at it; every bolt that reaches the
# shield ripples it where it lands - a ring and a shockwave, both clipped to
# the bubble by a `sprite_mask`, so a ripple never spills off the shield's
# edge. Defenders (blue darts) chase them with lasers (`line`s) and missiles
# that leave smoke; the station's turrets fire too; a raider that dies
# explodes into embers, smoke, a flash and a shockwave. A low sun lights the
# normal-mapped planet, station and rocks from one side, and everything
# bright enough - the sun, the flashes - throws `lens_flare` ghosts across
# the frame. L turns the flare off to compare.

OS_STATION = (260.0, 40.0)
OS_STATION_SIZE = (600.0, 281.0)
OS_SHIELD = (780.0, 440.0)       # the bubble, full size
OS_SUN = (-600.0, 330.0)
OS_RAIDERS = 5
OS_DARTS = 4
OS_BOLTS = 24
OS_MISSILES = 6
OS_RIPPLES = 10
OS_ROCKS = 7
OS_TURRETS = [(-30.0, 52.0), (120.0, -40.0), (390.0, 50.0)]  # station-relative


def orbital_prefabs():
    F = "sprites/fx/"
    hot = lambda c, k: emissive(lin(*c), k)
    return {
        # A raider going up: embers, a flash bright enough to flare the lens,
        # smoke, and a light.
        "OsBoom": prefab("OsBoom", unlit={},
                         point_light=point_light(lin(1.0, 0.6, 0.3), 6.0, 520, falloff=1.6, shadows=False, height=0.3),
                         particle_emitter=emitter(
                             texture_id=F + "ember.png", emission_rate=0.0, burst_count=120, max_particles=120,
                             lifetime=[0.4, 1.5], speed=[70.0, 460.0], size_start=[6.0, 12.0], size_end=[1.0, 2.0],
                             color_curve=[[0.0] + hot((1.0, 0.92, 0.7, 1.0), 9.0), [0.4] + hot((1.0, 0.5, 0.15, 0.8), 4.0),
                                          [1.0] + hot((0.6, 0.12, 0.04, 0.0), 1.0)],
                             drag=1.2, blend_mode="Additive", z_order=34),
                         lifetime={"remaining": 1.8}),
        "OsFlash": prefab("OsFlash", unlit={}, particle_emitter=emitter(
            texture_id=F + "glow.png", emission_rate=0.0, burst_count=1, max_particles=1,
            lifetime=[0.45, 0.45], speed=[0.0, 0.0], size_start=[120.0, 120.0], size_end=[420.0, 420.0],
            color_curve=[[0.0] + hot((1.0, 0.9, 0.75, 1.0), 26.0), [0.3] + hot((1.0, 0.6, 0.3, 0.6), 6.0),
                         [1.0] + hot((1.0, 0.3, 0.1, 0.0), 1.0)],
            blend_mode="Additive", z_order=35), lifetime={"remaining": 0.6}),
        "OsSmoke": prefab("OsSmoke", unlit={}, particle_emitter=emitter(
            texture_id=F + "smoke.png", emission_rate=0.0, burst_count=16, max_particles=16, blend_mode="Alpha",
            lifetime=[2.0, 3.5], speed=[20.0, 90.0], size_start=[40.0, 70.0], size_end=[160.0, 240.0],
            angular_velocity=[-0.6, 0.6],
            color_curve=[[0.0] + lin(0.7, 0.4, 0.2, 0.5), [0.2] + lin(0.3, 0.27, 0.28, 0.4), [1.0] + lin(0.15, 0.15, 0.18, 0.0)],
            drag=1.6, z_order=33), lifetime={"remaining": 3.8}),
        "OsWave": prefab("OsWave", sprite=sprite("", (520, 520), (1.0, 1.0, 1.0, 1.0), z=36),
                         material={"material_id": "materials/shockwave"}, unlit={},
                         lifetime={"remaining": 0.7}),
    }


def os_ship(name, tex, size, x, y, trail_col, glow_col):
    """A fighter: lit by the sun, an engine glow and a trail behind it."""
    return [
        ent(name, transform=tr(x, y),
            sprite=sprite(tex, size, (1, 1, 1, 1), z=20),
            trail={"lifetime": 0.45, "width": size[1] * 0.28, "width_end": 0.0, "color": emissive(trail_col, 3.0),
                   "color_end": trail_col[:3] + [0.0], "min_distance": 5.0, "z_order": 19, "blend_mode": "Additive"}),
        {"name": f"{name}Engine", "parent": name, "components": {
            "transform": tr(-size[0] * 0.5, 0), "unlit": {}, "material": additive(),
            "sprite": sprite("sprites/fx/soft_dot.png", (size[1] * 0.7, size[1] * 0.5), emissive(glow_col, 5.0), z=21),
            "point_light": point_light(glow_col, 0.7, 110, falloff=1.6, shadows=False, height=0.3)}},
    ]


def orbital_station():
    C = "sprites/orbital/"
    F = "sprites/fx/"
    cam = camera()
    cam["components"]["camera"]["zoom"] = 0.75
    ents = [cam]
    ents.append(ent("Ambient", transform=tr(), ambient_light={"color": lin(0.4, 0.5, 0.85)[:3], "intensity": 0.07}))
    # Space: deep blue-black, two star fields and a faint veil.
    ents.append(ent("Space", transform=tr(), unlit={}, sprite=sprite("", (2400, 1500), lin(0.008, 0.01, 0.025), z=-100)))
    ents.append(ent("StarsFar", transform=tr(), unlit={}, sprite=sprite(
        F + "stars_far.png", (2400, 1500), lin(0.8, 0.85, 1.0, 0.8), z=-95,
        fill={"mode": "tile", "tile_size": [512.0, 512.0]})))
    ents.append(ent("StarsNear", transform=tr(), unlit={}, material=additive(), sprite=sprite(
        F + "stars_near.png", (2400, 1500), emissive(lin(1.0, 0.97, 0.92), 1.4), z=-94,
        fill={"mode": "tile", "tile_size": [640.0, 640.0]})))
    ents.append(ent("Veil", transform=tr(300, 250, rot=0.5), unlit={}, material=additive(), sprite=sprite(
        F + "nebula_veil.png", (1600, 1000), emissive(lin(0.35, 0.2, 0.7, 0.35), 1.0), z=-90)))
    # The sun, low on the left: the light on everything, and bright enough
    # to flare the lens.
    sx, sy = OS_SUN
    ents.append(ent("SunGlow", transform=tr(sx, sy), unlit={}, material=additive(),
                    sprite=sprite(F + "glow.png", (520, 520), emissive(lin(1.0, 0.75, 0.5, 0.45), 1.6), z=-60)))
    ents.append(ent("Sun", transform=tr(sx, sy), unlit={}, material=additive(),
                    sprite=sprite(F + "star_flare.png", (300, 300), emissive(lin(1.0, 0.95, 0.85), 9.0), z=-59)))
    # A small white-hot core: what the lens flare sees past its threshold.
    ents.append(ent("SunCore", transform=tr(sx, sy), unlit={}, material=additive(),
                    sprite=sprite(F + "soft_dot.png", (70, 70), emissive(lin(1.0, 0.95, 0.85), 40.0), z=-58)))
    ents.append(ent("SunLight", transform=tr(sx, sy),
                    point_light=point_light(lin(1.0, 0.93, 0.84), 2.0, 3200, 0.45, 0.0, height=0.14, shadows=False)))
    # The planet below, its night side away from the sun, and its air.
    ents.append(ent("Planet", transform=tr(-360, -700),
                    sprite=sprite(C + "planet.png", (980, 980), (1.0, 1.0, 1.0, 1.0), z=-50),
                    material={"material_id": "lit_sprite", "normal_map_id": C + "planet_n.png"}))
    # ring.png peaks at 0.82 of its radius: sized so that lands on the limb.
    ents.append(ent("Air", transform=tr(-360, -700), unlit={}, material=additive(),
                    sprite=sprite(F + "ring.png", (1214, 1214), emissive(lin(0.35, 0.6, 1.0, 0.35), 1.2), z=-49)))
    # Rocks drifting through, turning as they go.
    for i in range(OS_ROCKS):
        k = i % 3
        size = 50 + (i * 37) % 70
        ents.append(ent(f"Rock{i}", transform=tr(-900 + i * 290, 380 - (i * 173) % 760),
                        sprite=sprite(C + f"rock{k}.png", (size, size), (1, 1, 1, 1), z=-30 + i % 2 * 45),
                        material={"material_id": "lit_sprite", "normal_map_id": C + f"rock{k}_n.png"}))
    # The station: lit, normal-mapped, with blinking beacons on its wings.
    stx, sty = OS_STATION
    ents.append(ent("Station", transform=tr(stx, sty),
                    sprite=sprite(C + "station.png", OS_STATION_SIZE, (1, 1, 1, 1), z=0),
                    material={"material_id": "lit_sprite", "normal_map_id": C + "station_n.png",
                              "specular": 0.6, "shininess": 40.0}))
    for i, (bx, by, col) in enumerate([(-282, 130, (1.0, 0.15, 0.1)), (282, 130, (0.2, 1.0, 0.35)),
                                       (-282, -130, (1.0, 0.15, 0.1)), (282, -130, (0.2, 1.0, 0.35))]):
        ents.append(ent(f"Beacon{i}", transform=tr(stx + bx, sty + by), unlit={}, material=additive(),
                        sprite=sprite(F + "soft_dot.png", (22, 22), emissive(lin(*col), 6.0), z=2),
                        point_light=point_light(lin(*col), 0.0, 90, falloff=1.6, shadows=False)))
    for i, (tx, ty) in enumerate(OS_TURRETS):
        ents.append(ent(f"Turret{i}", transform=tr(stx + tx, sty + ty), unlit={}, material=additive(),
                        sprite=sprite(F + "soft_dot.png", (16, 16), emissive(lin(0.5, 0.9, 1.0), 4.0), z=3)))
    # The shield: a bubble round the station, a flash of it when it is hit,
    # and the mask every ripple is clipped to.
    shw, shh = OS_SHIELD
    ents.append(ent("ShieldMask", transform=tr(stx, sty),
                    sprite_mask={"shape": {"Ellipse": {"size": [shw * 0.985, shh * 0.985]}}, "feather": 6.0}))
    ents.append(ent("Shield", transform=tr(stx, sty), unlit={}, material=additive(),
                    sprite=sprite(C + "shield.png", (shw, shh), emissive(lin(0.5, 0.85, 1.0, 0.55), 1.4), z=10)))
    ents.append(ent("ShieldFlash", transform=tr(stx, sty), unlit={}, material=additive(),
                    sprite=sprite(C + "shield.png", (shw, shh), emissive(lin(0.6, 0.9, 1.0, 0.0), 3.0), z=11)))
    for i in range(OS_RIPPLES):
        ents.append(ent(f"Ripple{i}", transform=tr(0, -5000), unlit={}, material=additive(),
                        masked={"by": "ShieldMask", "outside": False},
                        sprite=sprite(F + "ring.png", (40, 40), emissive(lin(0.55, 0.9, 1.0, 0.0), 5.0), z=12),
                        point_light=point_light(lin(0.5, 0.85, 1.0), 0.0, 260, falloff=1.5, shadows=False)))
        ents.append(ent(f"RippleWave{i}", transform=tr(0, -5000), unlit={},
                        masked={"by": "ShieldMask", "outside": False},
                        material={"material_id": "materials/shockwave"},
                        sprite=sprite("", (260, 260), (1.0, 1.0, 1.0, 1.0), z=13)))
    # The fighters.
    for i in range(OS_RAIDERS):
        ents += os_ship(f"Raider{i}", C + "crescent.png", (64, 43), 1200, 400 - i * 200,
                        lin(1.0, 0.35, 0.2, 0.6), lin(1.0, 0.45, 0.2))
    for i in range(OS_DARTS):
        ents += os_ship(f"Dart{i}", C + "dart.png", (64, 43), stx - 200 + i * 120, sty - 300,
                        lin(0.3, 0.7, 1.0, 0.6), lin(0.4, 0.8, 1.0))
        # Its laser: a hot core and a wide glow, both `line`s.
        beam = lambda w, c: {"points": [[0.0, -5000.0], [1.0, -5000.0]], "width": w, "color": c,
                             "z_order": 32, "blend_mode": "Additive", "begin_cap": "round", "end_cap": "round"}
        ents.append(ent(f"Dart{i}Glow", transform=tr(), unlit={}, line=beam(12.0, emissive(lin(0.2, 0.7, 1.0, 0.35), 2.5))))
        ents.append(ent(f"Dart{i}Beam", transform=tr(), unlit={}, line=beam(3.0, emissive(lin(0.75, 0.97, 1.0, 1.0), 6.0))))
    for i in range(len(OS_TURRETS)):
        beam = lambda w, c: {"points": [[0.0, -5000.0], [1.0, -5000.0]], "width": w, "color": c,
                             "z_order": 32, "blend_mode": "Additive", "begin_cap": "round", "end_cap": "round"}
        ents.append(ent(f"Turret{i}Glow", transform=tr(), unlit={}, line=beam(18.0, emissive(lin(0.3, 1.0, 0.6, 0.3), 2.5))))
        ents.append(ent(f"Turret{i}Beam", transform=tr(), unlit={}, line=beam(4.0, emissive(lin(0.8, 1.0, 0.85, 1.0), 7.0))))
    # The raiders' bolts: hot streaks with a ribbon and a light each.
    for i in range(OS_BOLTS):
        ents.append(ent(f"Bolt{i}", transform=tr(0, -5000), unlit={}, material=additive(),
                        sprite=sprite(F + "spark.png", (44, 7), emissive(lin(1.0, 0.35, 0.2), 6.0)[:3] + [0.0], z=31),
                        trail={"lifetime": 0.12, "width": 4.0, "width_end": 0.0, "color": emissive(lin(1.0, 0.3, 0.15, 0.7), 3.0),
                               "color_end": lin(1.0, 0.2, 0.1, 0.0), "min_distance": 6.0, "z_order": 30,
                               "emitting": False, "blend_mode": "Additive"},
                        point_light=point_light(lin(1.0, 0.35, 0.2), 0.0, 110, falloff=1.6, shadows=False)))
    # Missiles: lit bodies, an exhaust, a smoke trail of particles.
    for i in range(OS_MISSILES):
        ents.append(ent(f"Missile{i}", transform=tr(0, -5000),
                        sprite=sprite(C + "missile.png", (30, 8), (1, 1, 1, 1), z=26)))
        ents.append({"name": f"Missile{i}Exhaust", "parent": f"Missile{i}", "components": {
            "transform": tr(-17, 0), "unlit": {}, "material": additive(),
            "sprite": sprite(F + "soft_dot.png", (22, 12), emissive(lin(1.0, 0.75, 0.4), 6.0), z=27),
            "point_light": point_light(lin(1.0, 0.7, 0.4), 0.9, 120, falloff=1.6, shadows=False)}})
        ents.append(ent(f"Missile{i}Smoke", transform=tr(0, -5000), unlit={}, particle_emitter=emitter(
            texture_id=F + "smoke.png", emission_rate=150.0, max_particles=280, blend_mode="Alpha", active=False,
            lifetime=[0.9, 1.6], speed=[4.0, 18.0], size_start=[18.0, 24.0], size_end=[50.0, 80.0],
            angular_velocity=[-0.8, 0.8],
            color_curve=[[0.0] + lin(0.95, 0.75, 0.55, 0.5), [0.15] + lin(0.6, 0.6, 0.65, 0.35), [1.0] + lin(0.4, 0.42, 0.5, 0.0)],
            drag=0.8, z_order=25)))
    ents.append(ent("Battle", transform=tr(), script=script("scripts/s108_orbital_station.lua")))
    ents += ui_captions("108   Orbital Station", "every hit ripples the shield where it lands   L lens flare   Tab captions")
    pp = post(
        bloom={"threshold": 1.0, "intensity": 0.6, "blur_size": 0.0},
        vignette={"intensity": 0.45, "smoothness": 0.55, "color": [0.0, 0.0, 0.02, 1.0]},
        grade={"brightness": 1.0, "contrast": 1.06, "saturation": 1.08, "tint": [0.95, 0.95, 1.0, 0.04]},
        chromatic={"strength": 0.0012, "on": True},
        hdr={"tonemap": "aces", "exposure": 1.0})
    pp["effects"].insert(0, {"name": "lens_flare", "enabled": True, "params": {
        "threshold": {"Float": 5.0}, "intensity": {"Float": 0.8}, "ghosts": {"Float": 6.0},
        "spacing": {"Float": 0.32}, "halo": {"Float": 0.42}, "halo_width": {"Float": 0.05},
        "dispersion": {"Float": 0.008}, "streak": {"Float": 0.6}, "streak_length": {"Float": 0.3},
        "tint": {"Vec4": [1.0, 0.85, 0.7, 1.0]}}})
    return {"name": "108 - Orbital Station", "post_process": pp, "entities": ents}


def write_orbital_station_script():
    src = r'''-- 108 Orbital Station: raiders make passes at a shielded station and the
-- defenders chase them. The flying and the shooting are this script; what
-- you see is the engine's - every bolt that reaches the shield ripples it
-- where it lands (a ring and a shockwave clipped to the bubble by a
-- `sprite_mask`), lasers are `line`s, missiles trail particle smoke, and a
-- raider that dies goes up in prefabs of particles, a flash and a wave.
-- The sun and the flashes are bright enough to flare the lens (`lens_flare`);
-- L turns it off to compare.

script = { tick_rate = 60 }

local nav = require("nav")
local SCENE = "scenes/108-orbital-station.scene"
local atan2 = math.atan2 or function(y, x) return math.atan(y, x) end

local STX, STY = %(stx)f, %(sty)f
local SHW, SHH = %(shw)f, %(shh)f
local RAIDERS, DARTS, BOLTS, MISSILES, RIPPLES, ROCKS = %(raiders)d, %(darts)d, %(bolts)d, %(missiles)d, %(ripples)d, %(rocks)d
local TURRETS = %(turrets)s

local e = {}
local raiders, darts, bolts, missiles, ripples, rocks, turrets = {}, {}, {}, {}, {}, {}, {}
local booms = {}
local t = 0
local rng = 108
local captions = true
local flare_on = true
local flash = 0
local hits = 0
local downed = 0

local function rand()
    rng = (rng * 16807) %% 2147483647
    return rng / 2147483647
end
local function between(a, b) return a + (b - a) * rand() end
local function wrap(a)
    while a > math.pi do a = a - 2 * math.pi end
    while a < -math.pi do a = a + 2 * math.pi end
    return a
end

-- Is (x, y) inside the shield? (1 at its rim.)
local function shield_at(x, y)
    local dx, dy = (x - STX) / (SHW * 0.5), (y - STY) / (SHH * 0.5)
    return math.sqrt(dx * dx + dy * dy)
end

local function spawn(prefab, x, y)
    local h = Entity.spawn_prefab(prefab)
    Transform.set_position(h, x, y)
    return h
end

-- Turn a ship toward (tx, ty) at `rate`, and fly it on at its speed.
local function steer(s, tx, ty, rate, dt)
    local want = atan2(ty - s.y, tx - s.x)
    local d = wrap(want - s.a)
    s.a = s.a + math.max(-rate * dt, math.min(rate * dt, d))
    s.x = s.x + math.cos(s.a) * s.speed * dt
    s.y = s.y + math.sin(s.a) * s.speed * dt
    return math.abs(d)
end

local function ripple(x, y, strength)
    for _, r in ipairs(ripples) do
        if r.age >= r.life then
            r.x, r.y, r.age, r.life, r.k = x, y, 0, 0.75, strength
            hits = hits + 1
            flash = math.min(1, flash + 0.35 * strength)
            return
        end
    end
end

local function explode(x, y)
    spawn("OsBoom", x, y)
    spawn("OsFlash", x, y)
    spawn("OsSmoke", x, y)
    booms[#booms + 1] = { e = spawn("OsWave", x, y), age = 0 }
    downed = downed + 1
end

local function park(id) Transform.set_position(id, 0, -5000) end
local function beam_off(name)
    Line.set(e[name .. "Beam"], "points", { { 0, -5000 }, { 1, -5000 } })
    Line.set(e[name .. "Glow"], "points", { { 0, -5000 }, { 1, -5000 } })
end
local function beam_on(name, x0, y0, x1, y1, flicker)
    local w = 1 + 0.25 * math.sin(t * 90 + x0)
    Line.set(e[name .. "Beam"], "points", { { x0, y0 }, { x1, y1 } })
    Line.set(e[name .. "Glow"], "points", { { x0, y0 }, { x1, y1 } })
    Line.set(e[name .. "Beam"], "width", (flicker or 3) * w)
end

local function respawn(r)
    r.x = between(1050, 1250)
    r.y = between(-450, 450)
    r.a = math.pi + between(-0.3, 0.3)
    r.hp = 5
    r.dead = false
    r.respawn = 0
    r.cool = between(0.5, 1.5)
    r.orbit = between(0, 2 * math.pi)
end

function init(entity)
    for _, n in ipairs({ "Status", "ShieldFlash", "Shield" }) do e[n] = Entity.find_by_name(n) end
    for i = 0, RAIDERS - 1 do
        local r = { e = Entity.find_by_name("Raider" .. i), speed = between(330, 380) }
        respawn(r)
        r.x = r.x + i * 260
        raiders[#raiders + 1] = r
    end
    for i = 0, DARTS - 1 do
        local name = "Dart" .. i
        e[name .. "Beam"] = Entity.find_by_name(name .. "Beam")
        e[name .. "Glow"] = Entity.find_by_name(name .. "Glow")
        darts[#darts + 1] = { e = Entity.find_by_name(name), name = name, x = STX - 200 + i * 120, y = STY - 300,
                              a = 1.4, speed = between(400, 440), cool = between(0.5, 2), firing = 0, missile = between(2, 5) }
    end
    for i, p in ipairs(TURRETS) do
        local name = "Turret" .. (i - 1)
        e[name .. "Beam"] = Entity.find_by_name(name .. "Beam")
        e[name .. "Glow"] = Entity.find_by_name(name .. "Glow")
        turrets[#turrets + 1] = { name = name, x = STX + p[1], y = STY + p[2], cool = between(1, 3), firing = 0 }
    end
    for i = 0, BOLTS - 1 do
        local id = Entity.find_by_name("Bolt" .. i)
        bolts[#bolts + 1] = { e = id, live = false }
    end
    for i = 0, MISSILES - 1 do
        missiles[#missiles + 1] = { e = Entity.find_by_name("Missile" .. i), smoke = Entity.find_by_name("Missile" .. i .. "Smoke"), live = false }
    end
    for i = 0, RIPPLES - 1 do
        ripples[#ripples + 1] = { e = Entity.find_by_name("Ripple" .. i), wave = Entity.find_by_name("RippleWave" .. i), age = 1, life = 0 }
    end
    for i = 0, ROCKS - 1 do
        local id = Entity.find_by_name("Rock" .. i)
        local x, y = Transform.get_position(id)
        rocks[#rocks + 1] = { e = id, x = x, y = y, vx = between(-40, -14), vy = between(-8, 8), a = between(0, 6), w = between(-0.5, 0.5) }
    end
    for i = 0, 3 do e["Beacon" .. i] = Entity.find_by_name("Beacon" .. i) end
end

local function fire_bolt(r)
    for _, b in ipairs(bolts) do
        if not b.live then
            -- Aimed at the station, a little off.
            local tx, ty = STX + between(-120, 120), STY + between(-60, 60)
            local a = atan2(ty - r.y, tx - r.x)
            b.live, b.x, b.y, b.vx, b.vy, b.age = true, r.x + math.cos(a) * 30, r.y + math.sin(a) * 30,
                math.cos(a) * 1300, math.sin(a) * 1300, 0
            Transform.set_position(b.e, b.x, b.y)
            Transform.set_rotation(b.e, a)
            Trail.clear(b.e)
            Trail.set_emitting(b.e, true)
            Sprite.set_color(b.e, 6, 2.1, 1.2, 1)
            Lighting.set_intensity(b.e, 1.2)
            return
        end
    end
end

local function fire_missile(d, target)
    for _, m in ipairs(missiles) do
        if not m.live then
            m.live, m.x, m.y, m.a, m.speed, m.target, m.age = true, d.x, d.y, d.a + between(-0.6, 0.6), 380, target, 0
            Particles.set(m.smoke, "active", true)
            return
        end
    end
end

local function nearest_raider(x, y, reach)
    local best, bd = nil, reach
    for _, r in ipairs(raiders) do
        if not r.dead then
            local d = math.sqrt((r.x - x) ^ 2 + (r.y - y) ^ 2)
            if d < bd then best, bd = r, d end
        end
    end
    return best, bd
end

local function hurt(r, n)
    if r.dead then return end
    r.hp = r.hp - n
    if r.hp <= 0 then
        r.dead = true
        r.respawn = between(2.5, 4.5)
        explode(r.x, r.y)
        Trail.set_emitting(r.e, false)
        Trail.clear(r.e)
        park(r.e)
    end
end

function update(entity, dt)
    nav.tick(SCENE)
    t = t + dt
    if Input.is_key_just_pressed("Tab") then captions = nav.toggle_ui_captions(captions) end
    if Input.is_key_just_pressed("L") then
        flare_on = not flare_on
        PostProcess.set_enabled("lens_flare", flare_on)
    end

    -- Raiders: in from the right, a pass round the shield firing as they
    -- go, out and round again.
    for _, r in ipairs(raiders) do
        if r.dead then
            r.respawn = r.respawn - dt
            if r.respawn <= 0 then
                respawn(r)
                Trail.clear(r.e)
                Trail.set_emitting(r.e, true)
            end
        else
            r.orbit = r.orbit + dt * 0.45
            local tx = STX + math.cos(r.orbit) * SHW * 0.72
            local ty = STY + math.sin(r.orbit) * SHH * 0.85
            steer(r, tx, ty, 2.2, dt)
            r.cool = r.cool - dt
            local rim = shield_at(r.x, r.y)
            if r.cool <= 0 and rim < 2.0 and rim > 1.05 then
                fire_bolt(r)
                r.cool = between(0.35, 0.9)
            end
            Transform.set_position(r.e, r.x, r.y)
            Transform.set_rotation(r.e, r.a)
        end
    end

    -- Bolts fly until the shield takes them.
    for _, b in ipairs(bolts) do
        if b.live then
            b.x, b.y, b.age = b.x + b.vx * dt, b.y + b.vy * dt, b.age + dt
            if shield_at(b.x, b.y) <= 1.0 then
                ripple(b.x, b.y, 1.0)
                b.live = false
            elseif b.age > 1.5 then
                b.live = false
            end
            if b.live then
                Transform.set_position(b.e, b.x, b.y)
            else
                Trail.set_emitting(b.e, false)
                Trail.clear(b.e)
                Sprite.set_color(b.e, 6, 2.1, 1.2, 0)
                Lighting.set_intensity(b.e, 0)
                park(b.e)
            end
        end
    end

    -- Darts chase the nearest raider, firing their lasers when it is in
    -- their sights, and now and then a missile.
    for _, d in ipairs(darts) do
        local r, dist = nearest_raider(d.x, d.y, 4000)
        local off = 4
        if r then
            off = steer(d, r.x + math.cos(r.a) * 120, r.y + math.sin(r.a) * 120, 2.6, dt)
        else
            d.orbit = (d.orbit or 0) + dt * 0.5
            steer(d, STX + math.cos(d.orbit) * 500, STY + math.sin(d.orbit) * 320, 2.0, dt)
        end
        d.cool = d.cool - dt
        d.missile = d.missile - dt
        if r and d.cool <= 0 and off < 0.2 and dist < 520 then
            d.firing, d.cool = 0.18, between(0.8, 1.6)
        end
        if d.firing > 0 then
            d.firing = d.firing - dt
            if r then
                beam_on(d.name, d.x + math.cos(d.a) * 30, d.y + math.sin(d.a) * 30, r.x, r.y)
                if d.firing <= 0 then hurt(r, 1) end
            end
        else
            beam_off(d.name)
        end
        if r and d.missile <= 0 and dist < 900 then
            fire_missile(d, r)
            d.missile = between(3, 6)
        end
        Transform.set_position(d.e, d.x, d.y)
        Transform.set_rotation(d.e, d.a)
    end

    -- Missiles home and leave smoke.
    for _, m in ipairs(missiles) do
        if m.live then
            m.age = m.age + dt
            m.speed = math.min(900, m.speed + 700 * dt)
            local r = m.target
            if r.dead then r = nearest_raider(m.x, m.y, 4000) or r; m.target = r end
            steer(m, r.x, r.y, 3.2, dt)
            local hit = not r.dead and (r.x - m.x) ^ 2 + (r.y - m.y) ^ 2 < 34 * 34
            if hit then hurt(r, 3) end
            if hit or m.age > 4 then
                if not hit then explode(m.x, m.y); downed = downed - 1 end
                m.live = false
                Particles.set(m.smoke, "active", false)
                park(m.e)
            else
                Transform.set_position(m.e, m.x, m.y)
                Transform.set_rotation(m.e, m.a)
                Transform.set_position(m.smoke, m.x - math.cos(m.a) * 18, m.y - math.sin(m.a) * 18)
            end
        end
    end

    -- The station's turrets fire through the shield at raiders in reach.
    for _, tu in ipairs(turrets) do
        tu.cool = tu.cool - dt
        local r, dist = nearest_raider(tu.x, tu.y, 700)
        if r and tu.cool <= 0 then
            tu.firing, tu.cool, tu.target = 0.22, between(1.8, 3.2), r
        end
        if tu.firing > 0 and tu.target and not tu.target.dead then
            tu.firing = tu.firing - dt
            beam_on(tu.name, tu.x, tu.y, tu.target.x, tu.target.y, 4)
            if tu.firing <= 0 then hurt(tu.target, 1) end
        else
            tu.firing = 0
            beam_off(tu.name)
        end
    end

    -- Ripples spread over the shield and fade; the shield flashes with hits.
    for _, r in ipairs(ripples) do
        if r.age < r.life then
            r.age = r.age + dt
            local p = math.min(1, r.age / r.life)
            local s = 40 + 360 * p
            Transform.set_position(r.e, r.x, r.y)
            Transform.set_scale(r.e, s / 40, s / 40)
            local a = (1 - p) ^ 1.5 * r.k
            Sprite.set_color(r.e, 2.4, 4.5, 5.0, a)
            Lighting.set_intensity(r.e, 2.2 * a)
            Transform.set_position(r.wave, r.x, r.y)
            Material.set_vec4(r.wave, "progress", p, 0, 0, 0)
            Material.set_vec4(r.wave, "tint", 0.3 * (1 - p), 0.7 * (1 - p), 1.0 * (1 - p), 0)
            if r.age >= r.life then
                Lighting.set_intensity(r.e, 0)
                park(r.e)
                park(r.wave)
            end
        end
    end
    flash = math.max(0, flash - dt * 1.8)
    Sprite.set_color(e.ShieldFlash, 1.75, 2.4, 3.0, flash * 0.6)
    local hum = 0.5 + 0.06 * math.sin(t * 2.3)
    Sprite.set_color(e.Shield, 0.35, 0.95, 1.4, hum)

    -- Explosion waves.
    for i = #booms, 1, -1 do
        local w = booms[i]
        w.age = w.age + dt
        if w.age > 0.65 then
            table.remove(booms, i)
        else
            Material.set_vec4(w.e, "progress", w.age / 0.65, 0, 0, 0)
            Material.set_vec4(w.e, "tint", 1.0, 0.55, 0.25, 0)
        end
    end

    -- Rocks drift by and come round again.
    for _, k in ipairs(rocks) do
        k.x, k.y, k.a = k.x + k.vx * dt, k.y + k.vy * dt, k.a + k.w * dt
        if k.x < -1150 then k.x = 1150 end
        Transform.set_position(k.e, k.x, k.y)
        Transform.set_rotation(k.e, k.a)
    end

    -- The beacons blink.
    for i = 0, 3 do
        local on = math.floor(t * 1.2 + i * 0.5) %% 2 == 0
        Lighting.set_intensity(e["Beacon" .. i], on and 1.4 or 0)
        Sprite.set_color(e["Beacon" .. i], i %% 2 == 0 and 6 or 1.2, i %% 2 == 0 and 0.9 or 6, i %% 2 == 0 and 0.6 or 2.1, on and 1 or 0.1)
    end

    UI.set_text(e.Status, string.format("shield hits %%d   raiders down %%d   lens flare %%s", hits, downed, flare_on and "on" or "off"))
end
''' % {"stx": OS_STATION[0], "sty": OS_STATION[1], "shw": OS_SHIELD[0], "shh": OS_SHIELD[1],
       "raiders": OS_RAIDERS, "darts": OS_DARTS, "bolts": OS_BOLTS, "missiles": OS_MISSILES,
       "ripples": OS_RIPPLES, "rocks": OS_ROCKS,
       "turrets": "{ " + ", ".join(f"{{ {x:.1f}, {y:.1f} }}" for x, y in OS_TURRETS) + " }"}
    (ASSETS / "scripts" / "s108_orbital_station.lua").write_text(src, encoding="utf-8", newline="\n")


# ── 109 Mirror Maze ─────────────────────────────────────────────────────
# A carnival hall of mirrors from above: a small chequered room walled by
# four `mirror`s, each reflecting the room twice over - so the room repeats
# outward on every side, and since every mirror shows the mirrors it faces,
# the corners fill with reflections of reflections, a kaleidoscope that
# builds itself a frame a step. A laser turns in the middle and bounces
# round the walls, and every bounce is in every copy; marquee bulbs chase
# round the frames; visitors wander, and now and then one steps into the
# portal in the floor - a camera drawing into a texture, clipped to a disc -
# and turns up in the sunny garden it looks down on. M turns the mirrors off.

MM_RX, MM_RY = 280.0, 150.0      # the room, half its size
MM_DN, MM_DE = 520.0, 840.0      # mirror depth: north / south, east / west
MM_PORTAL = (150.0, 0.0)
MM_LASER = (-130.0, 0.0)
MM_GARDEN = (8000.0, 0.0)
MM_VISITORS = 5


def mirror_maze():
    C = "sprites/mirrors/"
    F = "sprites/fx/"
    G = "sprites/garden/"
    cam = camera()
    cam["components"]["camera"]["zoom"] = 0.62
    ents = [cam]
    ents.append(ent("Ambient", transform=tr(), ambient_light={"color": lin(0.5, 0.45, 0.8)[:3], "intensity": 0.14}))
    rx, ry = MM_RX, MM_RY
    # The floor, inside the room only: everything past the walls is mirror.
    floor = bumpy("Floor", C + "floor.png", (2 * rx, 2 * ry), (0, 0), -50, tile=(150, 150))[0]
    floor["components"]["material"].update({"specular": 0.8, "shininess": 50.0})
    ents.append(floor)
    # The four mirrors, each facing into the room: north and south as deep as
    # the room is tall and more, east and west as deep as it is wide and more,
    # each long enough to take in the corners - where the reflections of
    # reflections are.
    width_ns = 2 * rx + 2 * MM_DE
    width_ew = 2 * ry + 2 * MM_DN
    # Glass a little dark and blue: each reflection is dimmer than the one
    # it reflects, which is what tells the room from its copies.
    glass = lin(0.6, 0.66, 0.8)
    for name, (x, y, rot, w, d) in {
        "MirrorN": (0.0, ry, math.pi, width_ns, MM_DN),
        "MirrorS": (0.0, -ry, 0.0, width_ns, MM_DN),
        "MirrorE": (rx, 0.0, math.pi / 2, width_ew, MM_DE),
        "MirrorW": (-rx, 0.0, -math.pi / 2, width_ew, MM_DE),
    }.items():
        ents.append(ent(name, transform=tr(x, y, rot), mirror={
            "width": w, "depth": d, "resolution": 0.75, "tint": glass[:3] + [1.0], "z_order": -45}))
    # The gilt frames the mirrors sit in, and the glass's sheen along each.
    for name, (x, y, rot, length) in {
        "FrameN": (0.0, ry + 8, 0.0, 2 * rx + 32), "FrameS": (0.0, -ry - 8, math.pi, 2 * rx + 32),
        "FrameE": (rx + 8, 0.0, math.pi / 2, 2 * ry + 32), "FrameW": (-rx - 8, 0.0, -math.pi / 2, 2 * ry + 32),
    }.items():
        fr = bumpy(name, C + "frame.png", (length, 16), (x, y), 5, tile=(128, 16), rot=rot)[0]
        fr["components"]["material"].update({"specular": 1.0, "shininess": 40.0})
        ents.append(fr)
    for name, pts in {
        "SheenN": [[-rx, ry - 1], [rx, ry - 1]], "SheenS": [[-rx, -ry + 1], [rx, -ry + 1]],
        "SheenE": [[rx - 1, -ry], [rx - 1, ry]], "SheenW": [[-rx + 1, -ry], [-rx + 1, ry]],
    }.items():
        ents.append(ent(name, transform=tr(), unlit={}, line={
            "points": pts, "width": 2.0, "color": emissive(lin(0.75, 0.9, 1.0, 0.7), 1.6), "z_order": 6,
            "blend_mode": "Additive"}))
    # Marquee bulbs round the frames, chased by the script.
    k = 0
    for side, (x0, y0, x1, y1) in enumerate([(-rx, ry + 18, rx, ry + 18), (rx + 18, ry, rx + 18, -ry),
                                             (rx, -ry - 18, -rx, -ry - 18), (-rx - 18, -ry, -rx - 18, ry)]):
        n = int(math.hypot(x1 - x0, y1 - y0) // 40)
        for i in range(n):
            t = (i + 0.5) / n
            ents.append(ent(f"Bulb{k}", transform=tr(x0 + (x1 - x0) * t, y0 + (y1 - y0) * t), unlit={},
                            material=additive(),
                            sprite=sprite(F + "soft_dot.png", (14, 14), emissive(lin(1.0, 0.85, 0.5), 4.0), z=7)))
            k += 1
    # Lights in the corners, breathing: warm, with a rose and a teal.
    for i, (x, y, col) in enumerate([(-rx + 40, ry - 40, (1.0, 0.62, 0.78)), (rx - 40, ry - 40, (1.0, 0.85, 0.65)),
                                     (rx - 40, -ry + 40, (0.6, 0.9, 1.0)), (-rx + 40, -ry + 40, (1.0, 0.85, 0.65))]):
        ents.append(ent(f"Corner{i}", transform=tr(x, y),
                        point_light=point_light(lin(*col), 0.9, 380, falloff=1.4, shadows=False, height=0.35)))
    # The laser: a brass drum turning in the middle, its beam a hot core
    # and a wide glow, both `line`s, with a light at every bounce.
    lx, ly = MM_LASER
    las = bumpy("Laser", C + "laser.png", (56, 56), (lx, ly), 8)[0]
    las["components"]["material"].update({"specular": 1.0, "shininess": 60.0})
    ents.append(las)
    beam = lambda w, c: {"points": [[lx, ly], [lx + 1, ly]], "width": w, "color": c, "z_order": 30,
                         "blend_mode": "Additive", "begin_cap": "round", "end_cap": "round", "joint": "round"}
    ents.append(ent("BeamGlow", transform=tr(), unlit={}, line=beam(14.0, emissive(lin(1.0, 0.15, 0.2, 0.35), 2.5))))
    ents.append(ent("Beam", transform=tr(), unlit={}, line=beam(3.0, emissive(lin(1.0, 0.75, 0.75, 1.0), 7.0))))
    for i in range(8):
        ents.append(ent(f"Hit{i}", transform=tr(0, -5000), unlit={}, material=additive(),
                        sprite=sprite(F + "soft_dot.png", (30, 30), emissive(lin(1.0, 0.25, 0.25), 5.0), z=31),
                        point_light=point_light(lin(1.0, 0.25, 0.25), 0.9, 90, falloff=1.6, shadows=False)))
    # The portal in the floor: a disc showing what the garden camera sees,
    # clipped round, a rune ring and a glow round its rim.
    px, py = MM_PORTAL
    ents.append(ent("PortalMask", transform=tr(px, py), sprite_mask={"shape": {"Ellipse": {"size": [128.0, 128.0]}},
                                                                    "feather": 3.0}))
    ents.append(ent("Portal", transform=tr(px, py), unlit={}, masked={"by": "PortalMask", "outside": False},
                    sprite=sprite("portal_view", (132, 132), (1, 1, 1, 1), z=-40)))
    ents.append(ent("PortalRunes", transform=tr(px, py), unlit={}, material=additive(),
                    sprite=sprite(F + "rune_ring.png", (176, 176), emissive(lin(0.7, 0.4, 1.0, 0.9), 2.5), z=-39)))
    ents.append(ent("PortalGlow", transform=tr(px, py), unlit={}, material=additive(),
                    sprite=sprite(F + "ring.png", (170, 170), emissive(lin(0.6, 0.4, 1.0, 0.6), 2.0), z=-39),
                    point_light=point_light(lin(0.7, 0.45, 1.0), 1.2, 200, falloff=1.5, shadows=False, height=0.3)))
    # The garden it looks down on, far away: lawn, a fountain, flowers, a
    # warm light of its own, and the camera drawing it into `portal_view`.
    gx, gy = MM_GARDEN
    ents.append(ent("GardenLawn", transform=tr(gx, gy),
                    sprite=sprite(G + "lawn.png", (700, 700), (1, 1, 1, 1), z=-60,
                                  fill={"mode": "tile", "tile_size": [256.0, 256.0]})))
    ents.append(ent("GardenFountain", transform=tr(gx, gy), sprite=sprite(G + "fountain.png", (150, 150), (1, 1, 1, 1), z=1)))
    for i, (x, y) in enumerate([(-150, 120), (160, -110), (150, 140), (-140, -130)]):
        ents.append(ent(f"GardenBed{i}", transform=tr(gx + x, gy + y),
                        sprite=sprite(G + "rosebed.png", (130, 80), (1, 1, 1, 1), z=2)))
    ents.append(ent("GardenSun", transform=tr(gx, gy + 100),
                    point_light=point_light(lin(1.0, 0.9, 0.7), 2.6, 900, falloff=0.8, shadows=False, height=0.6)))
    ents.append(ent("GardenCam", transform=tr(gx, gy), camera={
        "zoom": 1.0, "is_active": True, "viewport_width": 420.0, "viewport_height": 420.0,
        "target": "portal_view", "target_size": [384, 384]}))
    for i in range(2):
        ents.append(ent(f"Picnicker{i}", transform=tr(gx - 60 + i * 120, gy - 60, 1.2 + i),
                        sprite=sprite(G + f"guest_{4 + i}.png", (30, 30), (1, 1, 1, 1), z=20)))
    # The visitors.
    for i in range(MM_VISITORS):
        ents.append(ent(f"Visitor{i}", transform=tr(-200 + i * 90, -80 + (i % 2) * 150, i * 1.3),
                        sprite=sprite(G + f"guest_{(i % 6) + 1}.png", (30, 30), (1, 1, 1, 1), z=20)))
    ents.append(ent("Keeper", transform=tr(), script=script("scripts/s109_mirror_maze.lua")))
    ents += ui_captions("109   Mirror Maze", "four mirrors, each showing the others   M mirrors   Tab captions")
    pp = post(
        bloom={"threshold": 1.0, "intensity": 0.6, "blur_size": 0.0},
        vignette={"intensity": 0.55, "smoothness": 0.5, "color": [0.02, 0.0, 0.04, 1.0]},
        grade={"brightness": 1.0, "contrast": 1.06, "saturation": 1.12, "tint": [1.0, 0.95, 1.0, 0.04]},
        chromatic={"strength": 0.0015, "on": True},
        hdr={"tonemap": "aces", "exposure": 1.05})
    return {"name": "109 - Mirror Maze", "post_process": pp, "entities": ents}


def write_mirror_maze_script():
    src = r'''-- 109 Mirror Maze: four mirrors wall a small room, and everything in it is
-- shown again in each - and in each mirror's reflection of the others. This
-- script moves what is in the room: the laser turning and bouncing, the
-- bulbs chasing, the lights breathing, the visitors wandering - and now and
-- then one of them stepping into the portal and out into the garden it
-- looks down on. The mirrors themselves are the engine's (`mirror`).

script = { tick_rate = 60 }

local nav = require("nav")
local SCENE = "scenes/109-mirror-maze.scene"

local RX, RY = %(rx)f, %(ry)f
local LX, LY = %(lx)f, %(ly)f
local PX, PY = %(px)f, %(py)f
local GX, GY = %(gx)f, %(gy)f
local VISITORS = %(visitors)d
local MIRRORS = { "MirrorN", "MirrorS", "MirrorE", "MirrorW" }

local e = {}
local bulbs = {}
local visitors = {}
local t = 0
local rng = 109
local captions = true
local mirrors_on = true

local function rand()
    rng = (rng * 16807) %% 2147483647
    return rng / 2147483647
end
local function between(a, b) return a + (b - a) * rand() end

-- A place on the floor clear of the laser and the portal.
local function spot()
    for _ = 1, 20 do
        local x, y = between(-RX + 30, RX - 30), between(-RY + 30, RY - 30)
        if (x - LX) ^ 2 + (y - LY) ^ 2 > 60 ^ 2 and (x - PX) ^ 2 + (y - PY) ^ 2 > 90 ^ 2 then return x, y end
    end
    return 0, -RY + 40
end

function init(entity)
    for _, n in ipairs({ "Laser", "Beam", "BeamGlow", "Status", "PortalRunes", "PortalGlow" }) do e[n] = Entity.find_by_name(n) end
    for _, n in ipairs(MIRRORS) do e[n] = Entity.find_by_name(n) end
    for i = 0, 3 do e["Corner" .. i] = Entity.find_by_name("Corner" .. i) end
    for i = 0, 7 do e["Hit" .. i] = Entity.find_by_name("Hit" .. i) end
    local i = 0
    while true do
        local b = Entity.find_by_name("Bulb" .. i)
        if not b then break end
        bulbs[#bulbs + 1] = b
        i = i + 1
    end
    for k = 0, VISITORS - 1 do
        local id = Entity.find_by_name("Visitor" .. k)
        local x, y = Transform.get_position(id)
        local tx, ty = spot()
        visitors[#visitors + 1] = { e = id, x = x, y = y, tx = tx, ty = ty, a = 0, speed = between(45, 70),
                                    state = "walk", wait = between(0, 2), scale = 1 }
    end
    visitors[1].state = "portal"
end

-- The beam from the laser, bounced off the four walls.
local function beam_path(angle)
    local pts = { { LX, LY } }
    local x, y = LX, LY
    local dx, dy = math.cos(angle), math.sin(angle)
    local hits = {}
    for _ = 1, 6 do
        local tx = dx > 0 and (RX - 2 - x) / dx or (dx < 0 and (-RX + 2 - x) / dx or 1e9)
        local ty = dy > 0 and (RY - 2 - y) / dy or (dy < 0 and (-RY + 2 - y) / dy or 1e9)
        local s = math.min(tx, ty)
        x, y = x + dx * s, y + dy * s
        pts[#pts + 1] = { x, y }
        hits[#hits + 1] = { x, y }
        if tx < ty then dx = -dx else dy = -dy end
    end
    return pts, hits
end

function update(entity, dt)
    nav.tick(SCENE)
    t = t + dt
    if Input.is_key_just_pressed("Tab") then captions = nav.toggle_ui_captions(captions) end
    if Input.is_key_just_pressed("M") then
        mirrors_on = not mirrors_on
        for _, n in ipairs(MIRRORS) do Mirror.set(e[n], "enabled", mirrors_on) end
    end

    -- The laser turns slowly; its beam bounces round the room.
    local angle = t * 0.23 + 0.4
    Transform.set_rotation(e.Laser, angle)
    local pts, hits = beam_path(angle)
    local flicker = 1 + 0.15 * math.sin(t * 61)
    Line.set(e.Beam, "points", pts)
    Line.set(e.BeamGlow, "points", pts)
    Line.set(e.BeamGlow, "width", 14 * flicker)
    for i = 0, 7 do
        local h = hits[i + 1]
        if h then Transform.set_position(e["Hit" .. i], h[1], h[2]) else Transform.set_position(e["Hit" .. i], 0, -5000) end
    end

    -- Bulbs chase round the frames.
    local n = #bulbs
    for i, b in ipairs(bulbs) do
        local on = math.floor(t * 9 - i) %% 4 == 0
        local k = on and 6 or 1.2
        Sprite.set_color(b, k, k * 0.82, k * 0.45, on and 1 or 0.6)
    end

    -- Corner lights breathe, out of step.
    for i = 0, 3 do
        Lighting.set_intensity(e["Corner" .. i], 0.8 + 0.3 * math.sin(t * 0.9 + i * 1.6))
    end
    Transform.set_rotation(e.PortalRunes, t * 0.4)
    Lighting.set_intensity(e.PortalGlow, 1.1 + 0.3 * math.sin(t * 2.3))

    -- Visitors wander; the first goes through the portal, and back.
    for _, v in ipairs(visitors) do
        if v.state == "walk" or v.state == "portal" or v.state == "return" then
            local tx, ty = v.tx, v.ty
            if v.state == "portal" then tx, ty = PX, PY end
            local dx, dy = tx - v.x, ty - v.y
            local d = math.sqrt(dx * dx + dy * dy)
            if d < 4 then
                if v.state == "portal" then
                    v.state = "sink"
                else
                    v.wait = between(0.5, 2.5)
                    v.state = "wait"
                end
            else
                local step = math.min(d, v.speed * dt)
                v.x, v.y = v.x + dx / d * step, v.y + dy / d * step
                v.a = (math.atan2 or math.atan)(dy, dx)
            end
        elseif v.state == "wait" then
            v.wait = v.wait - dt
            if v.wait <= 0 then
                v.tx, v.ty = spot()
                v.state = (v == visitors[1] and rand() < 0.5) and "portal" or "walk"
            end
        elseif v.state == "sink" then
            v.scale = v.scale - dt * 1.2
            v.a = v.a + dt * 8
            if v.scale <= 0 then
                v.scale = 0
                -- Out in the garden, walking a while.
                v.x, v.y = GX + between(-60, 60), GY - 40
                v.state = "garden"
                v.wait = 6
                v.tx, v.ty = GX + between(-120, 120), GY + between(-120, 120)
            end
        elseif v.state == "garden" then
            v.scale = math.min(1, v.scale + dt * 1.5)
            v.wait = v.wait - dt
            local dx, dy = v.tx - v.x, v.ty - v.y
            local d = math.sqrt(dx * dx + dy * dy)
            if d > 4 then
                v.x, v.y = v.x + dx / d * v.speed * dt, v.y + dy / d * v.speed * dt
                v.a = (math.atan2 or math.atan)(dy, dx)
            else
                v.tx, v.ty = GX + between(-120, 120), GY + between(-120, 120)
            end
            if v.wait <= 0 then
                v.x, v.y = PX, PY
                v.scale = 0
                v.state = "rise"
            end
        elseif v.state == "rise" then
            v.scale = math.min(1, v.scale + dt * 1.2)
            v.a = v.a - dt * 8
            if v.scale >= 1 then
                v.tx, v.ty = spot()
                v.state = "walk"
            end
        end
        Transform.set_position(v.e, v.x, v.y)
        Transform.set_rotation(v.e, v.a)
        Transform.set_scale(v.e, v.scale, v.scale)
    end

    UI.set_text(e.Status, mirrors_on and "mirrors on" or "mirrors off")
end
''' % {"rx": MM_RX, "ry": MM_RY, "lx": MM_LASER[0], "ly": MM_LASER[1], "px": MM_PORTAL[0], "py": MM_PORTAL[1],
       "gx": MM_GARDEN[0], "gy": MM_GARDEN[1], "visitors": MM_VISITORS}
    (ASSETS / "scripts" / "s109_mirror_maze.lua").write_text(src, encoding="utf-8", newline="\n")


# ── 110 Harbour Storm ───────────────────────────────────────────────────
# A harbour in a storm at night, side on. The sea is a `water_surface`: a
# swell rolls under everything, the rain chops it, and what falls in - a
# crate blown off the pier, a lightning strike - splashes it, the rings
# running out along it. The boats float on that surface, not on a flat box:
# they climb the crests, drop into the troughs and heel on the slopes,
# straining at the mooring ropes that hold them to the pier. A lighthouse on
# the headland sweeps its beam through the rain; lightning flashes the
# clouds and the sea; wind drives the rain slant. S calms the storm.

HS_SEA = -120.0
HS_WATER_W, HS_WATER_D = 2000.0, 420.0
HS_PIER_Y = -40.0
HS_LANTERN = (650.0, 307.0)


def harbour_storm():
    C = "sprites/storm/"
    E = "sprites/env/"
    F = "sprites/fx/"
    cam = camera()
    cam["components"]["camera"]["zoom"] = 0.8
    ents = [cam]
    ents.append(ent("Ambient", transform=tr(), ambient_light={"color": lin(0.45, 0.52, 0.8)[:3], "intensity": 0.2}))
    # The sky and two banks of cloud, which the lightning lights.
    ents.append(ent("Sky", transform=tr(0, 80), unlit={},
                    sprite=sprite(E + "st_sky.png", (2000, 1200), lin(0.45, 0.5, 0.62), z=-100)))
    for i, (y, a, z) in enumerate([(330, 0.85, -95), (260, 0.7, -90)]):
        ents.append(ent(f"Clouds{i}", transform=tr(0, y), unlit={},
                        sprite=sprite(E + "st_clouds.png", (2600, 520), lin(0.32, 0.34, 0.42, a), z=z)))
    # The headland and the lighthouse on it, lit by the storm and the beam.
    ents += bumpy("Headland", C + "headland.png", (700, 300), (600, -60), 18)
    ents += bumpy("Lighthouse", C + "lighthouse.png", (160, 440), (650, -60), 24, anchor=(0.5, 0.0))
    lx, ly = HS_LANTERN
    # The lamp: a glow in the lantern room, the beam - a `line` in the lamp's
    # own space, widening and fading - and a spot light along it. The script
    # turns the whole entity, which sweeps both.
    ents.append(ent("Lamp", transform=tr(lx, ly, 3.14159), unlit={},
                    line={"points": [[0.0, 0.0], [1700.0, 0.0]], "width": 26.0,
                          "width_curve": [[0.0, 1.0], [1.0, 9.0]],
                          "gradient": [[0.0, 1.6, 1.5, 1.2, 0.32], [0.3, 1.0, 0.95, 0.75, 0.1], [1.0, 1.0, 0.95, 0.8, 0.0]],
                          "z_order": 30, "blend_mode": "Additive", "begin_cap": "round"},
                    spot_light={"color": lin(1.0, 0.95, 0.8)[:3], "intensity": 2.6, "radius": 1800.0, "angle": 0.1,
                                "direction": 0.0, "falloff": 0.9, "shadow_softness": 0.0, "casts_shadows": False,
                                "height": 0.3}))
    # The keeper's door at the tower's foot, which lights the rock round it.
    ents.append(ent("Door", transform=tr(650, -38), unlit={}, material=additive(),
                    sprite=sprite(F + "glow.png", (90, 90), emissive(lin(1.0, 0.75, 0.45, 0.8), 1.6), z=27),
                    point_light=point_light(lin(1.0, 0.72, 0.45), 1.8, 420, falloff=1.2, shadows=False, height=0.4)))
    ents.append(ent("LampGlow", transform=tr(lx, ly), unlit={}, material=additive(),
                    sprite=sprite(F + "glow.png", (150, 150), emissive(lin(1.0, 0.9, 0.65, 0.9), 3.0), z=25),
                    point_light=point_light(lin(1.0, 0.85, 0.6), 1.2, 360, falloff=1.4, shadows=False)))
    # The sea: springs along its surface, a swell, rain chop, floating.
    ents.append(ent("Sea", transform=tr(0, HS_SEA), water_surface={
        "width": HS_WATER_W, "depth": HS_WATER_D, "spacing": 8.0, "tension": 0.018, "damping": 0.02,
        "spread": 0.25, "splash": 0.014, "chop": 22.0, "chop_strength": 1.6,
        "swell_height": 16.0, "swell_length": 520.0, "swell_speed": 70.0,
        "buoyancy": 2.4, "drag": 2.6, "angular_drag": 3.0,
        "color_top": lin(0.26, 0.42, 0.5, 0.86), "color_deep": lin(0.02, 0.05, 0.09, 0.97),
        "foam_color": lin(0.75, 0.85, 0.92, 0.85), "foam_width": 4.0, "z_order": 20}))
    # The pier on the left, on posts, and its lamp.
    ents.append(ent("Pier", transform=tr(-560, HS_PIER_Y),
                    sprite=sprite(E + "hb_planks.png", (480, 30), lin(0.7, 0.66, 0.62), z=12,
                                  fill={"mode": "tile", "tile_size": [256.0, 30.0]}),
                    rigid_body={"body_type": "Static", "mass": 1.0, "gravity_scale": 1.0, "linear_damping": 0.0,
                                "angular_damping": 0.0, "fixed_rotation": True},
                    collider={"shape": {"Box": {"width": 480.0, "height": 30.0}}, "friction": 0.8, "restitution": 0.0}))
    for i, x in enumerate((-760, -620, -480, -340)):
        ents.append(ent(f"Post{i}", transform=tr(x, HS_PIER_Y - 140),
                        sprite=sprite(E + "hb_post.png", (22, 260), lin(0.6, 0.56, 0.52), z=11)))
    ents.append(ent("PierLamp", transform=tr(-420, HS_PIER_Y + 120),
                    point_light=point_light(lin(1.0, 0.72, 0.42)[:3], 1.3, 460, 1.4, 0.0, height=0.4, shadows=False)))
    ents.append(ent("PierLampGlow", transform=tr(-420, HS_PIER_Y + 120), unlit={}, material=additive(),
                    sprite=sprite(F + "glow.png", (130, 130), lin(1.0, 0.7, 0.4, 0.6), z=13)))
    ents.append(ent("PierLampPost", transform=tr(-420, HS_PIER_Y + 62),
                    sprite=sprite(E + "hb_post.png", (7, 110), lin(0.25, 0.24, 0.26), z=11)))
    # Walls off both edges, so nothing floats away.
    for name, x in (("WallW", -1040.0), ("WallE", 1040.0)):
        ents.append(ent(name, transform=tr(x, 0),
                        rigid_body={"body_type": "Static", "mass": 1.0, "gravity_scale": 1.0, "linear_damping": 0.0,
                                    "angular_damping": 0.0, "fixed_rotation": True},
                        collider={"shape": {"Box": {"width": 80.0, "height": 1400.0}}, "friction": 0.5, "restitution": 0.1}))
    # The rock under the headland, solid, so the swell breaks on it.
    ents.append(ent("Rock", transform=tr(620, -140),
                    rigid_body={"body_type": "Static", "mass": 1.0, "gravity_scale": 1.0, "linear_damping": 0.0,
                                "angular_damping": 0.0, "fixed_rotation": True},
                    collider={"shape": {"Box": {"width": 460.0, "height": 170.0}}, "friction": 0.5, "restitution": 0.1}))
    # The boats, moored to the pier by ropes that strain as they ride.
    boats = [("Trawler", "hb_trawler", 180, 110, 160, 44, -29.0, -150, 4.0, (-340, 0.0), (-80, -10), 150.0),
             ("Tug", "hb_tug", 150, 100, 134, 40, -26.0, 160, 4.0, (-340, 0.0), (-60, -10), 420.0),
             ("Dinghy", "hb_dinghy", 100, 50, 90, 20, -13.0, -420, 1.2, (-480, 0.0), (0, -6), 90.0)]
    for name, tex, w, h, cw, ch, dy, x, mass, (px, _), (bx, by), length in boats:
        ents.append(ent(name, transform=tr(x, HS_SEA + 30),
                        sprite=sprite(f"{E}{tex}.png", (w, h), (1, 1, 1, 1), z=16), **hb_body(cw, ch, mass, dy),
                        joint={"target_entity": "Pier", "collide_connected": False, "joint_type": {"Rope": {
                            "anchor_a": [float(bx), float(by)], "anchor_b": [float(px - (-560)), -12.0],
                            "max_distance": length}}}))
        ents.append(ent(f"{name}Rope", transform=tr(px, HS_PIER_Y - 12),
                        mesh={"texture_id": "sprites/env/cb_rope.png", "color": lin(0.85, 0.75, 0.6), "z_order": 15,
                              "vertices": [], "indices": []},
                        rope={"length": length * 0.92, "segments": 12, "width": 5.0, "end": name,
                              "end_offset": [float(bx), float(by)], "gravity": [0.0, -700.0], "wind": [40.0, 0.0],
                              "gust": 0.6, "damping": 2.0, "iterations": 16}))
    # Crates on the pier, which the gusts throw in.
    for i, x in enumerate((-700, -660, -600, -540)):
        ents.append(ent(f"Crate{i}", transform=tr(x, HS_PIER_Y + 36 + (i % 2) * 40),
                        sprite=sprite("sprites/crater/crate.png", (38, 38), (1, 1, 1, 1), z=13), **hb_body(36, 36, 1.0)))
    # Rain, driven slant by the wind; spray where the sea breaks on rock.
    ents.append(ent("Rain", transform=tr(-100, 520), unlit={}, particle_emitter=emitter(
        texture_id=F + "st_drop.png", emission_rate=900.0, max_particles=900, lifetime=[0.55, 0.75],
        speed=[1000.0, 1200.0], angle=[-1.85, -1.75], size_start=[3.0, 4.0], size_end=[3.0, 4.0], stretch=0.03,
        emit_shape={"kind": "rect", "size": [2600.0, 20.0]},
        color_start=lin(0.7, 0.78, 0.9, 0.55), color_end=lin(0.7, 0.78, 0.9, 0.35), blend_mode="Alpha", z_order=40)))
    ents.append(ent("Spray", transform=tr(380, HS_SEA + 10), unlit={}, particle_emitter=emitter(
        texture_id=F + "soft_dot.png", emission_rate=0.0, burst_count=60, max_particles=240, lifetime=[0.5, 1.1],
        speed=[160.0, 460.0], angle=[1.7, 2.7], size_start=[5.0, 11.0], size_end=[2.0, 4.0],
        gravity_modifier=0.9, drag=0.8, color_start=lin(0.85, 0.92, 1.0, 0.85), color_end=lin(0.8, 0.88, 0.95, 0.0),
        blend_mode="Alpha", z_order=27)))
    # Lightning: a jagged bolt (a `line` the script draws), its glow, and the
    # light it throws.
    ents.append(ent("BoltGlow", transform=tr(), unlit={}, line={
        "points": [[0.0, -5000.0], [1.0, -5000.0]], "width": 18.0, "color": emissive(lin(0.6, 0.7, 1.0, 0.5), 3.0),
        "z_order": -85, "blend_mode": "Additive", "joint": "round"}))
    ents.append(ent("Bolt", transform=tr(), unlit={}, line={
        "points": [[0.0, -5000.0], [1.0, -5000.0]], "width": 4.0, "color": emissive(lin(0.9, 0.93, 1.0, 1.0), 9.0),
        "z_order": -84, "blend_mode": "Additive", "joint": "round"}))
    ents.append(ent("Flash", transform=tr(0, 300),
                    point_light=point_light(lin(0.75, 0.82, 1.0), 0.0, 2600, falloff=0.7, shadows=False, height=0.8)))
    ents.append(ent("Weather", transform=tr(), script=script("scripts/s110_harbour_storm.lua")))
    ents += ui_captions("110   Harbour Storm", "the boats ride the sea's own surface   S calm the storm   Tab captions")
    pp = post(
        bloom={"threshold": 1.0, "intensity": 0.55, "blur_size": 0.0},
        vignette={"intensity": 0.55, "smoothness": 0.5, "color": [0.0, 0.01, 0.03, 1.0]},
        grade={"brightness": 1.0, "contrast": 1.08, "saturation": 0.9, "tint": [0.85, 0.92, 1.0, 0.06]},
        chromatic={"strength": 0.0012, "on": False},
        hdr={"tonemap": "aces", "exposure": 1.05})
    return {"name": "110 - Harbour Storm", "post_process": pp, "entities": ents}


def write_harbour_storm_script():
    src = r'''-- 110 Harbour Storm: the sea is a `water_surface` and everything on it
-- floats on its moving surface. This script is the weather: the lighthouse
-- turning, the clouds drifting, lightning now and then (a bolt, a flash,
-- and a splash where it strikes the sea), gusts that throw the pier's
-- crates in (the engine splashes them), spray where the swell breaks on the
-- rock. S calms the storm and lets it rise again.

script = { tick_rate = 60 }

local nav = require("nav")
local SCENE = "scenes/110-harbour-storm.scene"
local SEA = %(sea)f
local PIER_Y = %(pier)f

local e = {}
local t = 0
local rng = 110
local captions = true
local storm = true
local strength = 1.0
local next_bolt = 2.5
local bolt_age = 9
local next_gust = 6
local next_spray = 1.0
local crates = {}

local function rand()
    rng = (rng * 16807) %% 2147483647
    return rng / 2147483647
end
local function between(a, b) return a + (b - a) * rand() end

function init(entity)
    for _, n in ipairs({ "Sea", "Lamp", "LampGlow", "Clouds0", "Clouds1", "Sky", "Bolt", "BoltGlow", "Flash", "Ambient",
                         "Rain", "Spray", "Status" }) do
        e[n] = Entity.find_by_name(n)
    end
    for i = 0, 3 do
        local id = Entity.find_by_name("Crate" .. i)
        local x, y = Transform.get_position(id)
        crates[#crates + 1] = { e = id, x = x, y = y, out = 0 }
    end
end

-- A jagged bolt from the clouds to the sea at x.
local function bolt(x)
    local pts = {}
    local px, py = x + between(-160, 160), 360
    pts[#pts + 1] = { px, py }
    local steps = 11
    for i = 1, steps do
        local f = i / steps
        local ty = 360 + (SEA - 360) * f
        px = px + (x - px) / (steps - i + 1) + between(-34, 34)
        pts[#pts + 1] = { px, ty }
    end
    pts[#pts] = { x, SEA }
    return pts
end

function update(entity, dt)
    nav.tick(SCENE)
    t = t + dt
    if Input.is_key_just_pressed("Tab") then captions = nav.toggle_ui_captions(captions) end
    if Input.is_key_just_pressed("S") then storm = not storm end
    strength = strength + ((storm and 1 or 0) - strength) * math.min(1, dt * 0.4)

    -- The sea gets up and lies down with the storm.
    Water.set(e.Sea, "chop", 4 + 20 * strength)
    Water.set(e.Sea, "swell_height", 5 + 13 * strength)
    Particles.set(e.Rain, "emission_rate", 120 + 800 * strength)

    -- The lighthouse turns, a slow sweep round.
    local a = math.pi + math.sin(t * 0.35) * 1.1 - 0.25
    Transform.set_rotation(e.Lamp, a)

    -- Clouds drift.
    Transform.set_position(e.Clouds0, ((t * 14) %% 400) - 200, 330)
    Transform.set_position(e.Clouds1, ((t * -22) %% 500) - 250, 260)

    -- Lightning: a bolt, the clouds and the sea flashed, a splash where it
    -- strikes - and it fades over a third of a second, with an after-flash.
    next_bolt = next_bolt - dt * strength
    if next_bolt <= 0 then
        local x = between(-700, 300)
        local pts = bolt(x)
        Line.set(e.Bolt, "points", pts)
        Line.set(e.BoltGlow, "points", pts)
        Transform.set_position(e.Flash, x, 200)
        Water.splash(e.Sea, x, -18)
        bolt_age = 0
        next_bolt = between(3.5, 8.0)
    end
    bolt_age = bolt_age + dt
    local flash = 0
    if bolt_age < 0.45 then
        flash = math.max(0, 1 - bolt_age / 0.12) + (bolt_age > 0.18 and bolt_age < 0.26 and 0.7 or 0)
    end
    if bolt_age > 0.35 then
        Line.set(e.Bolt, "points", { { 0, -5000 }, { 1, -5000 } })
        Line.set(e.BoltGlow, "points", { { 0, -5000 }, { 1, -5000 } })
    end
    Lighting.set_intensity(e.Flash, flash * 1.3)
    local c = 0.32 + flash * 0.8
    Sprite.set_color(e.Clouds0, c * 0.95, c, c * 1.25, 0.85)
    Sprite.set_color(e.Clouds1, c * 0.9, c * 0.95, c * 1.2, 0.7)
    local s = 0.45 + flash * 0.7
    Sprite.set_color(e.Sky, s * 0.21, s * 0.24, s * 0.34, 1)

    -- Gusts throw a crate off the pier now and then; it splashes in. Once
    -- every crate is in, they are put back.
    next_gust = next_gust - dt * strength
    if next_gust <= 0 then
        local all_in = true
        for _, c in ipairs(crates) do
            if c.out == 0 then
                all_in = false
                c.out = 1
                Physics.apply_impulse(c.e, between(900, 1500), between(500, 900))
                break
            end
        end
        if all_in then
            for _, c in ipairs(crates) do
                c.out = 0
                Transform.set_position(c.e, c.x, c.y)
                Transform.set_rotation(c.e, 0)
                Physics.set_velocity(c.e, 0, 0)
            end
        end
        next_gust = between(4, 7)
    end

    -- Spray where the swell breaks on the rock.
    next_spray = next_spray - dt
    if next_spray <= 0 then
        Particles.emit_burst(e.Spray, 60)
        Water.splash(e.Sea, 360, 6 * strength)
        next_spray = between(1.2, 2.6) / math.max(0.3, strength)
    end

    UI.set_text(e.Status, storm and "storm" or "calming")
end
''' % {"sea": HS_SEA, "pier": HS_PIER_Y}
    (ASSETS / "scripts" / "s110_harbour_storm.lua").write_text(src, encoding="utf-8", newline="\n")


# ── 111 Arena Boss ──────────────────────────────────────────────────────
# A stone golem in a ruined arena at night, fighting a knight. The golem is
# a skeleton of rock pieces with glowing cracks: it breathes and sways on a
# base clip with an additive breath layer, flinches on a layer when it is
# struck, roars on an override layer, and reaches with its fist by IK. Every
# attack is told first by a shape on the floor that fills (`radial` and
# `bar` sprite fills) - then the fist comes down, or sweeps, or rocks fall,
# and the floor is carved apart where they land. Its health is a bar fill.
# When it falls it goes limp (`ragdoll`) into the craters it made; then the
# arena is set again.

AB_FLOOR = -190.0
AB_G = 1.5                      # the golem's size, against the rig below
AB_GOLEM_X = -430.0
AB_HERO_X = 330.0


def ab_clip_keys():
    """The golem's pose at rest (local rotations), shared by its clips."""
    import math as m
    return {
        "pelvis": m.pi / 2, "torso": 0.0, "head": 0.0,
        "upper_r": -2.97, "fore_r": 0.4, "upper_l": 2.96, "fore_l": 0.35,
        "thigh_r": -2.99, "shin_r": -0.2, "thigh_l": 2.99, "shin_l": 0.1,
    }


def ab_clips():
    import math as m
    rest = ab_clip_keys()
    n = 24

    def cyc(period, f):
        return [(period * i / n,) + f(i / n) for i in range(n + 1)]

    idle_p = 3.2
    idle = aq_clip("gb_idle", idle_p, {
        "pelvis": cyc(idle_p, lambda p: (rest["pelvis"],)),
        "torso": cyc(idle_p, lambda p: (0.05 * m.sin(m.tau * p),)),
        "head": cyc(idle_p, lambda p: (-0.07 * m.sin(m.tau * p + 0.6),)),
        "upper_r": cyc(idle_p, lambda p: (rest["upper_r"] + 0.07 * m.sin(m.tau * p + 1.0),)),
        "fore_r": cyc(idle_p, lambda p: (rest["fore_r"] + 0.05 * m.sin(m.tau * p + 1.4),)),
        "upper_l": cyc(idle_p, lambda p: (rest["upper_l"] - 0.06 * m.sin(m.tau * p + 0.5),)),
        "fore_l": cyc(idle_p, lambda p: (rest["fore_l"] - 0.05 * m.sin(m.tau * p + 0.9),)),
        "thigh_r": cyc(idle_p, lambda p: (rest["thigh_r"],)),
        "shin_r": cyc(idle_p, lambda p: (rest["shin_r"],)),
        "thigh_l": cyc(idle_p, lambda p: (rest["thigh_l"],)),
        "shin_l": cyc(idle_p, lambda p: (rest["shin_l"],)),
    })
    breathe = aq_clip("gb_breathe", 2.6, {
        "torso": cyc(2.6, lambda p: (0.04 * (1 - m.cos(m.tau * p)) / 2,)),
        "head": cyc(2.6, lambda p: (-0.05 * (1 - m.cos(m.tau * p)) / 2,)),
    })
    flinch = aq_clip("gb_flinch", 0.5, {
        "torso": [(0.0, 0.0), (0.07, 0.2), (0.5, 0.0)],
        "head": [(0.0, 0.0), (0.1, 0.25), (0.5, 0.0)],
    })
    roar = aq_clip("gb_roar", 1.5, {
        "torso": [(0.0, 0.0), (0.4, 0.22), (1.1, 0.22), (1.5, 0.0)],
        "head": [(0.0, 0.0), (0.4, 0.35), (1.1, 0.35), (1.5, 0.0)],
        "upper_r": [(0.0, rest["upper_r"]), (0.4, -1.0), (1.1, -0.95), (1.5, rest["upper_r"])],
        "fore_r": [(0.0, rest["fore_r"]), (0.4, 0.7), (1.1, 0.7), (1.5, rest["fore_r"])],
        "upper_l": [(0.0, rest["upper_l"]), (0.4, 1.25), (1.1, 1.2), (1.5, rest["upper_l"])],
        "fore_l": [(0.0, rest["fore_l"]), (0.4, -0.6), (1.1, -0.6), (1.5, rest["fore_l"])],
    })
    return {"animations/gb_idle.skelanim": idle, "animations/gb_breathe.skelanim": breathe,
            "animations/gb_flinch.skelanim": flinch, "animations/gb_roar.skelanim": roar}


def arena_prefabs():
    F = "sprites/fx/"
    hot = lambda c, k: emissive(lin(*c), k)
    return {
        "AbDust": prefab("AbDust", unlit={}, particle_emitter=emitter(
            texture_id=F + "smoke.png", emission_rate=0.0, burst_count=22, max_particles=22, blend_mode="Alpha",
            lifetime=[1.2, 2.4], speed=[60.0, 260.0], angle=[0.2, 2.94], size_start=[40.0, 70.0], size_end=[150.0, 230.0],
            color_curve=[[0.0] + lin(0.5, 0.44, 0.38, 0.6), [1.0] + lin(0.35, 0.32, 0.3, 0.0)], drag=2.0,
            gravity_modifier=-0.05, z_order=40), lifetime={"remaining": 2.6}),
        "AbDebris": prefab("AbDebris", particle_emitter=emitter(
            texture_id=F + "shard.png", emission_rate=0.0, burst_count=34, max_particles=34, blend_mode="Alpha",
            lifetime=[1.2, 2.2], speed=[200.0, 620.0], angle=[0.35, 2.8], size_start=[8.0, 16.0], size_end=[8.0, 14.0],
            color_start=lin(0.55, 0.5, 0.44, 1.0), color_end=lin(0.5, 0.45, 0.4, 0.0), gravity_modifier=1.4,
            angular_velocity=[-12.0, 12.0], collision={"response": "bounce", "bounce": 0.35}, z_order=38),
            lifetime={"remaining": 2.4}),
        "AbSpark": prefab("AbSpark", unlit={}, point_light=point_light(lin(1.0, 0.75, 0.4), 2.2, 220, falloff=1.6, shadows=False),
                          particle_emitter=emitter(
                              texture_id=F + "spark.png", emission_rate=0.0, burst_count=26, max_particles=26,
                              lifetime=[0.15, 0.45], speed=[180.0, 520.0], size_start=[5.0, 9.0], size_end=[1.5, 2.0],
                              color_start=hot((1.0, 0.85, 0.5, 1.0), 6.0), color_end=hot((1.0, 0.45, 0.1, 0.0), 2.0),
                              stretch=0.03, drag=2.0, blend_mode="Additive", z_order=42),
                          lifetime={"remaining": 0.5}),
        "AbFlash": prefab("AbFlash", point_light=point_light(lin(1.0, 0.6, 0.3), 4.0, 520, falloff=1.4, shadows=False),
                          lifetime={"remaining": 0.18}),
        "AbRock": prefab("AbRock",
                         sprite=sprite("sprites/orbital/rock1.png", (56, 56), (1.3, 1.2, 1.1, 1.0), z=30),
                         material={"material_id": "lit_sprite", "normal_map_id": "sprites/orbital/rock1_n.png"},
                         rigid_body={"body_type": "Dynamic", "mass": 3.0, "gravity_scale": 1.0, "linear_damping": 0.0,
                                     "angular_damping": 0.3, "fixed_rotation": False, "ccd": True},
                         collider={"shape": {"Circle": {"radius": 24.0}}, "friction": 0.8, "restitution": 0.15},
                         lifetime={"remaining": 7.0}),
    }


def ab_golem():
    """The golem, facing right: a root at the hip, every bone carrying its
    rock piece (lit, normal-mapped) and that piece's glowing cracks."""
    A = "sprites/arena/"
    G = AB_G
    rest = ab_clip_keys()
    hip = AB_FLOOR + (72 + 78) * G - 6
    root = ent("Golem", transform=tr(AB_GOLEM_X, hip), skeleton_root={"name": "golem"},
               skeletal_player={"clip": "animations/gb_idle.skelanim", "layers": [
                   {"name": "breath", "clip": "animations/gb_breathe.skelanim", "mode": "additive", "mask": ["torso"],
                    "weight": 0.6, "loop": True},
                   {"name": "roar", "clip": "", "mask": ["torso"], "weight": 0.0},
                   {"name": "flinch", "clip": "", "mode": "additive", "mask": ["torso"], "weight": 0.0},
               ]},
               ragdoll={"active": False, "thickness": 30.0, "limit": 1.2, "density": 0.0015, "friction": 0.9,
                        "damping": 0.4})
    out = [root]

    def bone(name, parent, at, length, piece, size, z, glow=1.0, tint=(1, 1, 1, 1)):
        ent_name = "Golem" + name.title().replace("_", "")
        comps = {
            "transform": tr(at * G, 0.0, rest[name]),
            "bone": {"name": name, "length": float(length * G)},
            "sprite": sprite(f"{A}{piece}.png", (size[0] * G, size[1] * G), tint, z=z * 2, anchor=(0.06, 0.5)),
            "material": {"material_id": "lit_sprite", "normal_map_id": f"{A}{piece}_n.png"},
        }
        out.append({"name": ent_name, "parent": parent, "components": comps})
        out.append({"name": ent_name + "Glow", "parent": ent_name, "components": {
            "transform": tr(), "unlit": {}, "material": additive(),
            "sprite": sprite(f"{A}{piece}_glow.png", (size[0] * G, size[1] * G),
                             emissive(lin(1.0, 0.45, 0.12, glow * 0.85), 2.0), z=z * 2 + 1, anchor=(0.06, 0.5))}})
        return ent_name

    far = (0.7, 0.68, 0.72, 1.0)
    pelvis = bone("pelvis", "Golem", 0, 40, "pelvis", (70, 96), 4)
    torso = bone("torso", pelvis, 40, 118, "torso", (150, 132), 5)
    head = bone("head", torso, 122, 60, "head", (76, 70), 6)
    up_l = bone("upper_l", torso, 104, 90, "upper", (104, 50), 2, 0.7, far)
    bone("fore_l", up_l, 90, 104, "fore", (116, 62), 2, 0.7, far)
    up_r = bone("upper_r", torso, 104, 90, "upper", (104, 50), 8)
    fore_r = bone("fore_r", up_r, 90, 104, "fore", (116, 62), 8)
    th_l = bone("thigh_l", pelvis, 0, 72, "thigh", (84, 52), 1, 0.6, far)
    bone("shin_l", th_l, 72, 78, "shin", (90, 58), 1, 0.6, far)
    th_r = bone("thigh_r", pelvis, 0, 72, "thigh", (84, 52), 7)
    bone("shin_r", th_r, 72, 78, "shin", (90, 58), 7)
    # The fist reaches by IK: off until an attack turns it up.
    for e in out:
        if e["name"] == fore_r:
            e["components"]["ik_chain"] = {"target": [0.0, AB_FLOOR], "bones": 2, "iterations": 12, "tolerance": 0.5,
                                           "max_bend": 2.6, "weight": 0.0}
    # Its eyes: a slit of light on the head's front, and the light it gives.
    out.append({"name": "GolemEyes", "parent": head, "components": {
        "transform": tr(36 * G, -16 * G), "unlit": {}, "material": additive(),
        "sprite": sprite("sprites/fx/soft_dot.png", (16 * G, 30 * G), emissive(lin(1.0, 0.55, 0.15), 6.0), z=14),
        "point_light": point_light(lin(1.0, 0.55, 0.2), 1.2, 260, falloff=1.4, shadows=False)}})
    return out


def arena_boss():
    A = "sprites/arena/"
    F = "sprites/fx/"
    cam = camera()
    cam["components"]["camera"]["zoom"] = 0.8
    cam["components"]["transform"] = tr(0, 50)
    ents = [cam]
    ents.append(ent("Ambient", transform=tr(), ambient_light={"color": lin(0.45, 0.5, 0.8)[:3], "intensity": 0.32}))
    ents.append(ent("Moon", transform=tr(0, 0, rot=-2.4), directional_light={
        "color": lin(0.6, 0.7, 1.0)[:3], "intensity": 0.35, "height": 0.6, "softness": 10.0}))
    ents.append(ent("Sky", transform=tr(0, 120), unlit={},
                    sprite=sprite("sprites/siege/sky.png", (2100, 1300), lin(0.28, 0.3, 0.45), z=-100)))
    ents.append(ent("Colonnade", transform=tr(0, AB_FLOOR + 150), unlit={},
                    sprite=sprite(A + "colonnade.png", (2100, 620), lin(0.2, 0.21, 0.3, 0.75), z=-80)))
    # The floor, which the fight carves apart.
    ents.append(ent("Floor", transform=tr(0, AB_FLOOR - 130),
                    sprite=sprite(A + "floor.png", (1920, 260), (1, 1, 1, 1), z=-10),
                    carvable={"alpha_cutoff": 0.5, "collider": True, "collider_step": 4, "scorch": 12.0,
                              "scorch_color": [0.22, 0.17, 0.13, 1.0], "friction": 0.9}))
    # Braziers on the edges and their fire.
    for i, x in enumerate((-820.0, 820.0, 60.0)):
        y = AB_FLOOR + (0 if i < 2 else 330)
        if i == 2:
            continue
        ents.append(ent(f"Brazier{i}", transform=tr(x, y + 30),
                        sprite=sprite("sprites/crater/barrel.png", (46, 60), lin(0.4, 0.35, 0.3), z=0)))
        ents.append(ent(f"Fire{i}", transform=tr(x, y + 66), unlit={}, particle_emitter=emitter(
            texture_id=F + "flame.png", emission_rate=40.0, max_particles=70, lifetime=[0.4, 0.8], speed=[30.0, 80.0],
            angle=[1.3, 1.85], size_start=[30.0, 44.0], size_end=[8.0, 12.0], blend_mode="Additive",
            color_curve=[[0.0] + emissive(lin(1.0, 0.85, 0.5, 0.0), 4.0), [0.15] + emissive(lin(1.0, 0.7, 0.3, 1.0), 4.0),
                         [0.6] + emissive(lin(1.0, 0.35, 0.08, 0.7), 2.5), [1.0, 0.3, 0.06, 0.02, 0.0]],
            turbulence={"strength": 50.0, "scale": 60.0, "speed": 1.2}, z_order=2),
                        point_light=point_light(lin(1.0, 0.6, 0.3), 1.8, 600, falloff=1.3, softness=4.0)))
    ents += ab_golem()
    ents += sg_knight("Hero", AB_HERO_X, AB_FLOOR, "blue")
    # The warnings: a disc that fills before a slam, a bar along the floor
    # before a sweep, and three discs before the rocks.
    tell = lambda name, fill, size, x=0.0: ent(name, transform=tr(x, -5000), unlit={}, material=additive(),
                                               sprite={**sprite(F + "soft_dot.png", size, emissive(lin(1.0, 0.3, 0.1, 0.6), 2.0), z=20),
                                                       "fill": fill})
    ents.append(tell("SlamTell", {"mode": "radial", "amount": 0.0}, (240, 70)))
    ents.append(ent("SlamRing", transform=tr(0, -5000), unlit={}, material=additive(),
                    sprite=sprite(F + "ring.png", (300, 88), emissive(lin(1.0, 0.35, 0.12, 0.8), 2.0), z=21)))
    ents.append(ent("SweepTell", transform=tr(0, -5000), unlit={}, material=additive(),
                    sprite={**sprite("__white", (720, 26), emissive(lin(1.0, 0.3, 0.1, 0.45), 1.8), z=20, anchor=(0.0, 0.5)),
                            "fill": {"mode": "bar", "amount": 0.0, "from": "left"}}))
    for i in range(3):
        ents.append(tell(f"RainTell{i}", {"mode": "radial", "amount": 0.0}, (130, 40)))
    # The golem's health: a bar fill under its name.
    ents.append(ent("BossName", transform=tr(0, 438), unlit={},
                    text=text("THE STONE WARDEN", 1.5, lin(0.95, 0.85, 0.7), z=60, align="center")))
    ents.append(ent("BossBarBack", transform=tr(0, 410), unlit={},
                    sprite=sprite("__white", (620, 20), lin(0.08, 0.06, 0.06, 0.85), z=60)))
    ents.append(ent("BossBar", transform=tr(-306, 410), unlit={},
                    sprite={**sprite("__white", (612, 12), emissive(lin(1.0, 0.35, 0.12), 1.6), z=61, anchor=(0.0, 0.5)),
                            "fill": {"mode": "bar", "amount": 1.0, "from": "left"}}))
    ents.append(ent("Referee", transform=tr(), script=script("scripts/s111_arena_boss.lua")))
    ents += ui_captions("111   Arena Boss", "every attack is told by a shape that fills   Tab captions")
    pp = post(
        bloom={"threshold": 1.0, "intensity": 0.55, "blur_size": 0.0},
        vignette={"intensity": 0.5, "smoothness": 0.5, "color": [0.02, 0.0, 0.0, 1.0]},
        grade={"brightness": 1.0, "contrast": 1.08, "saturation": 1.05, "tint": [1.0, 0.93, 0.85, 0.05]},
        chromatic={"strength": 0.0015, "on": True},
        hdr={"tonemap": "aces", "exposure": 1.05})
    return {"name": "111 - Arena Boss", "post_process": pp, "entities": ents, "audio_refs": []}


def write_arena_boss_script():
    src = r'''-- 111 Arena Boss: a stone golem against a knight. The golem's body is the
-- engine's - a base clip, a breath layer, a flinch and a roar on layers, its
-- fist reaching by IK, a ragdoll when it falls; the fight is this script:
-- which attack, when, where. Every attack is told first by a shape on the
-- floor that fills (radial and bar sprite fills), and where it lands the
-- floor is carved. When its health bar is empty it goes limp, and after a
-- while the arena is set again.

script = { tick_rate = 60 }

local nav = require("nav")
local SCENE = "scenes/111-arena-boss.scene"
local FLOOR = %(floor)f
local GX = %(gx)f

local e = {}
local t = 0
local rng = 111
local captions = true
local hp = 1.0
local state = "idle"
local st = 0
local next_attack = 2.5
local attack_i = 0
local slam_x = 0
local rain = {}
local rocks = {}
local glow = 1.0
local hero = { x = %(hx)f, y = FLOOR, vx = 0, jump = 0, cool = 1.0, swing = 0, goal = 0 }
local dead_for = 0

local function rand()
    rng = (rng * 16807) %% 2147483647
    return rng / 2147483647
end
local function between(a, b) return a + (b - a) * rand() end
local function spawn(name, x, y)
    local h = Entity.spawn_prefab(name)
    Transform.set_position(h, x, y)
    return h
end
local function park(id) Transform.set_position(id, 0, -5000) end

local function impact(x, size)
    Sprite.carve(e.Floor, x, FLOOR, size)
    spawn("AbDust", x, FLOOR + 10)
    spawn("AbDebris", x, FLOOR + 14)
    spawn("AbFlash", x, FLOOR + 40)
    Camera.shake(size * 0.12, 0.35, 22)
end

function init(entity)
    for _, n in ipairs({ "Golem", "GolemForeR", "GolemTorso", "GolemEyes", "Floor", "SlamTell", "SlamRing", "SweepTell",
                         "BossBar", "Hero", "HeroThighL", "HeroThighR", "HeroShinL", "HeroShinR", "HeroArmR", "HeroForeR",
                         "HeroArmL", "Status" }) do
        e[n] = Entity.find_by_name(n)
    end
    for i = 0, 2 do rain[i + 1] = { e = Entity.find_by_name("RainTell" .. i), x = 0 } end
    e.glows = {}
    for _, n in ipairs({ "Pelvis", "Torso", "Head", "UpperL", "ForeL", "UpperR", "ForeR", "ThighL", "ShinL", "ThighR", "ShinR" }) do
        e.glows[#e.glows + 1] = Entity.find_by_name("Golem" .. n .. "Glow")
    end
end

-- The hand's reach: where it is held up before a blow, and where it lands.
local function reach(x, y, w)
    Skeleton.set_ik_target(e.GolemForeR, x, y)
    Skeleton.set_ik_weight(e.GolemForeR, w)
end

local function hit_golem()
    hp = math.max(0, hp - 0.06)
    glow = 2.2
    spawn("AbSpark", GX + 120, FLOOR + 260 + between(-40, 60))
    Animation.play_layer(e.Golem, "flinch", "animations/gb_flinch.skelanim", 0.05, false)
    Sprite.set_fill(e.BossBar, hp)
end

local function pose_hero(dt)
    -- Walking legs while moving, a thrust of the spear when attacking, a
    -- hop over a sweep.
    local moving = math.abs(hero.vx) > 5
    local p = t * 9
    local swing = moving and 0.35 * math.sin(p) or 0
    Transform.set_rotation(e.HeroThighL, -math.pi + 0.1 + swing)
    Transform.set_rotation(e.HeroThighR, math.pi - 0.14 - swing)
    Transform.set_rotation(e.HeroShinL, 0.04 + (moving and math.max(0, -math.sin(p)) * 0.5 or 0))
    Transform.set_rotation(e.HeroShinR, -0.06 - (moving and math.max(0, math.sin(p)) * 0.5 or 0))
    local thrust = hero.swing > 0 and math.sin((1 - hero.swing / 0.35) * math.pi) or 0
    Transform.set_rotation(e.HeroArmR, 2.9 - 0.7 * thrust)
    Transform.set_rotation(e.HeroForeR, -1.6 + 1.3 * thrust)
    local hy = FLOOR + 98 + hero.jump
    Transform.set_position(e.Hero, hero.x, hy)
end

local function tell_disc(id, x, amount)
    Transform.set_position(id, x, FLOOR + 6)
    Sprite.set_fill(id, amount)
end

function update(entity, dt)
    nav.tick(SCENE)
    t = t + dt
    if Input.is_key_just_pressed("Tab") then captions = nav.toggle_ui_captions(captions) end
    st = st + dt

    -- The cracks glow brighter when struck, and fade back.
    glow = glow + (1 - glow) * math.min(1, dt * 3)
    local k = (state == "dead") and math.max(0, 1 - dead_for / 2) or glow
    for _, g in ipairs(e.glows) do Sprite.set_color(g, 2.0 * k, 0.9 * k, 0.24 * k, 0.85) end
    Lighting.set_intensity(e.GolemEyes, 1.2 * k)
    Sprite.set_color(e.GolemEyes, 6 * k, 3.3 * k, 0.9 * k, 1)

    -- The knight: closes in and thrusts when nothing is coming, keeps clear
    -- of every warning, hops the sweep.
    hero.cool = hero.cool - dt
    hero.swing = math.max(0, hero.swing - dt)
    local goal = GX + 250
    if state == "slam_tell" or state == "slam" then goal = slam_x + 300 end
    if state == "rain" or state == "rain_tell" then
        goal = GX + 420
        for _, r in ipairs(rain) do
            if math.abs(goal - r.x) < 110 then goal = r.x + 150 end
        end
    end
    if state == "dead" then goal = GX + 360 end
    local dx = goal - hero.x
    hero.vx = math.max(-420, math.min(420, dx * 5))
    hero.x = hero.x + hero.vx * dt
    if state == "idle" and math.abs(dx) < 40 and hero.cool <= 0 then
        hero.swing = 0.35
        hero.cool = between(0.45, 0.7)
    end
    if hero.swing > 0 and hero.swing - dt <= 0.17 and hero.swing > 0.17 then hit_golem() end
    if state == "sweep" then
        hero.jump = math.max(0, math.sin(math.min(1, st / 0.7) * math.pi) * 150)
    else
        hero.jump = math.max(0, hero.jump - dt * 400)
    end
    pose_hero(dt)

    if state == "dead" then
        dead_for = dead_for + dt
        if dead_for > 7 then Scene.load(SCENE) end
        UI.set_text(e.Status, "the warden falls")
        return
    end
    if hp <= 0 then
        state = "dead"
        reach(GX + 200, FLOOR, 0)
        Ragdoll.set(e.Golem, "active", true)
        spawn("AbDust", GX, FLOOR + 40)
        Camera.shake(6, 0.6, 18)
        park(e.SlamTell); park(e.SlamRing); park(e.SweepTell)
        for _, r in ipairs(rain) do park(r.e) end
        return
    end

    if state == "idle" then
        reach(GX + 200, FLOOR + 100, 0)
        next_attack = next_attack - dt
        if next_attack <= 0 then
            attack_i = attack_i + 1
            local kind = ({ "slam", "sweep", "slam", "rain" })[(attack_i - 1) %% 4 + 1]
            st = 0
            if kind == "slam" then
                slam_x = math.max(GX + 180, math.min(GX + 420, hero.x - 20))
                state = "slam_tell"
            elseif kind == "sweep" then
                state = "sweep_tell"
                Transform.set_position(e.SweepTell, GX + 80, FLOOR + 8)
            else
                state = "rain_tell"
                Animation.play_layer(e.Golem, "roar", "animations/gb_roar.skelanim", 0.2, false)
                for i, r in ipairs(rain) do r.x = GX + 260 + i * 170 + between(-40, 40) end
            end
        end
    elseif state == "slam_tell" then
        -- The fist rises over the spot while the warning fills.
        local p = math.min(1, st / 1.3)
        tell_disc(e.SlamTell, slam_x, p)
        Transform.set_position(e.SlamRing, slam_x, FLOOR + 6)
        reach(slam_x - 30, FLOOR + 280 + 60 * p, math.min(1, st * 3))
        if st >= 1.3 then state = "slam"; st = 0 end
    elseif state == "slam" then
        reach(slam_x, FLOOR - 10, 1)
        if st >= 0.12 and st - dt < 0.12 then
            impact(slam_x, 70)
            park(e.SlamTell)
            park(e.SlamRing)
        end
        if st >= 0.9 then state = "idle"; next_attack = between(2.6, 3.4) end
    elseif state == "sweep_tell" then
        local p = math.min(1, st / 1.4)
        Sprite.set_fill(e.SweepTell, p)
        reach(GX + 160, FLOOR + 160, math.min(1, st * 3))
        if st >= 1.4 then state = "sweep"; st = 0 end
    elseif state == "sweep" then
        -- The fist drags along the floor, cutting a trench.
        local p = math.min(1, st / 0.7)
        local x = GX + 170 + p * 560
        reach(x, FLOOR - 6, 1)
        if math.floor(st * 30) ~= math.floor((st - dt) * 30) then Sprite.carve(e.Floor, x, FLOOR, 26) end
        if st >= 0.7 then
            Sprite.set_fill(e.SweepTell, 0)
            park(e.SweepTell)
            spawn("AbDust", x, FLOOR + 10)
            state = "idle"; next_attack = between(2.6, 3.4)
        end
    elseif state == "rain_tell" then
        local p = math.min(1, st / 1.4)
        for _, r in ipairs(rain) do tell_disc(r.e, r.x, p) end
        if st >= 1.4 then
            for _, r in ipairs(rain) do
                rocks[#rocks + 1] = { e = spawn("AbRock", r.x, 560), x = r.x, done = false }
            end
            state = "rain"; st = 0
        end
    elseif state == "rain" then
        for _, rk in ipairs(rocks) do
            if not rk.done then
                local x, y = Transform.get_position(rk.e)
                if y and y <= FLOOR + 40 then
                    rk.done = true
                    impact(rk.x, 46)
                end
            end
        end
        if st >= 1.6 then
            for _, r in ipairs(rain) do park(r.e) end
            rocks = {}
            state = "idle"; next_attack = between(2.6, 3.4)
        end
    end
    UI.set_text(e.Status, string.format("warden %%d%%%%", math.floor(hp * 100 + 0.5)))
end
''' % {"floor": AB_FLOOR, "gx": AB_GOLEM_X, "hx": AB_HERO_X}
    (ASSETS / "scripts" / "s111_arena_boss.lua").write_text(src, encoding="utf-8", newline="\n")
    for path, doc in ab_clips().items():
        (ASSETS / path).write_text(json.dumps(doc, indent=1) + "\n", encoding="utf-8", newline="\n")


# ── 112 Haunted Manor ───────────────────────────────────────────────────
# A torch-lit walk through a manor, side on, streamed in room by room: each
# room is a scene of its own (scenes/manor/), with its own wall, lights,
# ghosts and a `post_volume` - so the grade turns as the walker crosses from
# one room into the next, with no script. The walker's script streams the
# rooms ahead in and drops the ones behind, and crossfades the music to each
# room's own. The ghosts take light away: each carries a subtractive light.

HM_W = 1280.0
HM_ROOMS = [
    # name, wall, music, grade (brightness, contrast, saturation, tint), vignette
    ("The Entrance Hall", "hall", "sounds/manor_hall.wav", (1.0, 1.08, 1.05, [1.0, 0.75, 0.45, 0.12]), 0.5),
    ("The Library", "library", "sounds/manor_library.wav", (0.95, 1.1, 0.75, [0.7, 0.85, 0.5, 0.14]), 0.6),
    ("The Ballroom", "ballroom", "sounds/manor_ballroom.wav", (1.0, 1.05, 0.6, [0.55, 0.7, 1.0, 0.2]), 0.55),
    ("The Chapel", "chapel", "sounds/manor_chapel.wav", (0.9, 1.15, 0.5, [0.75, 0.55, 1.0, 0.18]), 0.75),
]


def hm_ghost(name, x, y, scale=1.0):
    return ent(name, transform=tr(x, y), unlit={},
               sprite=sprite("sprites/manor/ghost.png", (120 * scale, 220 * scale), (0.85, 0.95, 1.1, 0.55), z=-20),
               point_light={**point_light(lin(1.0, 1.0, 1.0), 0.9, 300, falloff=1.3, shadows=False), "subtract": True},
               script=script("scripts/s112_ghost.lua"))


def hm_candle(name, x, y, k=1.0, col=(1.0, 0.62, 0.3)):
    return ent(name, transform=tr(x, y), unlit={},
               point_light=point_light(lin(*col), 1.4 * k, 480 * k, falloff=1.5, shadows=False),
               particle_emitter=emitter(texture_id="sprites/fx/soft_dot.png", emission_rate=30.0, max_particles=40,
                                        lifetime=[0.25, 0.5], speed=[15.0, 35.0], angle=[1.4, 1.75],
                                        size_start=[10.0 * k, 14.0 * k], size_end=[2.0, 3.0],
                                        color_start=emissive(lin(1.0, 0.75, 0.35, 1.0), 3.0),
                                        color_end=list(lin(1.0, 0.3, 0.1, 0.0)), z_order=-28, blend_mode="Additive"),
               script=script("scripts/s86_torch.lua"))


def hm_room(k):
    name, wall, music, (bright, contrast, sat, tint), vig = HM_ROOMS[k]
    C = "sprites/manor/"
    F = "sprites/fx/"
    ents = []
    w = bumpy("Wall", C + f"{wall}.png", (HM_W, 720), (0, 40), -50)[0]
    ents.append(w)
    fl = bumpy("Floor", C + "floor.png", (HM_W, 140), (0, -310), -40, tile=(256, 70))[0]
    fl["components"]["material"].update({"specular": 0.5, "shininess": 30.0})
    ents.append(fl)
    ents.append(ent("Name", transform=tr(0, -262), unlit={}, text={
        "text": name.upper(), "font_id": "", "font_scale": 0.95, "color": list(lin(0.85, 0.72, 0.45)),
        "z_order": -30, "align": "center"}))
    # The room's look: its grade and its vignette, which the camera takes on
    # as it comes in.
    ents.append(ent("Look", transform=tr(0, 0), post_volume={
        "size": [HM_W - 300, 1000.0], "blend": 300.0, "weight": 1.0, "priority": 0,
        "effects": [
            {"name": "color_grade", "params": {"brightness": {"Float": bright}, "contrast": {"Float": contrast},
                                               "saturation": {"Float": sat}, "tint_color": {"Vec4": tint}}},
            {"name": "vignette", "params": {"intensity": {"Float": vig}}},
        ]}))
    if wall == "hall":
        for i, x in enumerate((-440.0, 0.0, 440.0)):
            ents.append(hm_candle(f"Candle{i}", x, 30, 1.0))
        ents.append(hm_ghost("Ghost0", 220, -80))
    elif wall == "library":
        ents.append(hm_candle("Lamp", -200, -150, 1.2, (0.7, 1.0, 0.55)))
        ents.append(ent("Dust", transform=tr(0, 0), unlit={}, particle_emitter=emitter(
            texture_id=F + "soft_dot.png", emission_rate=12.0, max_particles=120, lifetime=[6.0, 9.0],
            speed=[4.0, 14.0], size_start=[2.0, 4.0], size_end=[2.0, 4.0],
            emit_shape={"kind": "rect", "size": [HM_W, 600.0]},
            color_start=[0.9, 0.85, 0.6, 0.0], color_curve=[[0.0, 0.9, 0.85, 0.6, 0.0], [0.5, 0.9, 0.85, 0.6, 0.5],
                                                             [1.0, 0.9, 0.85, 0.6, 0.0]],
            turbulence={"strength": 10.0, "scale": 200.0, "speed": 0.2}, z_order=-25, blend_mode="Additive")))
        ents.append(hm_ghost("Ghost0", -380, 40, 0.9))
        ents.append(hm_ghost("Ghost1", 380, -60))
    elif wall == "ballroom":
        for i, cx in enumerate((-420.0, 0.0, 420.0)):
            ents.append(ent(f"Moon{i}", transform=tr(cx, -40, rot=-0.25), unlit={}, material=additive(),
                            sprite=sprite(F + "shaft.png", (260, 760), lin(0.5, 0.65, 1.0, 0.25), z=-30)))
            ents.append(ent(f"MoonLight{i}", transform=tr(cx + 60, -260),
                            point_light=point_light(lin(0.55, 0.7, 1.0), 0.8, 320, falloff=1.2, shadows=False)))
        ents.append(hm_candle("Chandelier", 0, 300, 1.6))
        ents.append(hm_ghost("Ghost0", -120, -120))
        ents.append(hm_ghost("Ghost1", 120, -120))
    else:
        ents.append(ent("Rose", transform=tr(0, 40 + 360 - 260), unlit={}, material=additive(),
                        sprite=sprite(C + "rose.png", (300, 300), emissive(lin(1.0, 1.0, 1.0, 0.8), 1.8), z=-45),
                        point_light=point_light(lin(0.9, 0.5, 1.0), 1.0, 600, falloff=1.2, shadows=False)))
        for i, x in enumerate((-90.0, -30.0, 30.0, 90.0)):
            ents.append(hm_candle(f"Candle{i}", x, -200, 0.6))
        ents.append(hm_ghost("Ghost0", -400, -40, 1.2))
    return {"name": f"Manor - {name}", "entities": ents}


def write_manor_rooms():
    d = ASSETS / "scenes" / "manor"
    d.mkdir(parents=True, exist_ok=True)
    for k in range(len(HM_ROOMS)):
        (d / f"room_{k}.scene").write_text(json.dumps(hm_room(k), indent=1) + "\n", encoding="utf-8")
    (ASSETS / "scripts" / "s112_ghost.lua").write_text("""-- 112 Haunted Manor: a ghost that came in with its room's scene. It drifts
-- and bobs, fades in and out, and backs away from the walker's torch - and
-- the light it carries is subtractive (`subtract` on its point light), so
-- where it floats the room goes darker. Generated by tools/gen_scenes.py.

script = { tick_rate = 60 }

local ghosts = {}
local walker = nil

function init(entity)
    local x, y = Transform.get_position(entity)
    ghosts[entity] = { x = x, y = y, hx = x, t = (x or 0) * 0.01 }
end

function update(entity, dt)
    local g = ghosts[entity]
    if not g then return end
    g.t = g.t + dt
    if not walker then walker = Entity.find_by_name("Walker") end
    local wx = walker and Transform.get_position(walker) or -1e9
    local away = 0
    if math.abs(wx - g.x) < 260 then away = (g.x > wx) and 1 or -1 end
    g.x = g.x + (g.hx + math.sin(g.t * 0.4) * 160 - g.x) * math.min(1, dt * 0.8) + away * 90 * dt
    g.hx = g.hx + away * 40 * dt
    local y = g.y + math.sin(g.t * 1.3) * 18
    Transform.set_position(entity, g.x, y)
    local a = 0.35 + 0.25 * math.sin(g.t * 0.7)
    Sprite.set_color(entity, 0.85, 0.95, 1.1, a)
    Lighting.set_intensity(entity, 0.6 + a)
end
""", encoding="utf-8", newline="\n")


def haunted_manor():
    C = "sprites/corridor/"
    F = "sprites/fx/"
    ents = [camera()]
    ents.append(ent("Ambient", transform=tr(), ambient_light={"color": lin(0.5, 0.5, 0.7)[:3], "intensity": 0.16}))
    ents.append(ent("Walker", transform=tr(0, -240), sprite=sprite(C + "walker.png", (96, 160), (1, 1, 1, 1), z=10,
                                                                     anchor=(0.5, 0.0))))
    ents.append({"name": "Torch", "parent": "Walker", "components": {
        "transform": tr(40, 120), "unlit": {},
        "point_light": point_light(lin(1.0, 0.65, 0.32), 1.8, 560, falloff=1.4, shadows=False),
        "particle_emitter": emitter(texture_id=F + "flame.png", emission_rate=36.0, max_particles=50,
                                    lifetime=[0.25, 0.5], speed=[20.0, 50.0], angle=[1.3, 1.85],
                                    size_start=[16.0, 22.0], size_end=[4.0, 6.0], blend_mode="Additive",
                                    color_curve=[[0.0] + emissive(lin(1.0, 0.85, 0.5, 0.0), 3.0),
                                                 [0.2] + emissive(lin(1.0, 0.7, 0.3, 1.0), 3.0),
                                                 [1.0, 0.3, 0.06, 0.02, 0.0]], z_order=12)}})
    ents.append(ent("Driver", transform=tr(), script=script("scripts/s112_haunted_manor.lua")))
    ents += ui_captions("112   Haunted Manor", "each room streams in with its own grade and music   Space hurry   Tab captions")
    pp = post(
        bloom={"threshold": 1.0, "intensity": 0.5, "blur_size": 0.0},
        vignette={"intensity": 0.5, "smoothness": 0.5, "color": [0.0, 0.0, 0.02, 1.0]},
        grade={"brightness": 1.0, "contrast": 1.05, "saturation": 1.0, "tint": [1.0, 1.0, 1.0, 0.0]},
        chromatic={"strength": 0.0015, "on": False},
        hdr={"tonemap": "aces", "exposure": 1.05})
    pp["effects"].append({"name": "film_grain", "enabled": True, "params": {"intensity": {"Float": 0.05}, "size": {"Float": 1.3}}})
    return {"name": "112 - Haunted Manor", "post_process": pp, "entities": ents,
            "audio_refs": [r[2] for r in HM_ROOMS]}


def write_haunted_manor_script():
    src = """-- 112 Haunted Manor: the walker crosses the manor room by room. Only the
-- room it is in and one either side exist: each is a scene of its own
-- (scenes/manor/), streamed in ahead (Scene.load_additive) and dropped
-- behind (Scene.unload) - with its lights, its ghosts and a `post_volume`
-- that turns the grade as the walker comes in. Entering a room crossfades
-- the music to that room's. Generated by tools/gen_scenes.py.

script = { tick_rate = 60 }

local nav = require("nav")
local SCENE = "scenes/112-haunted-manor.scene"
local W = %s
local ROOMS = %d
local NAMES = { %s }
local MUSIC = { %s }
local captions = true
local walker, camera, status, torch
local x, t = 0, 0
local loaded = {}
local playing = -1

local function room(k)
    return "scenes/manor/room_" .. (k %% ROOMS) .. ".scene"
end

function init(entity)
    walker = Entity.find_by_name("Walker")
    camera = Entity.find_by_name("Camera")
    status = Entity.find_by_name("Status")
    torch = Entity.find_by_name("Torch")
end

function update(entity, dt)
    nav.tick(SCENE)
    if Input.is_key_just_pressed("Tab") then captions = nav.toggle_ui_captions(captions) end
    local speed = Input.is_key_pressed("Space") and 520 or 150
    t = t + dt
    x = x + speed * dt
    local bob = math.abs(math.sin(t * speed * 0.045)) * 6
    Transform.set_position(walker, x, -240 + bob)
    Transform.set_position(camera, x + 160, 0)
    Lighting.set_intensity(torch, 1.7 + 0.25 * math.sin(t * 11.3) + 0.12 * math.sin(t * 17.9))
    -- The room the walker is in, and one either side.
    local r = math.floor((x + W / 2) / W)
    for k = math.max(0, r - 1), r + 1 do
        if not loaded[k] then loaded[k] = Scene.load_additive(room(k), k * W, 0) end
    end
    for k, h in pairs(loaded) do
        if k < r - 1 or k > r + 1 then
            Scene.unload(h)
            loaded[k] = nil
        end
    end
    -- Each room its own music, crossfaded on the way in.
    local here = r %% ROOMS
    if here ~= playing then
        playing = here
        Audio.crossfade_music(MUSIC[here + 1], 2.5, 0.7, true)
    end
    UI.set_text(status, NAMES[here + 1])
end
""" % (HM_W, len(HM_ROOMS), ", ".join('"%s"' % r[0] for r in HM_ROOMS), ", ".join('"%s"' % r[2] for r in HM_ROOMS))
    (ASSETS / "scripts" / "s112_haunted_manor.lua").write_text(src, encoding="utf-8", newline="\n")
    write_manor_rooms()


# ── 113 Falling Sands ───────────────────────────────────────────────────
# A cave in cross-section, every grain its own: one `pixel_sim` seeded from
# a picture of the cave (`maps/cave_seed.png`) - stone, a ledge of sand, a
# wooden bridge over a pool, a pocket of oil, a pool of lava. Sand pours
# from one crack in the ceiling and water from another; now and then a
# spark lights the oil, which burns to smoke along its shelf, and a lava
# bomb drops onto the bridge, setting it alight and boiling the pool below
# to steam where it lands. Crates fall onto the dunes and ride them down -
# the grid is solid where it is stone, wood or resting sand. After a while
# the cave is set again.

FS_W, FS_H = 1600.0, 900.0
FS_CELLS = (480, 270)


def fs_local(cx, cy):
    """A cell of the seed picture as a point in the cave's local space."""
    return (round((cx / FS_CELLS[0] - 0.5) * FS_W, 1), round((0.5 - cy / FS_CELLS[1]) * FS_H, 1))


def falling_sands():
    S = "sprites/sands/"
    F = "sprites/fx/"
    cam = camera()
    cam["components"]["camera"]["zoom"] = 0.8
    ents = [cam]
    ents.append(ent("Ambient", transform=tr(), ambient_light={"color": lin(0.6, 0.6, 0.75)[:3], "intensity": 0.75}))
    ents += bumpy("BackWall", S + "backwall.png", (1700, 960), (0, 0), -50)
    sand_at = fs_local(90, 10)
    water_at = fs_local(250, 10)
    ents.append(ent("Cave", transform=tr(0, 0),
                    sprite=sprite("", (FS_W, FS_H), (1, 1, 1, 1), z=0),
                    pixel_sim={"cells": list(FS_CELLS), "steps_per_second": 60.0, "seed_texture": "maps/cave_seed.png",
                               "sources": [
                                   {"at": list(sand_at), "material": "sand", "rate": 150.0, "radius": 10.0, "active": True},
                                   {"at": list(water_at), "material": "water", "rate": 70.0, "radius": 6.0, "active": True},
                               ],
                               "collider": True, "collider_interval": 0.3, "collider_step": 2, "glow": 2.2}))
    # Torches on the walls, and the light the lava gives.
    for i, (x, y) in enumerate([(-640, 160), (420, 90), (-80, -40)]):
        ents.append(ent(f"Torch{i}", transform=tr(x, y), unlit={}, particle_emitter=emitter(
            texture_id=F + "flame.png", emission_rate=26.0, max_particles=40, lifetime=[0.3, 0.6], speed=[20.0, 50.0],
            angle=[1.35, 1.8], size_start=[18.0, 24.0], size_end=[5.0, 7.0], blend_mode="Additive",
            color_curve=[[0.0] + emissive(lin(1.0, 0.85, 0.5, 0.0), 3.0), [0.2] + emissive(lin(1.0, 0.7, 0.3, 1.0), 3.0),
                         [1.0, 0.3, 0.06, 0.02, 0.0]], z_order=5),
                        point_light=point_light(lin(1.0, 0.65, 0.35), 1.3, 520, falloff=1.4, shadows=False)))
    lava = fs_local(410, 248)
    ents.append(ent("LavaLight", transform=tr(*lava),
                    point_light=point_light(lin(1.0, 0.4, 0.1), 2.2, 620, falloff=1.2, shadows=False, height=0.4)))
    oil = fs_local(390, 140)
    ents.append(ent("OilFire", transform=tr(*oil),
                    point_light=point_light(lin(1.0, 0.55, 0.2), 0.0, 600, falloff=1.2, shadows=False, height=0.4)))
    ents.append(ent("Keeper", transform=tr(), script=script("scripts/s113_falling_sands.lua")))
    ents += ui_captions("113   Falling Sands", "every grain its own   F fire   L lava   Tab captions")
    pp = post(
        bloom={"threshold": 1.0, "intensity": 0.6, "blur_size": 0.0},
        vignette={"intensity": 0.5, "smoothness": 0.5, "color": [0.02, 0.0, 0.0, 1.0]},
        grade={"brightness": 1.0, "contrast": 1.06, "saturation": 1.08, "tint": [1.0, 0.95, 0.88, 0.04]},
        chromatic={"strength": 0.0015, "on": False},
        hdr={"tonemap": "aces", "exposure": 1.05})
    return {"name": "113 - Falling Sands", "post_process": pp, "entities": ents}


