        (12.0, (0.12, 0.35, 0.85), (0.6, 0.8, 1.0), (0.85, 0.92, 1.0), 0.6, (1.0, 0.97, 0.9), 1.2),
        (15.5, (0.14, 0.34, 0.8), (0.75, 0.8, 0.95), (0.95, 0.92, 0.95), 0.55, (1.0, 0.88, 0.7), 1.1),
