def write_trophy_room_script():
    src = r'''-- 161 Trophy Room: two `toast_stack`s. Clicking a trophy unlocks its
-- achievement - `Toast.show(stack, title, text, icon)` - and everyday
-- notices come along on their own; the engine slides each in from its
-- corner, stacks them, waits and slides them away. This script is on the
-- achievements stack, so `on_toast` reaches it as each one appears.

script = { tick_rate = 60 }

local nav = require("nav")
local SCENE = "scenes/161-trophy-room.scene"
local ICONS = "sprites/trophyroom/icon_"
local TROPHIES = __TROPHIES__
local NOTES = __NOTES__
local status
local captions = true
local achievements, notices
local unlocked, count = {}, 0
local next_note, note_i = 1.5, 1
local next_unlock = 1.0
local shown = 0

local function unlock(i)
    local t = TROPHIES[i]
    if unlocked[i] then return end
    unlocked[i] = true
    count = count + 1
    local e = Entity.find_by_name(t[1])
    Outline.set(e, "enabled", true)
    Toast.show(achievements, "Unlocked: " .. t[2], t[3], ICONS .. t[4] .. ".png")
end

function init(entity)
    status = Entity.find_by_name("Status")
    achievements = entity
    notices = Entity.find_by_name("Notices")
end

function on_toast(entity)
    shown = shown + 1
end

function update(entity, dt)
    nav.tick(SCENE)
    if Input.is_key_just_pressed("Tab") then captions = nav.toggle_ui_captions(captions) end
    if Input.is_mouse_left_just_pressed() then
        local mx, my = Input.get_mouse_world_position()
        for i, t in ipairs(TROPHIES) do
            if math.abs(mx - t[5]) < 44 and my > t[6] and my < t[6] + 102 then
                unlock(i)
                next_unlock = 3.0
            end
        end
    end
    next_note = next_note - dt
    if next_note <= 0 then
        local n = NOTES[note_i]
        Toast.show(notices, n[1], n[2], ICONS .. n[3] .. ".png")
        note_i = note_i % #NOTES + 1
        next_note = 2.6 + math.random() * 1.6
    end
    -- Without a click for a while, the next trophy unlocks by itself.
    next_unlock = next_unlock - dt
    if next_unlock <= 0 and count < #TROPHIES then
        for i = 1, #TROPHIES do
            if not unlocked[i] then unlock(i); break end
        end
        next_unlock = 3.0
    end
    UI.set_text(status, count .. " of " .. #TROPHIES .. " unlocked")
end
'''
    tro = "{\n" + "\n".join('    { "%s", "%s", "%s", "%s", %.0f, %.0f },' % (n, title, text, icon, x, y)
                            for n, _, _, y, x, title, text, icon in TR_TROPHIES) + "\n}"
    notes = "{\n" + "\n".join('    { "%s", "%s", "%s" },' % n for n in TR_NOTES) + "\n}"
    src = src.replace("__TROPHIES__", tro).replace("__NOTES__", notes)
    (ASSETS / "scripts" / "s161_trophy_room.lua").write_text(src, encoding="utf-8", newline="\n")

# The pinball table of 162 Instant Replay, shared by its art and its scene:
# world units, the playfield centred on the screen.
PB_BUMPERS = ((-100.0, 140.0), (60.0, 140.0), (-20.0, 50.0))
PB_LANES = (-130.0, -60.0, 10.0)
PB_LANE_Y = 285.0
PB_POSTS = (-165.0, -95.0, -25.0, 45.0)
PB_SLING_L = ((-205.0, -80.0), (-205.0, -165.0), (-150.0, -200.0))
PB_SLING_R = ((165.0, -80.0), (165.0, -165.0), (110.0, -200.0))
PB_PIVOTS = ((-130.0, -245.0), (90.0, -245.0))
PB_RAILS = (  # every wall the ball meets, as segments
    ((-245.0, -150.0), (-245.0, 300.0)),
    ((-245.0, 300.0), (-200.0, 345.0)),
    ((-200.0, 345.0), (190.0, 345.0)),
    ((190.0, 345.0), (250.0, 285.0)),
    ((250.0, 285.0), (250.0, -360.0)),
    ((203.0, 140.0), (203.0, -360.0)),
    ((-245.0, -150.0), (-135.0, -240.0)),
    ((198.0, -150.0), (95.0, -240.0)),
)


# ── 162 Instant Replay ───────────────────────────────────────────────────
# A pinball table built from core physics - flippers on motored revolute
# joints, bumpers and slingshots the script kicks, a ccd ball - and an
# input replay: R records a run from a fresh table, P plays it back exactly
# as it happened. The replay keeps each frame's input and frame time
# (`Replay.*`, `input::replay`); the table, its physics and this script do
# the rest, the same way twice.

def pb_body(kind, mass=0.0):
    return {"body_type": kind, "mass": mass, "gravity_scale": 1.0, "linear_damping": 0.0,
            "angular_damping": 0.0, "fixed_rotation": False, "ccd": True}


def pb_static(shape, restitution=0.3, friction=0.2):
    return {"shape": shape, "offset": [0.0, 0.0], "is_sensor": False,
            "friction": friction, "restitution": restitution, "density": 1.0}


def pb_sling(pts):
    """A slingshot's sprite box (as the art cuts it) and its collider."""
    xs, ys = [p[0] for p in pts], [p[1] for p in pts]
    x0, y1 = min(xs) - 6, max(ys) + 6
    w, h = int(max(xs) - x0 + 6), int(y1 - min(ys) + 6)
    cx, cy = x0 + w / 2.0, y1 - h / 2.0
    return (cx, cy), (w, h), [[x - cx, y - cy] for x, y in pts]


def instant_replay():
    import math
    C = "sprites/pinball/"
    ents = [camera()]
    ents.append(ent("Cabinet", transform=tr(0, 0), sprite=sprite(C + "cabinet.png", (1280, 720), z=-100)))
    ents.append(ent("Playfield", transform=tr(0, 0), sprite=sprite(C + "playfield.png", (520, 720), z=-50)))
    # The rails: a static box along every segment the art draws.
    for i, ((x0, y0), (x1, y1)) in enumerate(PB_RAILS):
        length = math.hypot(x1 - x0, y1 - y0)
        ents.append(ent(f"Rail{i}", transform=tr((x0 + x1) / 2, (y0 + y1) / 2, math.atan2(y1 - y0, x1 - x0)),
                        rigid_body=pb_body("Static"),
                        collider=pb_static({"Box": {"width": length + 10.0, "height": 12.0}})))
    # The plunger's stop at the foot of the launch lane.
    ents.append(ent("LaneFloor", transform=tr(227, -352), rigid_body=pb_body("Static"),
                    collider=pb_static({"Box": {"width": 46.0, "height": 12.0}}, 0.0)))
    for i, x in enumerate(PB_POSTS):
        ents.append(ent(f"Post{i}", transform=tr(x, PB_LANE_Y), rigid_body=pb_body("Static"),
                        collider=pb_static({"Circle": {"radius": 7.0}}, 0.5)))
    for i, x in enumerate(PB_LANES):
        ents.append(ent(f"Lane{i}", transform=tr(x, PB_LANE_Y), sprite=sprite(C + "light.png", (28, 28), lin(0.35, 0.25, 0.1), z=-40)))
    for i, (x, y) in enumerate(PB_BUMPERS):
        ents.append(ent(f"Bumper{i}", transform=tr(x, y), sprite=sprite(C + "bumper.png", (64, 64), lin(1.0, 0.35, 0.7), z=5),
                        rigid_body=pb_body("Static"), collider=pb_static({"Circle": {"radius": 30.0}}, 0.6)))
    for name, pts, tex in (("SlingL", PB_SLING_L, "sling_l.png"), ("SlingR", PB_SLING_R, "sling_r.png")):
        (cx, cy), (w, h), verts = pb_sling(pts)
        ents.append(ent(name, transform=tr(cx, cy), sprite=sprite(C + tex, (w, h), lin(0.3, 0.85, 1.0), z=4),
                        rigid_body=pb_body("Static"),
                        collider=pb_static({"ConvexPolygon": {"vertices": verts}}, 0.5)))
    # The flippers: dynamic, each on a revolute joint to a static pivot, its
    # motor driving it up or down between two limits.
    # The right one is drawn mirrored rather than scaled by -1, which the
    # physics would read; both turn +-0.5 from level, so one pair of limits.
    for name, (px_, py_), side, tex in (("FlipperL", PB_PIVOTS[0], 1.0, "flipper.png"),
                                        ("FlipperR", PB_PIVOTS[1], -1.0, "flipper_r.png")):
        rest = -0.5 * side
        cx = px_ + side * 45.0 * math.cos(rest)
        cy = py_ + side * 45.0 * math.sin(rest)
        ents.append(ent(name + "Pivot", transform=tr(px_, py_), rigid_body=pb_body("Static")))
        ents.append(ent(name, transform=tr(cx, cy, rest),
                        sprite=sprite(C + tex, (110, 26), z=6),
                        rigid_body=pb_body("Dynamic", 3.0),
                        collider=pb_static({"Box": {"width": 100.0, "height": 16.0}}, 0.1, 0.4),
                        joint={"target_entity": name + "Pivot", "collide_connected": False, "joint_type": {"Revolute": {
                            "anchor": [-45.0 * side, 0.0], "anchor_b": [0.0, 0.0], "limits": [-0.5, 0.5],
                            "motor_speed": 0.01, "motor_max_torque": 60000000.0}}}))
    ents.append(ent("Plunger", transform=tr(227, -372), sprite=sprite(C + "bar.png", (26, 30), lin(0.8, 0.82, 0.9), z=3)))
    ents.append(ent("Ball", transform=tr(227, -334), sprite=sprite(C + "ball.png", (24, 24), z=10),
                    rigid_body=pb_body("Dynamic", 1.0),
                    collider=pb_static({"Circle": {"radius": 11.0}}, 0.3, 0.1)))
    # The backglass panels: the score on the left, the replay on the right.
    L, R = -455.0, 455.0
    gold, violet, pale = lin(1.0, 0.82, 0.4), lin(0.75, 0.6, 1.0), lin(0.88, 0.88, 0.95)
    ents.append(ent("ScoreLabel", transform=tr(L, 185), text=text("SCORE", 1.4, violet, align="center")))
    ents.append(ent("Score", transform=tr(L, 135), text=text("0", 3.0, gold, align="center")))
    ents.append(ent("BallLabel", transform=tr(L, 55), text=text("BALL 1 OF 3", 1.2, pale, align="center")))
    ents.append(ent("Message", transform=tr(L, -40), text=text("", 1.3, gold, align="center", wrap=250)))
    ents.append(ent("HelpL", transform=tr(L, -215), text=text(
        "Left / Right   flippers\nSpace   hold to pull the plunger", 0.9, pale, align="center", wrap=260)))
    ents.append(ent("ReplayLabel", transform=tr(R, 185), text=text("INSTANT REPLAY", 1.4, violet, align="center")))
    ents.append(ent("RecLamp", transform=tr(R - 70, 130), sprite=sprite(C + "light.png", (26, 26), lin(0.3, 0.05, 0.05), z=5)))
    ents.append(ent("ReplayState", transform=tr(R + 15, 130), text=text("READY", 1.6, pale, align="center")))
    ents.append(ent("BarFrame", transform=tr(R, 80), sprite=sprite(C + "bar_frame.png", (268, 22), lin(0.75, 0.6, 1.0), z=4)))
    ents.append(ent("Bar", transform=tr(R, 80), sprite=sprite(C + "bar.png", (260, 14), lin(1.0, 0.82, 0.4), z=5,
                                                               fill={"mode": "bar", "amount": 0.0, "from": "left"})))
    ents.append(ent("ReplayInfo", transform=tr(R, 25), text=text("", 0.95, pale, align="center", wrap=260)))
    ents.append(ent("HelpR", transform=tr(R, -215), text=text(
        "R   record a run from a fresh table\nP   play it back - P again takes over", 0.9, pale, align="center", wrap=260)))
    ents.append(ent("Table", transform=tr(), script=script("scripts/s162_instant_replay.lua")))
    ents += ui_captions("162   Instant Replay", "Left / Right flippers   Space plunger   R record   P play back   Tab captions")
    pp = post(bloom={"threshold": 0.8, "intensity": 0.5, "blur_size": 0.0},
              vignette={"intensity": 0.45, "smoothness": 0.6, "color": [0.0, 0.0, 0.0, 1.0]},
              chromatic={"strength": 0.0015, "on": False})
    return {"name": "162 - Instant Replay", "post_process": pp, "entities": ents}


def write_instant_replay_script():
    src = r'''-- 162 Instant Replay: a pinball table and an input replay. R records a
-- run from a freshly loaded table; P loads it again and plays the recording
-- back - every frame's input and frame time, so the physics and this script
-- go exactly the same way. The keys that steer the replay are read through
-- `Replay.live_key`, the player's own keyboard: everything else reads the
-- replayed input while it plays, and the R and P presses never end up in it.

local nav = require("nav")
local SCENE = "scenes/162-instant-replay.scene"
local BUMPERS = __BUMPERS__
local LANES = __LANES__
local LANE_Y = __LANE_Y__
local SLINGS = __SLINGS__
local FLIP_SPEED = 26
local LANE_X, LANE_Y0 = 227, -334
local e = {}
local captions = true
local score, ball_no, balls = 0, 1, 3
local flash = { 0, 0, 0 }
local sling_cool = { 0, 0 }
local bumper_cool = { 0, 0, 0 }
local lit = { false, false, false }
local lane_cool = { 0, 0, 0 }
local bonus_t = 0
local message, message_t = "", 0
local charge, launching = 0, false
local attract = true
local auto = { 0, 0 }
local auto_cool = { 0, 0 }
local auto_wait = 0
local over_t = 0
local rec_t, t = 0, 0

local function say(text, seconds)
    message, message_t = text, seconds
end

local function flipper(name, side, up)
    -- The motor turns the pivot relative to the flipper, so the flipper
    -- turns the other way: positive is down for the left flipper.
    local s = up and -FLIP_SPEED or FLIP_SPEED
    Physics.set_motor_speed(name, s * side)
end

local function reset_ball()
    Transform.set_position(e.Ball, LANE_X, LANE_Y0)
    Physics.set_velocity(e.Ball, 0, 0)
    charge = 0
end

local function kick(vx, vy, nx, ny, speed)
    -- Away along the normal, at least `speed`.
    local into = vx * nx + vy * ny
    if into < 0 then vx, vy = vx - 2 * into * nx, vy - 2 * into * ny end
    local along = vx * nx + vy * ny
    if along < speed then vx, vy = vx + (speed - along) * nx, vy + (speed - along) * ny end
    Physics.set_velocity(e.Ball, vx, vy)
end

function init(entity)
    for _, n in ipairs({ "Ball", "FlipperL", "FlipperR", "Score", "BallLabel", "Message", "RecLamp", "ReplayState",
        "Bar", "ReplayInfo", "Plunger", "Status", "Lane0", "Lane1", "Lane2", "Bumper0", "Bumper1", "Bumper2", "SlingL", "SlingR" }) do
        e[n] = Entity.find_by_name(n)
    end
    Physics.set_gravity(0, -6)
    flipper("FlipperL", 1, false)
    flipper("FlipperR", -1, false)
end

local function replay_controls(dt)
    local status = Replay.status()
    if status == "recording" then rec_t = rec_t + dt end
    if Replay.live_key("R") then
        if status == "recording" then
            Replay.stop()
        else
            Replay.record()
            Scene.load(SCENE)
        end
    elseif Replay.live_key("P") then
        if status == "playing" then
            Replay.stop()   -- take over: live input from here on
        elseif Replay.frames() > 0 then
            Replay.play()
            Scene.load(SCENE)
        end
    end
    -- Two minutes is a long run; stop there.
    if status == "recording" and rec_t > 120 then Replay.stop() end
end

local function replay_panel()
    local status = Replay.status()
    local frames = math.floor(Replay.frames())
    local seconds = string.format("%.1f", frames / 60)
    if status == "recording" then
        local on = math.floor(t * 2.5) % 2 == 0
        Sprite.set_color(e.RecLamp, on and 1.0 or 0.3, 0.05, 0.05, 1)
        Text.set(e.ReplayState, "REC  " .. string.format("%.1f", rec_t) .. " s")
        Sprite.set_fill(e.Bar, 0)
        Text.set(e.ReplayInfo, "Recording from a fresh table. R stops.")
    elseif status == "playing" then
        Sprite.set_color(e.RecLamp, 0.25, 1.0, 0.4, 1)
        Text.set(e.ReplayState, "REPLAY")
        Sprite.set_fill(e.Bar, Replay.progress())
        Text.set(e.ReplayInfo, "Frame " .. math.floor(Replay.progress() * frames + 0.5) .. " of " .. frames
            .. " - played back exactly. P takes over.")
    else
        Sprite.set_color(e.RecLamp, 0.3, 0.05, 0.05, 1)
        Sprite.set_fill(e.Bar, status == "finished" and 1 or 0)
        if status == "finished" then
            Text.set(e.ReplayState, "THE END")
            Text.set(e.ReplayInfo, "That was the replay. P plays it again, R records a new run.")
        elseif frames > 0 then
            Text.set(e.ReplayState, "READY")
            Text.set(e.ReplayInfo, "A run of " .. seconds .. " s is kept. P plays it back.")
        else
            Text.set(e.ReplayState, "READY")
            Text.set(e.ReplayInfo, "R records a run from a fresh table.")
        end
    end
end

local function auto_play(dt, bx, by, vx, vy)
    -- Attract mode: flip when the ball comes down onto a flipper, launch
    -- when it waits in the lane. Any key of the player's turns it off.
    for i = 1, 2 do
        auto[i] = math.max(0, auto[i] - dt)
        auto_cool[i] = math.max(0, auto_cool[i] - dt)
    end
    if by < -205 and by > -300 and vy < 80 then
        local side = bx < -20 and 1 or 2
        if auto_cool[side] == 0 and math.abs(bx - (side == 1 and -75 or 35)) < 70 then
            auto[side], auto_cool[side] = 0.22, 0.6
        end
    end
end

function update(entity, dt)
    nav.tick(SCENE)
    if Input.is_key_just_pressed("Tab") then captions = nav.toggle_ui_captions(captions) end
    t = t + dt
    replay_controls(dt)
    replay_panel()

    local bx, by = Transform.get_position(e.Ball)
    local vx, vy = Physics.get_velocity(e.Ball)
    if Input.is_key_just_pressed("Left") or Input.is_key_just_pressed("Right") or Input.is_key_just_pressed("Space") then
        attract = false
    end
    if attract then auto_play(dt, bx, by, vx, vy) end
    local left = Input.is_key_pressed("Left") or Input.is_key_pressed("A") or (attract and auto[1] > 0)
    local right = Input.is_key_pressed("Right") or Input.is_key_pressed("D") or (attract and auto[2] > 0)
    flipper("FlipperL", 1, left)
    flipper("FlipperR", -1, right)

    -- The plunger: hold Space while the ball waits in the lane.
    local waiting = bx > 205 and by < -300 and math.abs(vy) < 30
    local pull = Input.is_key_pressed("Space")
    if attract and waiting then
        auto_wait = auto_wait + dt
        pull = auto_wait < 1.6
        if not pull then auto_wait = 0 end
    end
    if waiting and pull then
        charge = math.min(1, charge + dt * 1.1)
    elseif waiting and charge > 0 then
        Physics.set_velocity(e.Ball, 0, 760 + 520 * charge)
        charge = 0
    end
    Transform.set_position(e.Plunger, LANE_X, -372 - charge * 14)

    -- Bumpers kick the ball away and flash.
    for i, b in ipairs(BUMPERS) do
        bumper_cool[i] = math.max(0, bumper_cool[i] - dt)
        local dx, dy = bx - b[1], by - b[2]
        local d = math.sqrt(dx * dx + dy * dy)
        if d < 44 and bumper_cool[i] == 0 then
            kick(vx, vy, dx / d, dy / d, 620)
            bumper_cool[i], flash[i] = 0.12, 1
            score = score + 100
        end
        flash[i] = math.max(0, flash[i] - dt * 5)
        local f = flash[i]
        Sprite.set_color(e["Bumper" .. (i - 1)], 1.0 + f * 2, 0.35 + f * 2, 0.7 + f * 1.5, 1)
    end
    -- Slingshots kick off their long face.
    for i, s in ipairs(SLINGS) do
        sling_cool[i] = math.max(0, sling_cool[i] - dt)
        local ax, ay, cx, cy = s[1], s[2], s[3], s[4]
        local ex, ey = cx - ax, cy - ay
        local len = math.sqrt(ex * ex + ey * ey)
        local ux, uy = ex / len, ey / len
        local nx, ny = uy * s[5], -ux * s[5]
        local along = (bx - ax) * ux + (by - ay) * uy
        local off = (bx - ax) * nx + (by - ay) * ny
        local name = i == 1 and "SlingL" or "SlingR"
        if along > 8 and along < len - 8 and off < 17 and off > 0 and sling_cool[i] == 0 then
            kick(vx, vy, nx, ny, 480)
            sling_cool[i] = 0.15
            score = score + 10
            Sprite.set_color(e[name], 1.2, 1.4, 1.6, 1)
        elseif sling_cool[i] == 0 then
            Sprite.set_color(e[name], 0.3, 0.85, 1.0, 1)
        end
    end
    -- Rollover lanes: light all three for a bonus.
    for i, x in ipairs(LANES) do
        lane_cool[i] = math.max(0, lane_cool[i] - dt)
        if math.abs(bx - x) < 22 and math.abs(by - LANE_Y) < 16 and lane_cool[i] == 0 then
            lane_cool[i] = 0.5
            if not lit[i] then lit[i] = true; score = score + 500 end
        end
    end
    if lit[1] and lit[2] and lit[3] then
        score = score + 5000
        lit = { false, false, false }
        bonus_t = 1.2
        say("LANES COMPLETE\n+5000", 2)
    end
    bonus_t = math.max(0, bonus_t - dt)
    for i = 1, 3 do
        local on = lit[i] or (bonus_t > 0 and math.floor(bonus_t * 8) % 2 == 0)
        if on then
            Sprite.set_color(e["Lane" .. (i - 1)], 1.6, 1.2, 0.4, 1)
        else
            Sprite.set_color(e["Lane" .. (i - 1)], 0.35, 0.25, 0.1, 1)
        end
    end

    -- The drain.
    if by < -380 then
        if ball_no >= balls then
            say("GAME OVER\nscore " .. score, 3)
            over_t = 3
            score, ball_no = 0, 1
        else
            ball_no = ball_no + 1
            say("BALL " .. ball_no, 1.5)
        end
        reset_ball()
    end
    over_t = math.max(0, over_t - dt)

    message_t = math.max(0, message_t - dt)
    Text.set(e.Message, message_t > 0 and message or "")
    Text.set(e.Score, tostring(score))
    Text.set(e.BallLabel, "BALL " .. ball_no .. " OF " .. balls)
    UI.set_text(e.Status, attract and "Attract mode - press a flipper to play" or "")
end
'''
    def lua(v):
        return "{ " + ", ".join(lua(x) if isinstance(x, (tuple, list)) else ("%.1f" % x) for x in v) + " }"
    # A slingshot's long face, from its top to its foot, and which way is out.
    slings = "{ " + ", ".join(lua((p[0][0], p[0][1], p[2][0], p[2][1], side)) for p, side in ((PB_SLING_L, -1.0), (PB_SLING_R, 1.0))) + " }"
    src = (src.replace("__BUMPERS__", lua(PB_BUMPERS)).replace("__LANES__", lua(PB_LANES))
           .replace("__LANE_Y__", "%.1f" % PB_LANE_Y).replace("__SLINGS__", slings))
    (ASSETS / "scripts" / "s162_instant_replay.lua").write_text(src, encoding="utf-8", newline="\n")



