def write_post_defaults(post_off):
    """`scripts/post_defaults.lua`: the post effects each scene starts with
    off. Keys 1-4 toggle an effect and the status line names what is on, and
    a script cannot ask the renderer, so `nav.post_all_on(SCENE)` reads this.
    It used to assume all four were on, so in the 79 scenes authoring
    chromatic off the line said "on" and the first press of 4 did nothing."""
    lines = ["-- Generated by tools/gen_scenes.py: the post effects each scene starts",
             "-- with off, read by nav.post_all_on. Do not edit; re-run the generator.",
             "return {"]
    for rel in sorted(post_off):
        names = ", ".join(json.dumps(n) for n in post_off[rel])
        lines.append(f'    ["{rel}"] = {{ {names} }},')
    lines.append("}")
    (ASSETS / "scripts" / "post_defaults.lua").write_text("\n".join(lines) + "\n", encoding="utf-8", newline="\n")


